import prisma from '../src/prisma';

async function debug() {
  console.log('--- Google Drive Debugging ---');
  const settings = await prisma.systemSetting.findMany({
    where: { key: { in: ['googleDriveEnabled', 'googleDriveFolderId', 'googleDriveCredentials'] } }
  });

  const settingsMap = settings.reduce((acc, curr) => {
    acc[curr.key] = curr.value;
    return acc;
  }, {} as Record<string, string>);

  console.log('Enabled:', settingsMap['googleDriveEnabled']);
  console.log('Folder ID:', settingsMap['googleDriveFolderId']);
  
  if (settingsMap['googleDriveCredentials']) {
    try {
      const creds = JSON.parse(settingsMap['googleDriveCredentials']);
      console.log('Service Account Email in JSON:', creds.client_email);
    } catch (e) {
      console.log('Credentials JSON is INVALID (could not parse)');
    }
  } else {
    console.log('Credentials JSON is MISSING');
  }
}

debug().catch(console.error).finally(() => prisma.$disconnect());

require('dotenv').config();
const jwt = require('jsonwebtoken');

// Ensure this matches the secret used in utils/license.util.ts
const LICENSE_SECRET = process.env.LICENSE_SECRET || 'edu-tracker-master-license-secret-key-2026';

function generateLicense(clientName, type, expiresInDays) {
  const payload = {
    clientName,
    type,
  };

  const expiresInSeconds = expiresInDays * 24 * 60 * 60;
  
  const token = jwt.sign(payload, LICENSE_SECRET, { expiresIn: expiresInSeconds });
  
  console.log('==========================================');
  console.log('🎉 LICENSE GENERATED SUCCESSFULLY 🎉');
  console.log('==========================================');
  console.log(`Client Name  : ${clientName}`);
  console.log(`License Type : ${type}`);
  console.log(`Valid for    : ${expiresInDays} days`);
  console.log('------------------------------------------');
  console.log('LICENSE KEY (Copy below):');
  console.log(token);
  console.log('==========================================');
  return token;
}

// Read arguments from command line
const args = process.argv.slice(2);
const clientName = args[0] || 'Demo School';
const type = args[1] || 'annual'; // 'trial', 'annual', 'lifetime'
const expiresInDays = parseInt(args[2], 10) || 365;

generateLicense(clientName, type, expiresInDays);

import { google } from 'googleapis';
import prisma from '../src/prisma';

async function listVisibleFiles() {
  const settings = await prisma.systemSetting.findMany({
    where: { key: { in: ['googleDriveCredentials'] } }
  });

  const credentialsJson = settings.find(s => s.key === 'googleDriveCredentials')?.value;
  if (!credentialsJson) {
    console.log('No credentials found');
    return;
  }

  const credentials = JSON.parse(credentialsJson);
  const auth = new google.auth.GoogleAuth({
    credentials,
    scopes: ['https://www.googleapis.com/auth/drive.readonly', 'https://www.googleapis.com/auth/drive.metadata.readonly'],
  });

  const drive = google.drive({ version: 'v3', auth });

  console.log('Listing all folders/files shared with this Service Account...');
  const res = await drive.files.list({
    pageSize: 10,
    fields: 'files(id, name, mimeType)',
    q: "mimeType = 'application/vnd.google-apps.folder'",
    supportsAllDrives: true,
    includeItemsFromAllDrives: true,
  });

  const files = res.data.files;
  if (files?.length) {
    console.log('Found Folders:');
    files.forEach((file: any) => {
      console.log(`${file.name} (ID: ${file.id})`);
    });
  } else {
    console.log('No folders shared with this Service Account found.');
  }
}

listVisibleFiles().catch(console.error).finally(() => prisma.$disconnect());

import prisma from '../src/prisma';

async function repopulate() {
  console.log('--- Repopulating CLASS_1 ---');

  // 1. Ensure Class exists
  const className = 'CLASS_1';
  const schoolClass = await prisma.schoolClass.upsert({
    where: { name: className },
    update: {},
    create: { name: className }
  });

  // 2. Add Sections A and B
  const sections = ['A', 'B'];
  for (const s of sections) {
    await prisma.classSection.upsert({
      where: { className_section: { className, section: s } },
      update: {},
      create: { className, section: s }
    });
  }
  console.log('Sections A and B restored.');

  // 3. Add Sample Students
  const sampleStudents = [
    { studentId: 'STU-2026-010', fullName: 'Emily Davis', rollNumber: '01', section: 'A' },
    { studentId: 'STU-2026-011', fullName: 'Noah Smith', rollNumber: '02', section: 'A' },
    { studentId: 'STU-2026-012', fullName: 'Sophia Brown', rollNumber: '01', section: 'B' },
    { studentId: 'STU-2026-013', fullName: 'Liam Wilson', rollNumber: '02', section: 'B' },
    { studentId: 'STU-2026-014', fullName: 'Ava Martinez', rollNumber: '03', section: 'A' },
  ];

  for (const stu of sampleStudents) {
    await prisma.student.upsert({
      where: { studentId: stu.studentId },
      update: { className, section: stu.section, rollNumber: stu.rollNumber },
      create: {
        ...stu,
        className,
        gender: Math.random() > 0.5 ? 'FEMALE' : 'MALE',
        email: `${stu.studentId.toLowerCase()}@example.com`
      }
    });
  }
  console.log(`${sampleStudents.length} students restored to CLASS_1.`);
}

repopulate().catch(console.error).finally(() => prisma.$disconnect());

