  const results: any[] = [];
  const validRecords: any[] = [];
  const failedRecords: any[] = [];

  await new Promise((resolve, reject) => {
    fs.createReadStream(req.file!.path)
      .pipe(csv())
      .on('data', (data) => results.push(data))
      .on('end', resolve)
      .on('error', reject);
  });

  for (let i = 0; i < results.length; i++) {
