import { Response } from 'express';
import { asyncHandler } from '../utils/asyncHandler';
import { ApiError } from '../utils/apiError';
import { ApiResponse } from '../utils/apiResponse';
import prisma from '../prisma';
import bcrypt from 'bcryptjs';
import { AuthRequest } from '../middleware/auth.middleware';

/**
 * Get all users (staff)
 */
export const getUsers = asyncHandler(async (req: AuthRequest, res: Response) => {
  const users = await prisma.user.findMany({
    select: {
      id: true,
      email: true,
      name: true,
      role: true,
      nid: true,
      phone: true,
      address: true,
      canLogin: true,
      profileImage: true,
      createdAt: true,
    },
    orderBy: {
      createdAt: 'desc',
    },
  });

  return res.status(200).json(
    new ApiResponse(200, users, 'Users fetched successfully')
  );
});

/**
 * Create a new user (staff)
 */
export const createUser = asyncHandler(async (req: AuthRequest, res: Response) => {
  const { email, password, name, role, nid, phone, address, canLogin, profileImage } = req.body;

  if (!email || !role) {
    throw new ApiError(400, 'Email and role are required');
  }

  const existingUser = await prisma.user.findUnique({
    where: { email },
  });

  if (existingUser) {
    throw new ApiError(400, 'User with this email already exists');
  }

  let hashedPassword = null;
  if (canLogin && password) {
    hashedPassword = await bcrypt.hash(password, 10);
  }

  const user = await prisma.user.create({
    data: {
      email,
      password: hashedPassword,
      name,
      role,
      nid,
      phone,
      address,
      canLogin: !!canLogin,
      profileImage,
    },
    select: {
      id: true,
      email: true,
      name: true,
      role: true,
      nid: true,
      phone: true,
      address: true,
      canLogin: true,
      profileImage: true,
      createdAt: true,
    },
  });

  return res.status(201).json(
    new ApiResponse(201, user, 'User created successfully')
  );
});

/**
 * Update a user (staff)
 */
export const updateUser = asyncHandler(async (req: AuthRequest, res: Response) => {
  const { id } = req.params;
  const { email, name, role, password, nid, phone, address, canLogin, profileImage } = req.body;

  const userData: any = {
    email,
    name,
    role,
    nid,
    phone,
    address,
    canLogin: !!canLogin,
    profileImage,
  };

  if (password && canLogin) {
    userData.password = await bcrypt.hash(password, 10);
  } else if (!canLogin) {
    userData.password = null;
  }

  const user = await prisma.user.update({
    where: { id: parseInt(id) },
    data: userData,
    select: {
      id: true,
      email: true,
      name: true,
      role: true,
      nid: true,
      phone: true,
      address: true,
      canLogin: true,
      profileImage: true,
      createdAt: true,
    },
  });

  return res.status(200).json(
    new ApiResponse(200, user, 'User updated successfully')
  );
});

/**
 * Delete a user (staff)
 */
export const deleteUser = asyncHandler(async (req: AuthRequest, res: Response) => {
  const { id } = req.params;

  // Prevent self-deletion
  if (req.user?.id === parseInt(id)) {
    throw new ApiError(400, 'You cannot delete your own account');
  }

  await prisma.user.delete({
    where: { id: parseInt(id) },
  });

  return res.status(200).json(
    new ApiResponse(200, null, 'User deleted successfully')
  );
});

import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import { ApiError } from '../utils/apiError';
import { asyncHandler } from '../utils/asyncHandler';
import prisma from '../prisma';

const ACCESS_TOKEN_SECRET = process.env.ACCESS_TOKEN_SECRET as string;

export type Role = 'ADMIN' | 'PRINCIPAL' | 'TEACHER' | 'STAFF' | 'LIBRARIAN' | 'ACCOUNTANT' | 'CLERK' | 'SECURITY' | 'CLEANER';

export interface AuthUser {
  id: number;
  email: string;
  name: string | null;
  role: Role;
  profileImage: string | null;
}

export interface AuthRequest extends Request {
  user?: AuthUser;
}

export const authMiddleware = asyncHandler(
  async (req: AuthRequest, res: Response, next: NextFunction) => {
    let token = req.header('Authorization')?.replace('Bearer ', '');

    // Allow token to be passed via query string (useful for PDF export and direct print URLs)
    if (!token && req.query.token && typeof req.query.token === 'string') {
      token = req.query.token;
    }

    if (!token) {
      throw new ApiError(401, 'Authentication required');
    }

    try {
      const decoded = jwt.verify(token, ACCESS_TOKEN_SECRET) as { id: number };
      const user = await prisma.user.findUnique({
        where: { id: decoded.id },
        select: {
          id: true,
          email: true,
          name: true,
          role: true,
          profileImage: true,
        },
      });

      if (!user) {
        throw new ApiError(401, 'User not found');
      }

      req.user = user as AuthUser;
      next();
    } catch (error) {
      throw new ApiError(401, 'Invalid or expired token');
    }
  }
);

// Optional: Role-based authorization middleware
export const authorize = (...roles: string[]) => {
  return (req: AuthRequest, res: Response, next: NextFunction) => {
    if (!req.user || !roles.includes(req.user.role)) {
      throw new ApiError(403, 'You do not have permission to perform this action');
    }
    next();
  };
};

import { Request, Response, NextFunction } from 'express';
import { ApiError } from '../utils/apiError';

export const errorMiddleware = (
  err: any,
  req: Request,
  res: Response,
  next: NextFunction
) => {
  let { statusCode, message } = err;

  if (!(err instanceof ApiError)) {
    statusCode = err.statusCode || 500;
    message = err.message || 'Internal Server Error';
  }

  const response = {
    success: false,
    message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
    errors: err.errors || [],
  };

  res.status(statusCode).json(response);
};

import { Request, Response, NextFunction } from 'express';
import prisma from '../prisma';
import { verifyLicenseToken } from '../utils/license.util';

export const licenseCheckMiddleware = async (req: Request, res: Response, next: NextFunction) => {
  try {
    const licenseRecord = await prisma.systemSetting.findUnique({
      where: { key: 'LICENSE_KEY' }
    });

    if (!licenseRecord || !licenseRecord.value) {
      return res.status(402).json({ error: 'LICENSE_MISSING', message: 'System not activated. Please provide a valid license key.' });
    }

    const decoded = verifyLicenseToken(licenseRecord.value);

    if (!decoded) {
      return res.status(402).json({ error: 'LICENSE_EXPIRED', message: 'License key is invalid or has expired.' });
    }

    // Pass the license info along in case a route needs it
    (req as any).licenseInfo = decoded;
    next();
  } catch (error) {
    console.error('License verification error:', error);
    return res.status(500).json({ error: 'SERVER_ERROR', message: 'Failed to verify license status' });
  }
};

