"use client";

import React, { useState, useEffect, useMemo } from 'react';
import { Calendar as CalendarIcon, Save, CheckCircle, XCircle, Users, LayoutList, CheckSquare, Lock, Unlock } from 'lucide-react';
import toast from 'react-hot-toast';
import { useAppDispatch, useAppSelector } from '@/lib/hooks';
import { selectAllStudents, fetchStudents } from '@/lib/features/studentsSlice';
import { selectUser } from '@/lib/features/authSlice';
import { 
  selectAllAttendanceRecords, 
  addDailyRecordsBulkThunk,
  fetchAttendance,
  fetchAttendanceLockStatus,
  unlockAttendanceThunk,
  selectIsAttendanceLocked,
  AttendanceSummary
} from '@/lib/features/attendanceSlice';
import { fetchClassesOverview, selectClassesOverview } from '@/lib/features/classesSlice';
import { Attendance, AttendanceStatus } from '@/types/models';
import { selectClasses } from '@/lib/features/configSlice';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Select } from '@/components/ui/Select';

export default function AttendancePage() {
  const dispatch = useAppDispatch();
  const allStudents = useAppSelector(selectAllStudents);
  const CLASSES = useAppSelector(selectClasses);
  const classesOverview = useAppSelector(selectClassesOverview);
  
  const loadingAttendance = useAppSelector((state) => state.attendance.loading);
  const currentUser = useAppSelector(selectUser);
  const isLocked = useAppSelector(selectIsAttendanceLocked);

  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedClass, setSelectedClass] = useState<string>('');
  const [selectedSection, setSelectedSection] = useState<string>('');
  
  // Pagination state
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;
  
  useEffect(() => {
    dispatch(fetchStudents());
    dispatch(fetchAttendance());
    dispatch(fetchClassesOverview());
  }, [dispatch]);

  useEffect(() => {
    if (selectedClass && selectedSection && selectedDate) {
      dispatch(fetchAttendanceLockStatus({
        className: selectedClass,
        section: selectedSection,
        date: selectedDate
      }));
    }
  }, [dispatch, selectedClass, selectedSection, selectedDate]);

  const availableSections = useMemo(() => {
    const classData = classesOverview.find(c => c.className === selectedClass);
    return classData ? classData.sections.map(s => ({ value: s.section, label: `Sec ${s.section}` })).sort((a, b) => a.value.localeCompare(b.value)) : [];
  }, [classesOverview, selectedClass]);

  // Filter students based on selected class and section
  const classStudents = useMemo(() => {
    if (!selectedClass || !selectedSection) return [];
    return allStudents
      .filter(student => student.className === selectedClass && student.section === selectedSection)
      .sort((a, b) => a.rollNumber.localeCompare(b.rollNumber));
  }, [allStudents, selectedClass, selectedSection]);

  // Paginated students
  const paginatedStudents = useMemo(() => {
    const startIndex = (currentPage - 1) * itemsPerPage;
    return classStudents.slice(startIndex, startIndex + itemsPerPage);
  }, [classStudents, currentPage]);

  const totalPages = Math.ceil(classStudents.length / itemsPerPage);

  useEffect(() => {
    setSelectedSection('');
    setCurrentPage(1);
  }, [selectedClass]);

  useEffect(() => {
    setCurrentPage(1);
  }, [selectedSection]);

  // Get records from Redux for the currently selected date
  const allRecords = useAppSelector(selectAllAttendanceRecords);
  const storeRecords = useMemo(() => 
    allRecords.filter(record => record.date === selectedDate), 
  [allRecords, selectedDate]);

  // Local state to manage toggles before saving
  const [localAttendance, setLocalAttendance] = useState<Record<number, AttendanceStatus>>({});
  const [isDirty, setIsDirty] = useState(false);

  // Sync local attendance state when selectedDate, storeRecords, or classStudents change
  useEffect(() => {
    const attendanceMap: Record<number, AttendanceStatus> = {};
    
    classStudents.forEach(student => {
      const record = storeRecords.find(r => r.studentId === student.id);
      if (record) {
        attendanceMap[student.id] = record.status;
      }
    });

    setLocalAttendance(attendanceMap);
    setIsDirty(false);
  }, [storeRecords, selectedDate, classStudents]);

  const handleStatusChange = (studentId: number, status: AttendanceStatus) => {
    setLocalAttendance(prev => ({
      ...prev,
      [studentId]: status
    }));
    setIsDirty(true);
  };

  const handleMarkAll = (status: AttendanceStatus) => {
    const newMap: Record<number, AttendanceStatus> = {};
    classStudents.forEach(student => {
      newMap[student.id] = status;
    });
    setLocalAttendance(newMap);
    setIsDirty(true);
  };

  const isAllMarked = useMemo(() => {
    return classStudents.length > 0 && classStudents.every(student => !!localAttendance[student.id]);
  }, [classStudents, localAttendance]);

  const handleSave = () => {
    if (!isAllMarked) {
      toast.error('All students in the section must be marked before saving.');
      return;
    }

    const recordsToSave: Partial<Attendance>[] = classStudents.map(student => {
      const existingRecord = storeRecords.find(r => r.studentId === student.id);
      return {
        id: existingRecord?.id,
        studentId: student.id,
        date: selectedDate,
        status: localAttendance[student.id],
      };
    });

    dispatch(addDailyRecordsBulkThunk(recordsToSave))
      .unwrap()
      .then(() => {
        toast.success('Attendance records updated and locked for this date');
      })
      .catch((err) => toast.error(typeof err === 'string' ? err : 'Failed to save attendance'));
    setIsDirty(false);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* Header Section */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
        <div>
          <h1 className="text-3xl font-bold text-slate-900 tracking-tight flex items-center gap-3">
            Daily Attendance
          </h1>
          <p className="text-slate-500 font-medium mt-1">Record and manage daily student presence by class.</p>
        </div>
        
        <div className="flex flex-col sm:flex-row items-center gap-3 w-full md:w-auto bg-white p-2 rounded-xl border border-slate-200 shadow-sm">
          <Select 
            placeholder="Select Class"
            value={selectedClass}
            onChange={(e) => setSelectedClass(e.target.value)}
            options={CLASSES}
            className="!w-full sm:!w-40 h-10"
          />

          <div className="h-6 w-[1px] bg-slate-200 hidden sm:block"></div>

          <Select 
            placeholder="Section"
            value={selectedSection}
            onChange={(e) => setSelectedSection(e.target.value)}
            disabled={!selectedClass || availableSections.length === 0}
            options={availableSections}
            className="!w-full sm:!w-32 h-10"
          />

          <div className="h-6 w-[1px] bg-slate-200 hidden sm:block"></div>

          <div className="relative w-full sm:w-44">
            <CalendarIcon className="absolute left-3 top-1/2 -translate-y-1/2 text-primary" size={16} />
            <input
              type="date"
              value={selectedDate}
              onChange={(e) => setSelectedDate(e.target.value)}
              className="w-full bg-slate-50 border-none rounded-lg pl-10 pr-4 py-2 text-sm text-slate-900 font-semibold focus:ring-2 focus:ring-primary/20 transition-standard cursor-pointer h-10"
            />
          </div>
        </div>
      </div>

      {/* Main Content Section */}
      <Card className="border-slate-200/60 shadow-sm overflow-hidden p-0 flex flex-col min-h-[400px]">
        <CardHeader className="flex flex-col sm:flex-row items-center justify-between border-b border-slate-100 bg-slate-50/50 p-6">
          <CardTitle className="text-slate-900 flex items-center gap-2">
            <Users size={20} className="text-primary" />
            {selectedClass && selectedSection ? `${CLASSES.find(c => c.value === selectedClass)?.label} - Sec ${selectedSection} Students` : 'Class Roster'}
            {isLocked && (
              <span className="ml-2 inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-bold bg-amber-100 text-amber-700 border border-amber-200">
                <Lock size={12} /> Locked
              </span>
            )}
          </CardTitle>
          
          {selectedClass && selectedSection && classStudents.length > 0 && (
            <div className="flex gap-2 items-center">
              {isLocked && (currentUser?.role === 'ADMIN' || currentUser?.role === 'PRINCIPAL') && (
                <Button 
                  variant="outline" 
                  size="sm" 
                  className="bg-white hover:bg-amber-50 hover:text-amber-700 hover:border-amber-300 text-[11px] font-bold text-amber-600 border-amber-200"
                  onClick={() => {
                    dispatch(unlockAttendanceThunk({
                      className: selectedClass,
                      section: selectedSection,
                      date: selectedDate
                    })).unwrap().then(() => toast.success('Attendance unlocked successfully'));
                  }}
                >
                  <Unlock size={14} className="mr-1.5" /> Unlock
                </Button>
              )}
              <Button 
                variant="outline" 
                size="sm" 
                className="bg-white hover:bg-emerald-50 hover:text-emerald-600 hover:border-emerald-200 text-[11px] font-bold disabled:opacity-50 disabled:cursor-not-allowed"
                onClick={() => handleMarkAll('PRESENT')}
                disabled={isLocked}
              >
                <CheckCircle size={14} className="mr-1.5" /> Mark All Present
              </Button>
              <Button 
                variant="outline" 
                size="sm" 
                className="bg-white hover:bg-red-50 hover:text-red-600 hover:border-red-200 text-[11px] font-bold disabled:opacity-50 disabled:cursor-not-allowed"
                onClick={() => handleMarkAll('ABSENT')}
                disabled={isLocked}
              >
                <XCircle size={14} className="mr-1.5" /> Mark All Absent
              </Button>
            </div>
          )}
        </CardHeader>
        
        <CardContent className="p-0 flex-1 flex flex-col">
          {!selectedClass || !selectedSection ? (
            <div className="flex-1 flex flex-col items-center justify-center py-24 text-center">
              <div className="p-6 bg-slate-50 rounded-full text-slate-300 border border-slate-100 mb-4">
                <LayoutList size={48} />
              </div>
              <h3 className="text-slate-900 font-bold">Select a Class and Section</h3>
              <p className="text-slate-500 text-sm mt-1 max-w-[280px]">Choose a class and section from the header to start marking daily attendance records.</p>
            </div>
          ) : loadingAttendance ? (
            <div className="flex-1 flex flex-col items-center justify-center py-24">
              <div className="h-10 w-10 border-4 border-primary/20 border-t-primary rounded-full animate-spin"></div>
              <span className="mt-4 text-slate-400 font-medium text-sm">Fetching class data...</span>
            </div>
          ) : classStudents.length === 0 ? (
            <div className="flex-1 flex flex-col items-center justify-center py-24 text-center">
              <div className="p-6 bg-slate-50 rounded-full text-slate-300 border border-slate-100 mb-4">
                <Users size={48} />
              </div>
              <h3 className="text-slate-900 font-bold">Empty Class</h3>
              <p className="text-slate-500 text-sm mt-1 max-w-[280px]">There are no students registered in this class yet.</p>
            </div>
          ) : (
            <div className="flex flex-col h-full">
              <div className="overflow-x-auto max-h-[calc(100vh-320px)] custom-scrollbar">
                <table className="w-full text-left text-sm border-collapse min-w-[600px]">
                  <thead className="sticky top-0 z-10 bg-white shadow-[0_1px_0_0_rgba(0,0,0,0.05)]">
                    <tr className="bg-slate-50/50 border-b border-slate-100">
                      <th className="px-6 py-4 font-bold text-slate-600 uppercase tracking-wider text-[11px] w-24">Roll No</th>
                      <th className="px-6 py-4 font-bold text-slate-600 uppercase tracking-wider text-[11px]">Student Name</th>
                      <th className="px-6 py-4 font-bold text-slate-600 uppercase tracking-wider text-[11px]">Identification</th>
                      <th className="px-6 py-4 font-bold text-slate-600 uppercase tracking-wider text-[11px] text-center">Status Toggle</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50">
                    {paginatedStudents.map((student) => {
                      const currentStatus = localAttendance[student.id];
                      
                      return (
                        <tr key={student.id} className="hover:bg-slate-50/50 transition-standard group">
                          <td className="px-6 py-4 text-slate-900 font-bold font-mono">{student.rollNumber}</td>
                          <td className="px-6 py-4">
                            <div className="flex items-center gap-3">
                              <div className="h-8 w-8 rounded-full bg-slate-100 flex items-center justify-center text-slate-600 font-bold text-xs border border-slate-200">
                                {student.fullName.charAt(0)}
                              </div>
                              <span className="font-bold text-slate-900">{student.fullName}</span>
                            </div>
                          </td>
                          <td className="px-6 py-4">
                            <span className="text-xs font-bold text-slate-500 bg-slate-100 px-2 py-1 rounded border border-slate-200">
                              {student.studentId}
                            </span>
                          </td>
                          <td className="px-6 py-4">
                            <div className="flex items-center justify-center gap-2">
                              <button
                                onClick={() => handleStatusChange(student.id, 'PRESENT')}
                                disabled={isLocked}
                                className={`flex items-center gap-1.5 px-4 py-1.5 rounded-lg border text-xs font-bold transition-all duration-200 ${
                                  currentStatus === 'PRESENT'
                                    ? 'bg-emerald-500 border-emerald-600 text-white shadow-md shadow-emerald-100'
                                    : 'bg-white border-slate-200 text-slate-400 hover:bg-slate-50'
                                } ${isLocked ? 'opacity-50 cursor-not-allowed' : ''}`}
                              >
                                <CheckCircle size={14} />
                                Present
                              </button>
                              <button
                                onClick={() => handleStatusChange(student.id, 'ABSENT')}
                                disabled={isLocked}
                                className={`flex items-center gap-1.5 px-4 py-1.5 rounded-lg border text-xs font-bold transition-all duration-200 ${
                                  currentStatus === 'ABSENT'
                                    ? 'bg-red-500 border-red-600 text-white shadow-md shadow-red-100'
                                    : 'bg-white border-slate-200 text-slate-400 hover:bg-slate-50'
                                } ${isLocked ? 'opacity-50 cursor-not-allowed' : ''}`}
                              >
                                <XCircle size={14} />
                                Absent
                              </button>
                            </div>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>

              {/* Pagination Footer */}
              {classStudents.length > 0 && (
                <div className="px-6 py-4 border-t border-slate-100 bg-slate-50/30 flex flex-col sm:flex-row items-center justify-between gap-4">
                  <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                    Showing {Math.min(classStudents.length, (currentPage - 1) * itemsPerPage + 1)}-{Math.min(classStudents.length, currentPage * itemsPerPage)} of {classStudents.length} Students
                  </div>
                  <div className="flex items-center gap-2">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
                      disabled={currentPage === 1}
                      className="bg-white h-8 text-[10px] font-black"
                    >
                      Prev
                    </Button>
                    <div className="flex items-center gap-1">
                      {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
                        <button
                          key={page}
                          onClick={() => setCurrentPage(page)}
                          className={`h-7 w-7 rounded-lg text-[10px] font-black transition-standard ${
                            currentPage === page
                              ? 'bg-primary text-white shadow-md shadow-blue-100'
                              : 'bg-white text-slate-500 border border-slate-200 hover:bg-slate-50'
                          }`}
                        >
                          {page}
                        </button>
                      ))}
                    </div>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
                      disabled={currentPage === totalPages}
                      className="bg-white h-8 text-[10px] font-black"
                    >
                      Next
                    </Button>
                  </div>
                </div>
              )}

              {/* Sticky Footer for Save Button */}
              <div className="mt-auto p-4 sm:p-6 bg-white border-t border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-4 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)]">
                <div className="flex items-center gap-2 text-slate-500 text-sm font-medium w-full sm:w-auto justify-center sm:justify-start">
                  <CheckSquare size={18} className="text-primary" />
                  <span>{Object.values(localAttendance).filter(v => v === 'PRESENT').length} students present today</span>
                </div>
                <Button 
                  onClick={handleSave} 
                  disabled={!isDirty || !isAllMarked || isLocked}
                  className={`w-full sm:w-auto px-8 py-2.5 min-h-[44px] shadow-lg transition-all ${isDirty && isAllMarked && !isLocked ? 'shadow-blue-200 scale-100' : 'shadow-none scale-95 opacity-80 cursor-not-allowed'}`}
                >
                  <Save size={18} className="mr-2" />
                  Save Class Records
                </Button>
              </div>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { useAppDispatch, useAppSelector } from '@/lib/hooks';
import { fetchAuditLogs, selectAuditLogs, selectAuditLoading, selectAuditTotal } from '@/lib/features/auditSlice';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card';
import { Select } from '@/components/ui/Select';
import { Button } from '@/components/ui/Button';
import { 
  History, 
  User as UserIcon, 
  Activity, 
  Database, 
  Calendar,
  Search,
  ArrowRight,
  FilterX
} from 'lucide-react';
import { format } from 'date-fns';

export default function AuditPage() {
  const dispatch = useAppDispatch();
  const logs = useAppSelector(selectAuditLogs);
  const loading = useAppSelector(selectAuditLoading);
  const total = useAppSelector(selectAuditTotal);

  const [filters, setFilters] = useState({
    action: '',
    entityType: '',
    performedBy: '',
  });

  const [limit] = useState(50);
  const [offset, setOffset] = useState(0);

  useEffect(() => {
    dispatch(fetchAuditLogs({ ...filters, limit, offset, performedBy: filters.performedBy ? Number(filters.performedBy) : undefined }));
  }, [dispatch, filters, limit, offset]);

  const handleFilterChange = (name: string, value: string) => {
    setFilters(prev => ({ ...prev, [name]: value }));
    setOffset(0);
  };

  const resetFilters = () => {
    setFilters({ action: '', entityType: '', performedBy: '' });
    setOffset(0);
  };

  const getActionColor = (action: string) => {
    switch (action) {
      case 'CREATE': return 'text-emerald-600 bg-emerald-50 border-emerald-100';
      case 'UPDATE': return 'text-amber-600 bg-amber-50 border-amber-100';
      case 'DELETE': return 'text-rose-600 bg-rose-50 border-rose-100';
      default: return 'text-slate-600 bg-slate-50 border-slate-100';
    }
  };

  const formatValue = (val: any) => {
    if (typeof val === 'object' && val !== null) {
      return <pre className="text-xs mt-1 p-2 bg-slate-50 rounded border border-slate-100 overflow-x-auto">{JSON.stringify(val, null, 2)}</pre>;
    }
    return <span className="text-slate-600">{String(val)}</span>;
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold tracking-tight text-slate-900 flex items-center gap-3">
            <div className="p-2 bg-primary/10 rounded-xl text-primary">
              <History size={28} />
            </div>
            System Audit Logs
          </h1>
          <p className="mt-2 text-slate-500 font-medium">
            Monitor all administrative and teacher activities across the system.
          </p>
        </div>
        
        <div className="flex items-center gap-2 text-sm text-slate-500 font-semibold bg-white px-4 py-2 rounded-lg border border-slate-200 shadow-sm">
          <Activity size={16} className="text-primary" />
          <span>{total} Total Events Logged</span>
        </div>
      </div>

      {/* Filters */}
      <Card className="border-slate-200/60 shadow-sm overflow-visible">
        <CardContent className="p-6">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-6 items-end">
            <Select
              label="Action"
              options={[
                { value: '', label: 'All Actions' },
                { value: 'CREATE', label: 'Create' },
                { value: 'UPDATE', label: 'Update' },
                { value: 'DELETE', label: 'Delete' },
              ]}
              value={filters.action}
              onChange={(e) => handleFilterChange('action', e.target.value)}
            />
            <Select
              label="Entity Type"
              options={[
                { value: '', label: 'All Entities' },
                { value: 'Student', label: 'Student' },
                { value: 'Mark', label: 'Mark' },
                { value: 'Attendance', label: 'Attendance' },
                { value: 'MarkLock', label: 'Mark Lock' },
              ]}
              value={filters.entityType}
              onChange={(e) => handleFilterChange('entityType', e.target.value)}
            />
            <div className="relative group">
              <label className="block text-sm font-bold text-slate-700 mb-2">Performed By (User ID)</label>
              <div className="relative">
                <Input
                  type="text"
                  placeholder="Filter by User ID..."
                  value={filters.performedBy}
                  onChange={(e) => handleFilterChange('performedBy', e.target.value)}
                  className="pl-10"
                />
                <UserIcon className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-primary transition-standard" size={18} />
              </div>
            </div>
            <div className="flex gap-2">
              <Button 
                variant="outline" 
                onClick={resetFilters}
                className="flex-1 gap-2 border-slate-200 text-slate-600 hover:bg-slate-50"
              >
                <FilterX size={18} />
                Reset
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Timeline View */}
      <div className="relative">
        <div className="absolute left-8 top-0 bottom-0 w-0.5 bg-slate-200" />
        
        <div className="space-y-10">
          {loading && logs.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-20 bg-white rounded-2xl border border-slate-100 shadow-sm ml-12">
              <div className="w-12 h-12 border-4 border-primary/20 border-t-primary rounded-full animate-spin mb-4" />
              <p className="text-slate-500 font-medium italic">Scanning audit trails...</p>
            </div>
          ) : logs.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-20 bg-white rounded-2xl border border-slate-100 shadow-sm ml-12">
              <div className="p-4 bg-slate-50 rounded-full mb-4">
                <Search size={32} className="text-slate-300" />
              </div>
              <p className="text-slate-500 font-bold">No activity found matching your filters</p>
              <Button variant="ghost" onClick={resetFilters} className="mt-2 text-primary">Clear all filters</Button>
            </div>
          ) : (
            logs.map((log) => (
              <div key={log.id} className="relative pl-12 group">
                {/* Timeline Dot */}
                <div className={`absolute left-[26px] top-4 w-3 h-3 rounded-full border-2 border-white shadow-sm ring-4 ring-slate-50 z-10 transition-transform group-hover:scale-125 duration-300 ${
                  log.action === 'CREATE' ? 'bg-emerald-500' :
                  log.action === 'UPDATE' ? 'bg-amber-500' :
                  'bg-rose-500'
                }`} />

                <Card className="border-slate-200/60 shadow-sm hover:shadow-md hover:border-slate-300/60 transition-all duration-300 overflow-hidden bg-white/80 backdrop-blur-sm">
                  <div className="p-5">
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-4">
                      <div className="flex items-center gap-4">
                        <div className={`px-3 py-1 rounded-full text-[10px] font-black tracking-widest uppercase border ${getActionColor(log.action)}`}>
                          {log.action}
                        </div>
                        <div className="flex items-center gap-2 text-slate-900">
                          <Database size={16} className="text-slate-400" />
                          <span className="font-bold">{log.entityType}</span>
                          <span className="text-slate-400 font-medium">ID: {log.entityId}</span>
                        </div>
                      </div>
                      
                      <div className="flex items-center gap-2 text-slate-500 font-semibold text-xs whitespace-nowrap">
                        <Calendar size={14} />
                        {format(new Date(log.timestamp), 'MMM d, yyyy • HH:mm:ss')}
                      </div>
                    </div>

                    <div className="flex flex-col md:flex-row gap-6">
                      <div className="flex-1 space-y-4">
                        <div className="flex items-center gap-2 p-3 bg-slate-50 rounded-xl border border-slate-100">
                          <div className="p-1.5 bg-white rounded-lg shadow-sm">
                            <UserIcon size={14} className="text-primary" />
                          </div>
                          <div className="flex flex-col">
                            <span className="text-[10px] text-slate-400 font-black uppercase tracking-wider leading-none">Performed By</span>
                            <span className="text-sm font-bold text-slate-700">{log.user?.name || log.user?.email || `User #${log.performedBy}`}</span>
                          </div>
                          <div className="ml-auto px-2 py-0.5 bg-slate-200/50 rounded text-[9px] font-black text-slate-500">
                            {log.user?.role || 'TEACHER'}
                          </div>
                        </div>

                        {(log.oldValue || log.newValue) && (
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {log.oldValue && (
                              <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Previous State</label>
                                <div className="max-h-40 overflow-y-auto custom-scrollbar">
                                  {formatValue(log.oldValue)}
                                </div>
                              </div>
                            )}
                            {log.newValue && (
                              <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Updated State</label>
                                <div className="max-h-40 overflow-y-auto custom-scrollbar">
                                  {formatValue(log.newValue)}
                                </div>
                              </div>
                            )}
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                </Card>
              </div>
            ))
          )}
        </div>
      </div>

      {total > limit && (
        <div className="flex flex-col sm:flex-row items-center justify-center gap-4 pt-6">
          <Button
            variant="outline"
            disabled={offset === 0}
            onClick={() => setOffset(Math.max(0, offset - limit))}
            className="w-full sm:w-32 border-slate-200 min-h-[44px]"
          >
            Previous
          </Button>
          <div className="text-sm font-bold text-slate-500">
            Page {Math.floor(offset / limit) + 1} of {Math.ceil(total / limit)}
          </div>
          <Button
            variant="outline"
            disabled={offset + limit >= total}
            onClick={() => setOffset(offset + limit)}
            className="w-full sm:w-32 border-slate-200 min-h-[44px]"
          >
            Next
          </Button>
        </div>
      )}
    </div>
  );
}

// Internal helper for user ID filter input
function Input({ className, ...props }: React.InputHTMLAttributes<HTMLInputElement>) {
  return (
    <input
      className={`flex h-11 w-full rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm font-semibold text-slate-900 ring-offset-white file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-slate-400 placeholder:font-medium focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/20 focus-visible:border-primary disabled:cursor-not-allowed disabled:opacity-50 transition-standard ${className}`}
      {...props}
    />
  );
}

