'use client';

import { useEffect, useState } from 'react';
import { useParams } from 'next/navigation';
import { useAppDispatch, useAppSelector } from '@/lib/hooks';
import { fetchSectionDetail, selectSectionDetail, selectClassesLoading, updateSection, updateRoutine } from '@/lib/features/classesSlice';
import { addStudentThunk } from '@/lib/features/studentsSlice';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Modal } from '@/components/ui/Modal';
import { selectTeachers, fetchConfig, selectSubjects } from '@/lib/features/configSlice';
import { toast } from 'react-hot-toast';
import { RoutineEditorModal } from '../../RoutineEditorModal';
import { StudentFormData } from '@/lib/validations';
import { StudentForm } from '@/components/students/StudentForm';
import { 
  Users, 
  Calendar, 
  User, 
  ArrowLeft,
  Clock,
  Search,
  Edit2,
  Plus
} from 'lucide-react';
import Link from 'next/link';

export default function SectionDetailPage() {
  const { className, section } = useParams() as { className: string, section: string };
  const dispatch = useAppDispatch();
  const detail = useAppSelector(selectSectionDetail);
  const loading = useAppSelector(selectClassesLoading);
  const teachers = useAppSelector(selectTeachers);
  const subjects = useAppSelector(selectSubjects);
  
  const [activeTab, setActiveTab] = useState<'roster' | 'routine'>('roster');
  const [searchTerm, setSearchTerm] = useState('');
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [isRoutineModalOpen, setIsRoutineModalOpen] = useState(false);
  const [isAddStudentModalOpen, setIsAddStudentModalOpen] = useState(false);
  const [selectedTeacherId, setSelectedTeacherId] = useState<string>('');

  useEffect(() => {
    dispatch(fetchSectionDetail({ className, section }));
    dispatch(fetchConfig());
  }, [dispatch, className, section]);

  useEffect(() => {
    if (detail?.teacherId) {
      setSelectedTeacherId(detail.teacherId.toString());
    }
  }, [detail]);

  const handleUpdateTeacher = async () => {
    try {
      await dispatch(updateSection({ 
        className, 
        section, 
        teacherId: selectedTeacherId ? Number(selectedTeacherId) : null 
      })).unwrap();
      toast.success('Teacher assigned successfully');
      setIsEditModalOpen(false);
    } catch (error: any) {
      toast.error(error || 'Failed to assign teacher');
    }
  };

  const handleSaveRoutine = async (routines: any[]) => {
    try {
      await dispatch(updateRoutine({ className, section, routines })).unwrap();
      toast.success('Routine updated successfully');
      setIsRoutineModalOpen(false);
      dispatch(fetchSectionDetail({ className, section })); // Refresh data
    } catch (error: any) {
      toast.error(error || 'Failed to update routine');
    }
  };

  const onAddStudent = async (data: StudentFormData) => {
    try {
      await dispatch(addStudentThunk(data)).unwrap();
      toast.success('Student added successfully');
      setIsAddStudentModalOpen(false);
      dispatch(fetchSectionDetail({ className, section })); // Refresh list
    } catch (error: any) {
      toast.error(error || 'Failed to add student');
    }
  };

  if (loading && !detail) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
      </div>
    );
  }

  if (!detail) {
    return (
      <div className="p-12 text-center">
        <h2 className="text-xl font-bold text-red-500">Section not found</h2>
        <Link href="/classes" className="text-primary hover:underline mt-4 inline-block">Back to classes</Link>
      </div>
    );
  }

  const filteredStudents = detail.students.filter(s => 
    s.fullName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.studentId.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.rollNumber.includes(searchTerm)
  );

  const days = ['MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY', 'SATURDAY', 'SUNDAY'];

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="flex items-center gap-4">
        <Link href="/classes">
          <Button variant="outline" size="icon" className="rounded-full h-10 w-10">
            <ArrowLeft className="h-5 w-5" />
          </Button>
        </Link>
        <div>
          <h1 className="text-3xl font-bold tracking-tight">{className.replace('_', ' ')} <span className="text-primary">Section {section}</span></h1>
          <div className="flex items-center gap-4 mt-1">
             <div className="flex items-center gap-1.5 text-sm text-muted-foreground">
              <User className="h-4 w-4" />
              <span>Teacher: <span className="font-semibold text-foreground">{detail.teacher?.name || 'Unassigned'}</span></span>
              <button 
                onClick={() => setIsEditModalOpen(true)}
                className="ml-1 p-1 hover:bg-muted rounded-full text-primary transition-colors"
              >
                <Edit2 className="h-3 w-3" />
              </button>
            </div>
            <div className="flex items-center gap-1.5 text-sm text-muted-foreground border-l pl-4">
              <Users className="h-4 w-4" />
              <span>{detail.students.length} Students</span>
            </div>
          </div>
        </div>
      </div>

      {/* Teacher Assignment Modal */}
      <Modal
        isOpen={isEditModalOpen}
        onClose={() => setIsEditModalOpen(false)}
        title="Assign Class Teacher"
      >
        <div className="space-y-4 py-4">
          <div className="space-y-2">
            <label className="text-sm font-medium">Select Teacher</label>
            <select
              value={selectedTeacherId}
              onChange={(e) => setSelectedTeacherId(e.target.value)}
              className="w-full h-10 px-3 rounded-md border border-input bg-background text-sm focus:outline-none focus:ring-2 focus:ring-primary/20"
            >
              <option value="">Select a teacher</option>
              {teachers.map((t) => (
                <option key={t.value} value={t.value}>{t.label}</option>
              ))}
            </select>
            <p className="text-xs text-muted-foreground">
              This teacher will be the primary contact and administrator for this section.
            </p>
          </div>
          <div className="flex justify-end gap-3 pt-4">
            <Button variant="outline" onClick={() => setIsEditModalOpen(false)}>Cancel</Button>
            <Button onClick={handleUpdateTeacher}>Save Assignment</Button>
          </div>
        </div>
      </Modal>

      <div className="flex border-b">
        <button
          onClick={() => setActiveTab('roster')}
          className={`px-6 py-3 font-semibold text-sm transition-all border-b-2 ${activeTab === 'roster' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground hover:text-foreground'}`}
        >
          Student Roster
        </button>
        <button
          onClick={() => setActiveTab('routine')}
          className={`px-6 py-3 font-semibold text-sm transition-all border-b-2 ${activeTab === 'routine' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground hover:text-foreground'}`}
        >
          Class Routine
        </button>
      </div>

      {activeTab === 'roster' ? (
        <div className="space-y-4">
          <div className="flex justify-between items-center">
            <div className="relative w-full max-w-sm">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Search students by name, ID or roll..."
                className="pl-9"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
            <div className="flex gap-2">
              <Button size="sm" variant="outline" className="hidden sm:flex">
                <Users className="h-4 w-4 mr-2" />
                Manage Roster
              </Button>
              <Button size="sm" onClick={() => setIsAddStudentModalOpen(true)}>
                <Plus className="h-4 w-4 mr-2" />
                Add Student
              </Button>
            </div>
          </div>

          <Card className="border-none shadow-sm overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-sm text-left">
                <thead className="text-xs text-muted-foreground uppercase bg-muted/30">
                  <tr>
                    <th className="px-6 py-4 font-bold">Roll</th>
                    <th className="px-6 py-4 font-bold">Student ID</th>
                    <th className="px-6 py-4 font-bold">Full Name</th>
                    <th className="px-6 py-4 font-bold">Gender</th>
                    <th className="px-6 py-4 font-bold">Status</th>
                    <th className="px-6 py-4 font-bold text-right">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-muted/50">
                  {filteredStudents.map((student) => (
                    <tr key={student.id} className="hover:bg-muted/20 transition-colors group">
                      <td className="px-6 py-4 font-bold text-primary">{student.rollNumber}</td>
                      <td className="px-6 py-4 font-medium">{student.studentId}</td>
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-3">
                          <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center text-primary font-bold text-xs">
                            {student.fullName.charAt(0)}
                          </div>
                          <span className="font-semibold">{student.fullName}</span>
                        </div>
                      </td>
                      <td className="px-6 py-4 text-muted-foreground">{student.gender}</td>
                      <td className="px-6 py-4">
                        <span className="px-2 py-1 rounded-full bg-green-100 text-green-700 text-[10px] font-bold uppercase">Active</span>
                      </td>
                      <td className="px-6 py-4 text-right">
                        <Link href={`/students/${student.id}`}>
                          <Button variant="ghost" size="sm" className="h-8 group-hover:bg-primary group-hover:text-white">View Profile</Button>
                        </Link>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            {filteredStudents.length === 0 && (
              <div className="p-12 text-center text-muted-foreground">
                <Users className="h-12 w-12 mx-auto mb-4 opacity-10" />
                <p>No students found in this section</p>
              </div>
            )}
          </Card>
        </div>
      ) : (
        <div className="space-y-6">
          <div className="flex justify-between items-center">
            <h3 className="text-lg font-bold">Weekly Schedule</h3>
            <Button size="sm" onClick={() => setIsRoutineModalOpen(true)}>
              <Calendar className="h-4 w-4 mr-2" />
              Edit Routine
            </Button>
          </div>

          <RoutineEditorModal
            isOpen={isRoutineModalOpen}
            onClose={() => setIsRoutineModalOpen(false)}
            onSave={handleSaveRoutine}
            initialRoutines={detail.routines}
            subjects={subjects}
            teachers={teachers}
          />

          <div className="grid gap-6">
            {days.map((day) => {
              const routine = detail.routines.find(r => r.dayOfWeek === day);
              return (
                <Card key={day} className="border-none shadow-sm">
                  <CardHeader className="py-3 bg-muted/30">
                    <CardTitle className="text-sm font-bold flex items-center gap-2">
                      <div className="w-2 h-2 rounded-full bg-primary"></div>
                      {day}
                    </CardTitle>
                  </CardHeader>
                  <CardContent className="p-0">
                    {routine && routine.periods.length > 0 ? (
                      <div className="divide-y divide-muted/50">
                        {routine.periods.map((period: any) => (
                          <div key={period.id} className="p-4 flex items-center justify-between">
                            <div className="flex items-center gap-6">
                              <div className="text-sm font-bold text-muted-foreground w-20 flex items-center gap-1.5">
                                <Clock className="h-3.5 w-3.5" />
                                {period.startTime}
                              </div>
                              <div className="w-[1px] h-10 bg-muted"></div>
                              <div>
                                <p className="font-bold text-primary">{period.subjectId}</p>
                                <p className="text-xs text-muted-foreground flex items-center gap-1 mt-0.5">
                                  <User className="h-3 w-3" />
                                  {period.teacher?.name || 'Unknown Teacher'}
                                </p>
                              </div>
                            </div>
                            <div className="text-[10px] font-bold bg-secondary px-2 py-1 rounded text-secondary-foreground">
                              PERIOD {period.periodNumber || '-'}
                            </div>
                          </div>
                        ))}
                      </div>
                    ) : (
                      <div className="p-6 text-center text-sm text-muted-foreground italic">
                        No classes scheduled for this day
                      </div>
                    )}
                  </CardContent>
                </Card>
              );
            })}
          </div>
        </div>
      )}

      {/* Add Student Modal */}
      <Modal 
        isOpen={isAddStudentModalOpen} 
        onClose={() => setIsAddStudentModalOpen(false)}
        title={`Register Student: ${className.replace('_', ' ')} Sec ${section}`}
        className="max-w-3xl"
      >
        <StudentForm 
          key={isAddStudentModalOpen ? 'open' : 'closed'}
          onSubmit={onAddStudent}
          onCancel={() => setIsAddStudentModalOpen(false)}
          initialData={{ className, section }}
          hideClassAndSection={true}
        />
      </Modal>
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { useAppDispatch, useAppSelector } from '@/lib/hooks';
import { fetchClassesOverview, fetchClassAnalytics, selectClassesOverview, selectClassAnalytics, selectClassesLoading } from '@/lib/features/classesSlice';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import Link from 'next/link';
import { 
  Users, 
  BookOpen, 
  TrendingUp, 
  TrendingDown, 
  Search, 
  Filter,
  ArrowRight,
  Plus
} from 'lucide-react';
import { addSectionThunk } from '@/lib/features/configSlice';
import { Modal } from '@/components/ui/Modal';
import { toast } from 'react-hot-toast';

export default function ClassesPage() {
  const dispatch = useAppDispatch();
  const overview = useAppSelector(selectClassesOverview);
  const analytics = useAppSelector(selectClassAnalytics);
  const loading = useAppSelector(selectClassesLoading);
  const [searchTerm, setSearchTerm] = useState('');
  
  const [isAddSectionModalOpen, setIsAddSectionModalOpen] = useState(false);
  const [selectedClassForSection, setSelectedClassForSection] = useState<string | null>(null);
  const [newSectionName, setNewSectionName] = useState('');

  useEffect(() => {
    dispatch(fetchClassesOverview());
    dispatch(fetchClassAnalytics());
  }, [dispatch]);

  const handleAddSection = async () => {
    if (!selectedClassForSection || !newSectionName.trim()) return;
    
    try {
      await dispatch(addSectionThunk({ 
        className: selectedClassForSection, 
        section: newSectionName 
      })).unwrap();
      toast.success('Section added successfully');
      setIsAddSectionModalOpen(false);
      setNewSectionName('');
      dispatch(fetchClassesOverview()); // Refresh the list
    } catch (error: any) {
      toast.error(error || 'Failed to add section');
    }
  };

  const filteredClasses = overview.filter(c => 
    c.className.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading && overview.length === 0) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary mx-auto mb-4"></div>
          <p className="text-muted-foreground font-medium">Loading classes...</p>
        </div>
      </div>
    );
  }

  const overallAttendance = analytics?.trends.length 
    ? Math.round(analytics.trends.reduce((acc, t) => acc + t.attendanceRate, 0) / analytics.trends.length) 
    : 0;

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col gap-2 md:flex-row md:items-center md:justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Classes Management</h1>
          <p className="text-muted-foreground">Monitor class performance, attendance, and routines across all sections.</p>
        </div>
      </div>

      {/* Add Section Modal */}
      <Modal
        isOpen={isAddSectionModalOpen}
        onClose={() => setIsAddSectionModalOpen(false)}
        title={`Add Section to ${selectedClassForSection?.replace('_', ' ')}`}
      >
        <div className="space-y-4 py-4">
          <div className="space-y-2">
            <label className="text-sm font-medium">Section Name</label>
            <Input
              placeholder="e.g. A, B, Morning, Evening"
              value={newSectionName}
              onChange={(e) => setNewSectionName(e.target.value)}
              autoFocus
            />
            <p className="text-xs text-muted-foreground">
              Enter a unique identifier for this section.
            </p>
          </div>
          <div className="flex justify-end gap-3 pt-4">
            <Button variant="outline" onClick={() => setIsAddSectionModalOpen(false)}>Cancel</Button>
            <Button onClick={handleAddSection} disabled={!newSectionName.trim()}>Add Section</Button>
          </div>
        </div>
      </Modal>

      {/* Analytics Cards */}
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
        <Card className="border-l-4 border-l-green-500">
          <CardHeader className="flex flex-row items-center justify-between pb-2 space-y-0">
            <CardTitle className="text-sm font-medium">Top Performing</CardTitle>
            <TrendingUp className="h-4 w-4 text-green-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{analytics?.topClass?.replace('_', ' ') || 'N/A'}</div>
            <p className="text-xs text-muted-foreground mt-1">Highest average marks</p>
          </CardContent>
        </Card>
        <Card className="border-l-4 border-l-red-500">
          <CardHeader className="flex flex-row items-center justify-between pb-2 space-y-0">
            <CardTitle className="text-sm font-medium">Needs Attention</CardTitle>
            <TrendingDown className="h-4 w-4 text-red-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{analytics?.weakestClass?.replace('_', ' ') || 'N/A'}</div>
            <p className="text-xs text-muted-foreground mt-1">Lowest performance trends</p>
          </CardContent>
        </Card>
        <Card className="border-l-4 border-l-blue-500">
          <CardHeader className="flex flex-row items-center justify-between pb-2 space-y-0">
            <CardTitle className="text-sm font-medium">Avg. Attendance</CardTitle>
            <Users className="h-4 w-4 text-blue-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{overallAttendance}%</div>
            <p className="text-xs text-muted-foreground mt-1">Daily average attendance</p>
          </CardContent>
        </Card>
        <Card className="border-l-4 border-l-purple-500">
          <CardHeader className="flex flex-row items-center justify-between pb-2 space-y-0">
            <CardTitle className="text-sm font-medium">Total Classes</CardTitle>
            <BookOpen className="h-4 w-4 text-purple-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{overview.length}</div>
            <p className="text-xs text-muted-foreground mt-1">Registered academic classes</p>
          </CardContent>
        </Card>
      </div>

      {/* Search and Filters */}
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center">
        <div className="relative flex-1 max-w-sm">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Search classes..."
            className="pl-9 bg-white"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <div className="flex items-center gap-2">
          <Button variant="outline" size="sm" className="h-9">
            <Filter className="h-4 w-4 mr-2" />
            Filters
          </Button>
          <p className="text-sm text-muted-foreground">
            Showing {filteredClasses.length} classes
          </p>
        </div>
      </div>

      {/* Class List */}
      <div className="grid gap-6 md:grid-cols-2 xl:grid-cols-3">
        {filteredClasses.length > 0 ? (
          filteredClasses.map((c) => (
            <Card key={c.className} className="overflow-hidden border-none shadow-sm hover:shadow-md transition-all duration-300">
              <div className="h-2 bg-primary" />
              <CardHeader className="pb-4">
                <div className="flex justify-between items-start">
                  <div>
                    <CardTitle className="text-xl font-bold">{c.className.replace('_', ' ')}</CardTitle>
                    <p className="text-sm text-muted-foreground">{c.sections.length} Sections</p>
                  </div>
                  <div className="flex flex-col items-end gap-2">
                    <div className="px-2.5 py-1 rounded-md bg-primary/10 text-primary text-xs font-bold">
                      {c.totalStudents} STUDENTS
                    </div>
                    <Button 
                      variant="outline" 
                      size="sm" 
                      className="h-7 text-[10px] px-2"
                      onClick={() => {
                        setSelectedClassForSection(c.className);
                        setIsAddSectionModalOpen(true);
                      }}
                    >
                      <Plus className="h-3 w-3 mr-1" /> Add Section
                    </Button>
                  </div>
                </div>
              </CardHeader>
              <CardContent className="space-y-6">
                <div className="grid grid-cols-2 gap-4 bg-muted/30 p-4 rounded-lg">
                  <div className="space-y-1 text-center border-r border-muted">
                    <p className="text-[10px] text-muted-foreground font-bold uppercase tracking-wider">Attendance</p>
                    <p className="text-xl font-bold text-blue-600">{c.attendancePercentage}%</p>
                  </div>
                  <div className="space-y-1 text-center">
                    <p className="text-[10px] text-muted-foreground font-bold uppercase tracking-wider">Avg Marks</p>
                    <p className="text-xl font-bold text-green-600">{c.averageMarks}</p>
                  </div>
                </div>

                <div className="space-y-3">
                  <p className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider">Active Sections</p>
                  <div className="divide-y divide-muted/50">
                    {c.sections.map((s) => (
                      <div key={s.section} className="py-3 flex items-center justify-between group">
                        <div className="flex items-center gap-3">
                          <span className="w-10 h-10 flex items-center justify-center rounded-lg bg-secondary text-secondary-foreground font-bold text-lg">
                            {s.section}
                          </span>
                          <div>
                            <p className="font-semibold text-sm group-hover:text-primary transition-colors">{s.teacher}</p>
                            <p className="text-xs text-muted-foreground">{s.studentCount} Students</p>
                          </div>
                        </div>
                        <Link href={`/classes/${c.className}/${s.section}`}>
                          <Button variant="ghost" size="icon" className="h-8 w-8 min-h-[44px] min-w-[44px] rounded-full hover:bg-primary hover:text-white transition-all">
                            <ArrowRight className="h-4 w-4" />
                          </Button>
                        </Link>
                      </div>
                    ))}
                    {c.sections.length === 0 && (
                      <div className="py-6 text-center text-muted-foreground italic text-sm">
                        No active sections. Click "Add Section" above to get started.
                      </div>
                    )}
                  </div>
                </div>
              </CardContent>
            </Card>
          ))
        ) : (
          <div className="col-span-full py-12 text-center bg-muted/20 rounded-xl border-2 border-dashed">
            <Search className="h-12 w-12 text-muted-foreground mx-auto mb-4 opacity-20" />
            <h3 className="text-lg font-medium text-muted-foreground">No classes found</h3>
            <p className="text-sm text-muted-foreground/60">Try adjusting your search or filter</p>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import React, { useEffect, useMemo } from 'react';
import {
  Zap,
  Users,
  Clock,
  BookOpen,
  Calendar,
  Sparkles,
  TrendingUp,
  LayoutGrid,
  AlertCircle,
  CheckCircle2,
  Key,
  UserPlus,
  FileSpreadsheet,
  Wallet,
  GraduationCap
} from 'lucide-react';
import { selectRole } from '@/lib/features/authSlice';
import { useAppSelector, useAppDispatch } from '@/lib/hooks';
import { selectAllStudents, fetchStudents } from '@/lib/features/studentsSlice';
import Link from 'next/link';
import {
  fetchMarks,
  selectAllMarks,
  selectAverageMarks,
  selectMarksTrendData,
} from '@/lib/features/marksSlice';
import {
  fetchAttendance,
  selectAttendanceTrendData,
  selectAllAttendanceRecords,
  selectOverallAttendanceRate,
  selectAttendanceBreakdownData,
} from '@/lib/features/attendanceSlice';
import dynamic from 'next/dynamic';
import { Button } from '@/components/ui/Button';
import { Skeleton } from '@/components/ui/Skeleton';
import { selectClasses } from '@/lib/features/configSlice';
import { generateInsights } from '@/lib/features/aiInsightsSlice';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card';
import { selectSchoolProfile, fetchSchoolProfile, fetchUsers, selectUsers } from '@/lib/features/settingsSlice';

// Lazy load Recharts components
const ResponsiveContainer = dynamic(
  () => import('recharts').then((mod) => mod.ResponsiveContainer),
  { ssr: false },
);
const AreaChart = dynamic(() => import('recharts').then((mod) => mod.AreaChart), { ssr: false });
const Area = dynamic(() => import('recharts').then((mod) => mod.Area), { ssr: false });
const XAxis = dynamic(() => import('recharts').then((mod) => mod.XAxis), { ssr: false });
const YAxis = dynamic(() => import('recharts').then((mod) => mod.YAxis), { ssr: false });
const CartesianGrid = dynamic(() => import('recharts').then((mod) => mod.CartesianGrid), {
  ssr: false,
});
const Tooltip = dynamic(() => import('recharts').then((mod) => mod.Tooltip), { ssr: false });
const BarChart = dynamic(() => import('recharts').then((mod) => mod.BarChart), { ssr: false });
const Bar = dynamic(() => import('recharts').then((mod) => mod.Bar), { ssr: false });
const PieChart = dynamic(() => import('recharts').then((mod) => mod.PieChart), { ssr: false });
const Pie = dynamic(() => import('recharts').then((mod) => mod.Pie), { ssr: false });
const Cell = dynamic(() => import('recharts').then((mod) => mod.Cell), { ssr: false });
const Legend = dynamic(() => import('recharts').then((mod) => mod.Legend), { ssr: false });

const STATUS_COLORS: Record<string, string> = {
  Present: '#10b981',
  Absent: '#ef4444',
  Late: '#f59e0b',
  Excused: '#3b82f6',
};

export default function DashboardPage() {
  const dispatch = useAppDispatch();
  const loadingStudents = useAppSelector((state) => state.students.loading);
  const loadingMarks = useAppSelector((state) => state.marks.loading);
  const loadingAttendance = useAppSelector((state) => state.attendance.loading);
  const isInitialLoading = loadingStudents || loadingMarks || loadingAttendance;

  useEffect(() => {
    dispatch(fetchStudents());
    dispatch(fetchMarks());
    dispatch(fetchAttendance());
    dispatch(fetchSchoolProfile());
    dispatch(fetchUsers());
  }, [dispatch]);

  const allStudents = useAppSelector(selectAllStudents);
  const totalStudents = allStudents.length;
  const userRole = useAppSelector(selectRole);
  const classes = useAppSelector(selectClasses);
  const totalClasses = classes.length;
  const schoolProfile = useAppSelector(selectSchoolProfile);
  const staffList = useAppSelector(selectUsers);

  const averageMarks = useAppSelector(selectAverageMarks);
  const attendanceRate = useAppSelector(selectOverallAttendanceRate);

  const marksTrendData = useAppSelector(selectMarksTrendData);
  const attendanceBreakdownData = useAppSelector(selectAttendanceBreakdownData);
  const attendanceTrendData = useAppSelector(selectAttendanceTrendData);

  const allMarks = useAppSelector(selectAllMarks);
  const allAttendance = useAppSelector(selectAllAttendanceRecords);
  const { result: aiResult, loading: aiLoading } = useAppSelector((state) => state.aiInsights);
  
  const licenseExpiryDate = useAppSelector((state) => state.license.expiryDate);

  const daysRemaining = useMemo(() => {
    if (!licenseExpiryDate) return null;
    const diff = new Date(licenseExpiryDate).getTime() - new Date().getTime();
    return Math.max(0, Math.ceil(diff / (1000 * 60 * 60 * 24)));
  }, [licenseExpiryDate]);

  const handleGenerateInsights = () => {
    dispatch(generateInsights({ marks: allMarks, attendance: allAttendance }));
  };

  // --- Derive Recent Activity ---
  const recentActivities = useMemo(() => {
    interface Activity {
      id: string;
      type: string;
      title: string;
      description: string;
      time: string | undefined;
      icon: React.ReactNode;
      color: string;
      bg: string;
    }
    const activities: Activity[] = [];

    const sortedStudents = [...allStudents]
      .sort((a, b) => new Date(b.createdAt || 0).getTime() - new Date(a.createdAt || 0).getTime())
      .slice(0, 3);

    sortedStudents.forEach((s) => {
      activities.push({
        id: `stu-${s.id}`,
        type: 'STUDENT',
        title: 'New Enrollment',
        description: `${s.fullName} registered in ${s.className}`,
        time: s.createdAt,
        icon: <Users size={16} />,
        color: 'text-primary',
        bg: 'bg-primary/10',
      });
    });

    const sortedMarks = [...allMarks]
      .sort((a, b) => new Date(b.createdAt || 0).getTime() - new Date(a.createdAt || 0).getTime())
      .slice(0, 3);

    sortedMarks.forEach((m) => {
      const student = allStudents.find((s) => s.id === m.studentId);
      activities.push({
        id: `mark-${m.id}`,
        type: 'MARK',
        title: 'Academic Update',
        description: `Marks entered for ${student?.fullName || 'student'} in ${m.subject}`,
        time: m.createdAt,
        icon: <BookOpen size={16} />,
        color: 'text-emerald-600',
        bg: 'bg-emerald-50',
      });
    });

    return activities
      .sort((a, b) => new Date(b.time || 0).getTime() - new Date(a.time || 0).getTime())
      .slice(0, 6);
  }, [allStudents, allMarks]);

  // Gender Distribution Data
  const demographicData = useMemo(() => {
    const boys = allStudents.filter(s => s.gender === 'MALE').length;
    const girls = allStudents.filter(s => s.gender === 'FEMALE').length;
    return [
      { name: 'Boys', value: boys, fill: '#3b82f6' },
      { name: 'Girls', value: girls, fill: '#ec4899' },
    ].filter(d => d.value > 0);
  }, [allStudents]);

  return (
    <div className="space-y-8 pb-10 animate-in fade-in duration-700">
      
      {/* 1. Command Center Header (Modern Glassmorphic look) */}
