'use client';

import React, { useEffect, useState, useMemo } from 'react';
import { useRouter } from 'next/navigation';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Select } from '@/components/ui/Select';
import { useAppDispatch, useAppSelector } from '@/lib/hooks';
import { createQuestionPaper } from '@/lib/features/questionPaperSlice';
import { fetchConfig, selectClasses, selectSubjects, selectExamTypes } from '@/lib/features/configSlice';
import { fetchClassesOverview, selectClassesOverview } from '@/lib/features/classesSlice';
import { fetchSchoolProfile, selectSchoolProfile } from '@/lib/features/settingsSlice';
import toast from 'react-hot-toast';
import { Bot, Save, ArrowLeft, Eye, EyeOff } from 'lucide-react';
import Link from 'next/link';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { questionPaperSchema, QuestionPaperForm } from '@/lib/validations';
import { QuestionPaperFormData } from '@/types/question-paper';
import { QuestionBuilder } from '@/components/question-paper/QuestionBuilder';
import { QuestionPaperPreview } from '@/components/question-paper/QuestionPaperPreview';
import { TemplateSelectorModal } from '@/components/question-paper/TemplateSelectorModal';
import { ConfirmationModal } from '@/components/ui/ConfirmationModal';
import { ResizableLayout } from '@/components/ui/ResizableLayout';
import { QuestionPaper } from '@/types/question-paper';

export default function CreateQuestionPaperPage() {
  const router = useRouter();
  const dispatch = useAppDispatch();
  const [loading, setLoading] = useState(false);
  const [showPreview, setShowPreview] = useState(false);
  const [templateModalOpen, setTemplateModalOpen] = useState(false);
  const [unsavedModalOpen, setUnsavedModalOpen] = useState(false);

  // Configuration Selectors
  const CLASSES = useAppSelector(selectClasses);
  const SUBJECTS = useAppSelector(selectSubjects);
  const EXAM_TYPES = useAppSelector(selectExamTypes);
  const classesOverview = useAppSelector(selectClassesOverview);
  const schoolProfile = useAppSelector(selectSchoolProfile);

  useEffect(() => {
    dispatch(fetchConfig());
    dispatch(fetchClassesOverview());
    dispatch(fetchSchoolProfile());
  }, [dispatch]);

  const {
    register,
    handleSubmit,
    watch,
    control,
    reset,
    formState: { errors, isDirty },
  } = useForm<QuestionPaperForm>({
    resolver: zodResolver(questionPaperSchema) as any,
    defaultValues: {
      title: '',
      className: '',
      section: '',
      subject: '',
      examType: '',
      duration: 120,
      totalMarks: 100,
      examDate: new Date().toISOString().split('T')[0],
      instructions: 'Attempt all questions. Follow the marking scheme strictly.',
      questions: [],
    }
  });

  const selectedClass = watch('className');
  const formData = watch();
  const [lastSaved, setLastSaved] = useState<Date | null>(null);
  const [isAutosaving, setIsAutosaving] = useState(false);

  const handleBack = () => {
    if (isDirty) {
      setUnsavedModalOpen(true);
    } else {
      router.push('/question-papers');
    }
  };

  const handleSelectTemplate = (template: QuestionPaper) => {
    reset({
      title: `${template.title} - ${new Date().getFullYear()}`,
      className: template.className,
      section: template.section || '',
      subject: template.subject,
      examType: template.examType,
      duration: template.duration,
      totalMarks: template.totalMarks,
      examDate: new Date().toISOString().split('T')[0],
      instructions: template.instructions || '',
      questions: template.questions.map((q, idx) => ({
        questionType: q.questionType as any,
        questionText: q.questionText,
        marks: q.marks,
        options: q.options || [],
        order: idx,
        instructions: q.instructions || '',
        correctAnswer: q.correctAnswer || ''
      })),
    });
    setTemplateModalOpen(false);
    toast.success('Template loaded successfully');
  };

  // Autosave Draft
  useEffect(() => {
    // Only autosave if title is present
    if (!formData.title) return;

    setIsAutosaving(true);
    const timer = setTimeout(() => {
      localStorage.setItem('questionPaperDraft', JSON.stringify(formData));
      setLastSaved(new Date());
      setIsAutosaving(false);
    }, 1500);

    return () => clearTimeout(timer);
  }, [formData]);

  // Compute available sections based on selected class
  const availableSections = useMemo(() => {
    const defaultOption = { value: '', label: 'Select Section (Optional)' };
    if (!selectedClass) return [defaultOption];
    const classInfo = classesOverview.find(c => c.className === selectedClass);
    if (!classInfo) return [defaultOption];
    return [
      defaultOption,
      ...classInfo.sections.map(s => ({ value: s.section, label: `Section ${s.section}` }))
    ];
  }, [selectedClass, classesOverview]);

  const onSubmit = async (data: QuestionPaperForm) => {
    setLoading(true);
    
    try {
      const payload: QuestionPaperFormData = {
        ...data,
        questions: (data.questions as any)?.map((q: any, index: number) => ({
          ...q,
          order: index
        })) || [],
        instructions: data.instructions || '',
        status: 'DRAFT'
      };
      
      const resultAction = await dispatch(createQuestionPaper(payload));
      if (createQuestionPaper.fulfilled.match(resultAction)) {
        toast.success('Question paper drafted successfully');
        localStorage.removeItem('questionPaperDraft'); // Clear draft on success
        router.push(`/question-papers/${resultAction.payload.id}`);
      } else {
        toast.error('Failed to create paper');
      }
    } catch (err) {
      toast.error('Error creating paper');
    } finally {
      setLoading(false);
    }
  };

  const editorPanel = (
    <div className="space-y-6">
      <div className="flex justify-end mb-4">
        <Button 
          variant="outline" 
          onClick={() => setTemplateModalOpen(true)}
          className="border-primary text-primary hover:bg-primary/5 font-bold"
        >
          <Bot size={18} className="mr-2" />
          Load from Template
        </Button>
      </div>
      <Card className="border-slate-200/60 shadow-sm bg-white overflow-hidden">
        <CardHeader className="border-b border-slate-100 bg-slate-50/50 p-6">
          <CardTitle className="text-xl flex items-center gap-2 text-slate-900">
            <Bot size={20} className="text-primary" />
            Paper Configuration
          </CardTitle>
        </CardHeader>
        <CardContent className="p-6">
          <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              
              <div className="md:col-span-2">
                <Input 
                  label="Paper Title" 
                  placeholder="e.g. Mid Term Mathematics 2026" 
                  {...register('title')}
                  error={errors.title?.message}
                />
              </div>

              <Select 
                label="Class / Grade" 
                placeholder="Select Class"
                options={CLASSES}
                {...register('className')}
                error={errors.className?.message}
              />

              <Select 
                label="Section (Optional)" 
                placeholder="Select Section"
                options={availableSections}
                {...register('section')}
                error={errors.section?.message}
                disabled={!selectedClass}
              />

              <Select 
                label="Academic Subject" 
                placeholder="Select Subject"
                options={SUBJECTS}
                {...register('subject')}
                error={errors.subject?.message}
              />

              <Select 
                label="Exam Type" 
                placeholder="Select Assessment Type"
                options={EXAM_TYPES}
                {...register('examType')}
                error={errors.examType?.message}
              />

              <Input 
                label="Duration (minutes)" 
                type="number"
                placeholder="e.g. 120"
                {...register('duration')}
                error={errors.duration?.message}
              />

              <Input 
                label="Total Marks" 
                type="number"
                placeholder="e.g. 100"
                {...register('totalMarks')}
                error={errors.totalMarks?.message}
              />

              <div className="md:col-span-2">
                <Input 
                  label="Date of Examination" 
                  type="date"
                  {...register('examDate')}
                  error={errors.examDate?.message}
                />
              </div>

              <div className="md:col-span-2 space-y-1">
                <label className="text-sm font-medium text-slate-700 ml-0.5">General Instructions</label>
                <textarea 
                  rows={4}
                  {...register('instructions')}
                  className={`w-full p-3.5 rounded-lg border bg-white text-sm text-slate-900 focus:outline-none focus:border-primary focus:ring-4 focus:ring-primary/10 transition-standard shadow-sm resize-y ${
                    errors.instructions ? 'border-red-500 focus:border-red-500 focus:ring-red-500/10' : 'border-slate-200'
                  }`}
                  placeholder="Enter any specific instructions for the students..."
                />
                {errors.instructions && (
                  <p className="text-xs text-red-500 font-bold mt-1 ml-0.5">{errors.instructions.message}</p>
                )}
              </div>
            </div>

            <div className="pt-6 border-t border-slate-100">
              <QuestionBuilder control={control} register={register} errors={errors} />
            </div>

            <div className="flex justify-end pt-6 border-t border-slate-100">
              <Button type="submit" loading={loading} className="px-8 shadow-lg shadow-blue-200 h-11 text-sm font-bold tracking-wide">
                <Save size={18} className="mr-2" />
                Generate Paper
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );

  const previewPanel = (
    <div className="sticky top-24 h-[calc(100vh-140px)] animate-in slide-in-from-right duration-500 print:static print:h-auto print:block">
      <div className="h-full rounded-2xl border border-slate-200 bg-slate-50 overflow-hidden flex flex-col shadow-inner print:border-none print:rounded-none print:shadow-none print:bg-transparent print:overflow-visible print:block">
        <div className="bg-white border-b border-slate-200 px-6 py-4 flex items-center justify-between print:hidden">
          <div className="flex items-center gap-2">
            <div className="w-3 h-3 rounded-full bg-emerald-500" />
            <span className="text-sm font-bold text-slate-700">Live Preview</span>
          </div>
          <div className="flex items-center gap-2">
            <Button variant="outline" size="sm" onClick={() => window.print()} className="h-8 text-xs font-bold border-slate-200 hover:bg-slate-50">
              Print / Export
            </Button>
            <Button variant="ghost" size="sm" onClick={() => setShowPreview(false)} className="h-8 w-8 p-0 text-slate-400 hover:text-slate-600">
              <EyeOff size={16} />
            </Button>
          </div>
        </div>
        <div className="flex-1 overflow-hidden print:overflow-visible print:block">
          <QuestionPaperPreview data={formData} schoolProfile={schoolProfile} />
        </div>
      </div>
    </div>
  );

  return (
    <div className={`space-y-6 animate-in fade-in duration-500 pb-12 transition-all duration-500 ${showPreview ? 'max-w-[1600px] mx-auto' : 'max-w-4xl mx-auto'} print:m-0 print:p-0 print:max-w-none print:w-full print:space-y-0`}>
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 print:hidden">
        <div className="flex items-center gap-4">
          <Button variant="outline" onClick={handleBack} className="px-3 shadow-sm border-slate-200">
            <ArrowLeft size={18} />
          </Button>
          <div>
            <h1 className="text-3xl font-bold text-foreground tracking-tight">Create New Paper</h1>
            <p className="text-muted-foreground font-medium mt-1">Configure parameters to generate a new question paper.</p>
          </div>
        </div>
        
        <div className="flex items-center gap-3">
          {/* Autosave Indicator */}
          <div className="hidden md:flex items-center gap-2 text-sm text-slate-500 bg-slate-50 px-3 py-1.5 rounded-full border border-slate-200">
            {isAutosaving ? (
              <>
                <div className="w-2 h-2 bg-amber-500 rounded-full animate-pulse" />
                <span>Saving...</span>
              </>
            ) : lastSaved ? (
              <>
                <div className="w-2 h-2 bg-emerald-500 rounded-full" />
                <span>Saved {lastSaved.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
              </>
            ) : (
              <>
                <div className="w-2 h-2 bg-slate-300 rounded-full" />
                <span>Unsaved</span>
              </>
            )}
          </div>

          <Button
            type="button"
            variant={showPreview ? "primary" : "outline"}
            onClick={() => setShowPreview(!showPreview)}
            className={`gap-2 ${showPreview ? 'bg-primary text-white shadow-primary/20' : 'bg-white border-slate-200 text-slate-700'}`}
          >
            {showPreview ? <EyeOff size={18} /> : <Eye size={18} />}
            {showPreview ? "Hide Preview" : "Live Preview"}
          </Button>
        </div>
      </div>

      <ResizableLayout
        leftPanel={editorPanel}
        rightPanel={previewPanel}
        showRightPanel={showPreview}
      />

      <TemplateSelectorModal 
        isOpen={templateModalOpen}
        onClose={() => setTemplateModalOpen(false)}
        onSelect={handleSelectTemplate}
      />

      <ConfirmationModal
        isOpen={unsavedModalOpen}
        onClose={() => setUnsavedModalOpen(false)}
        onConfirm={() => router.push('/question-papers')}
        title="Unsaved Changes"
        message="You have unsaved changes. Are you sure you want to leave? Your progress will be lost."
        confirmText="Leave Page"
        cancelText="Stay Here"
        destructive={true}
      />
    </div>
  );
}

'use client';

import React, { useEffect, useState, useMemo } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { 
  FileText, Plus, Search, Eye, Edit2, Trash2, Copy, Printer, FileDown 
} from 'lucide-react';
import { useAppDispatch, useAppSelector } from '@/lib/hooks';
import { 
  fetchQuestionPapers, 
  selectAllQuestionPapers, 
  selectQuestionPaperLoading,
  deleteQuestionPaper,
  createQuestionPaper,
  duplicateQuestionPaper
} from '@/lib/features/questionPaperSlice';
import { 
  fetchConfig, selectClasses, selectSubjects, selectExamTypes 
} from '@/lib/features/configSlice';
import { Card, CardHeader, CardTitle } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Select } from '@/components/ui/Select';
import { ConfirmationModal } from '@/components/ui/ConfirmationModal';
import { TableRowSkeleton } from '@/components/ui/Skeleton';
import api from '@/lib/api';
import toast from 'react-hot-toast';
import { QuestionPaper, QuestionPaperFormData } from '@/types/question-paper';

export default function QuestionPapersPage() {
  const dispatch = useAppDispatch();
  const router = useRouter();
  const papers = useAppSelector(selectAllQuestionPapers);
  const loading = useAppSelector(selectQuestionPaperLoading);
  
  const CLASSES = useAppSelector(selectClasses);
  const SUBJECTS = useAppSelector(selectSubjects);
  const EXAM_TYPES = useAppSelector(selectExamTypes);

  // Tabs
  const [activeTab, setActiveTab] = useState<'PAPERS' | 'TEMPLATES'>('PAPERS');

  // Filters
  const [search, setSearch] = useState('');
  const [classFilter, setClassFilter] = useState('');
  const [subjectFilter, setSubjectFilter] = useState('');
  const [examTypeFilter, setExamTypeFilter] = useState('');

  // Modals and Actions
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
  const [paperToDelete, setPaperToDelete] = useState<string | null>(null);
  const [duplicateModalOpen, setDuplicateModalOpen] = useState(false);
  const [paperToDuplicate, setPaperToDuplicate] = useState<QuestionPaper | null>(null);
  const [exportingId, setExportingId] = useState<string | null>(null);

  useEffect(() => {
    dispatch(fetchQuestionPapers({ isTemplate: activeTab === 'TEMPLATES' }));
    dispatch(fetchConfig());
  }, [dispatch, activeTab]);

  const filteredPapers = useMemo(() => {
    return papers.filter(p => {
      const matchesSearch = p.title.toLowerCase().includes(search.toLowerCase()) || 
                            p.subject.toLowerCase().includes(search.toLowerCase());
      const matchesClass = classFilter ? p.className === classFilter : true;
      const matchesSubject = subjectFilter ? p.subject === subjectFilter : true;
      const matchesExamType = examTypeFilter ? p.examType === examTypeFilter : true;
      
      return matchesSearch && matchesClass && matchesSubject && matchesExamType;
    });
  }, [papers, search, classFilter, subjectFilter, examTypeFilter]);

  const handleDeleteConfirm = async () => {
    if (paperToDelete) {
      const resultAction = await dispatch(deleteQuestionPaper(paperToDelete));
      if (deleteQuestionPaper.fulfilled.match(resultAction)) {
        toast.success(`${activeTab === 'TEMPLATES' ? 'Template' : 'Paper'} deleted successfully`);
        dispatch(fetchQuestionPapers({ isTemplate: activeTab === 'TEMPLATES' }));
      } else {
        toast.error('Failed to delete');
      }
    }
    setDeleteModalOpen(false);
    setPaperToDelete(null);
  };

  const handleDuplicateClick = (paper: QuestionPaper) => {
    setPaperToDuplicate(paper);
    setDuplicateModalOpen(true);
  };

  const handleDuplicateConfirm = async () => {
    if (!paperToDuplicate) return;
    
    const resultAction = await dispatch(duplicateQuestionPaper({ 
      id: paperToDuplicate.id, 
      options: { title: `Copy of ${paperToDuplicate.title}`, isTemplate: paperToDuplicate.isTemplate } 
    }));
    
    if (duplicateQuestionPaper.fulfilled.match(resultAction)) {
      toast.success('Duplicated successfully');
      dispatch(fetchQuestionPapers({ isTemplate: activeTab === 'TEMPLATES' }));
    } else {
      toast.error('Failed to duplicate');
    }
    
    setDuplicateModalOpen(false);
    setPaperToDuplicate(null);
  };

  const handleCreateFromTemplate = async (template: QuestionPaper) => {
    const resultAction = await dispatch(duplicateQuestionPaper({ 
      id: template.id, 
      options: { title: `${template.title} - ${new Date().getFullYear()}`, isTemplate: false } 
    }));
    
    if (duplicateQuestionPaper.fulfilled.match(resultAction)) {
      toast.success('Paper created from template');
      router.push(`/question-papers/${(resultAction.payload as any).id}/edit`);
    } else {
      toast.error('Failed to create paper from template');
    }
  };

  const handleSaveAsTemplate = async (paper: QuestionPaper) => {
    const resultAction = await dispatch(duplicateQuestionPaper({ 
      id: paper.id, 
      options: { title: `${paper.title} (Template)`, isTemplate: true } 
    }));
    
    if (duplicateQuestionPaper.fulfilled.match(resultAction)) {
      toast.success('Saved as template successfully');
    } else {
      toast.error('Failed to save as template');
    }
  };

  const handleExportPdf = async (paperId: string, title: string) => {
    setExportingId(paperId);
    try {
      const response = await api.get(`/question-papers/${paperId}/export/pdf`, {
        responseType: 'blob',
      });
      
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `${title.replace(/[^a-z0-9]/gi, '_').toLowerCase()}_${paperId.substring(0, 8)}.pdf`);
      document.body.appendChild(link);
      link.click();
      link.parentNode?.removeChild(link);
      window.URL.revokeObjectURL(url);
      
      toast.success('PDF exported successfully');
    } catch (error) {
      console.error('Error exporting PDF:', error);
      toast.error('Failed to export PDF.');
    } finally {
      setExportingId(null);
    }
  };

  const clearFilters = () => {
    setSearch('');
    setClassFilter('');
    setSubjectFilter('');
    setExamTypeFilter('');
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-12">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-3xl font-bold text-foreground tracking-tight">Question Papers</h1>
          <p className="text-muted-foreground font-medium mt-1">Manage and generate examination question papers.</p>
        </div>
        <div className="flex gap-2">
          <div className="bg-muted p-1 rounded-lg flex mr-4">
            <button 
              onClick={() => setActiveTab('PAPERS')}
              className={`px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'PAPERS' ? 'bg-card text-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'}`}
            >
              Papers
            </button>
            <button 
              onClick={() => setActiveTab('TEMPLATES')}
              className={`px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'TEMPLATES' ? 'bg-card text-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'}`}
            >
              Templates
            </button>
          </div>
          <Link href="/question-papers/create">
            <Button className="shadow-md">
              <Plus size={18} className="mr-2" />
              Create Paper
            </Button>
          </Link>
        </div>
      </div>

      <Card className="border-border shadow-sm">
        <CardHeader className="border-b border-border bg-muted/30 p-6 space-y-4">
          <div className="flex flex-col md:flex-row gap-4 items-start md:items-center justify-between">
            <CardTitle className="text-xl flex items-center gap-2">
              <FileText size={20} className="text-primary" />
              Paper Directory
            </CardTitle>
            <div className="relative w-full md:w-96">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" size={16} />
              <input 
                type="text"
                placeholder="Search by title or subject..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="w-full bg-card border border-border rounded-lg pl-9 pr-4 py-2 text-sm text-foreground placeholder:text-muted-foreground transition-standard focus:border-primary focus:ring-4 focus:ring-primary/10 outline-none shadow-sm"
              />
            </div>
          </div>
          
          <div className="grid grid-cols-1 sm:grid-cols-3 lg:grid-cols-4 gap-4 pt-2">
            <Select 
              options={[{ value: '', label: 'All Classes' }, ...CLASSES]}
              value={classFilter}
              onChange={(e) => setClassFilter(e.target.value)}
              className="bg-card h-9"
            />
            <Select 
              options={[{ value: '', label: 'All Subjects' }, ...SUBJECTS]}
              value={subjectFilter}
              onChange={(e) => setSubjectFilter(e.target.value)}
              className="bg-card h-9"
            />
            <Select 
              options={[{ value: '', label: 'All Exam Types' }, ...EXAM_TYPES]}
              value={examTypeFilter}
              onChange={(e) => setExamTypeFilter(e.target.value)}
              className="bg-card h-9"
            />
            {(search || classFilter || subjectFilter || examTypeFilter) && (
              <Button variant="ghost" onClick={clearFilters} className="h-9 text-muted-foreground hover:text-foreground">
                Clear Filters
              </Button>
            )}
          </div>
        </CardHeader>
        
        <div className="overflow-x-auto min-h-[400px]">
          <table className="w-full text-left text-sm whitespace-nowrap">
            <thead className="bg-muted/50 border-b border-border">
              <tr>
                <th className="px-6 py-4 font-bold text-muted-foreground uppercase tracking-wider text-xs">Title</th>
                <th className="px-6 py-4 font-bold text-muted-foreground uppercase tracking-wider text-xs">Class</th>
                <th className="px-6 py-4 font-bold text-muted-foreground uppercase tracking-wider text-xs">Subject</th>
                <th className="px-6 py-4 font-bold text-muted-foreground uppercase tracking-wider text-xs">Exam Type</th>
                <th className="px-6 py-4 font-bold text-muted-foreground uppercase tracking-wider text-xs">Status</th>
                <th className="px-6 py-4 font-bold text-muted-foreground uppercase tracking-wider text-xs">Date</th>
                <th className="px-6 py-4 font-bold text-muted-foreground uppercase tracking-wider text-xs text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border bg-card">
              {loading ? (
                Array(5).fill(0).map((_, i) => (
                  <TableRowSkeleton key={i} columns={7} />
                ))
              ) : filteredPapers.length > 0 ? (
                filteredPapers.map(paper => (
                  <tr key={paper.id} className="hover:bg-muted/30 transition-colors group">
                    <td className="px-6 py-4 font-bold text-foreground">
                      <div className="flex items-center gap-2">
                        <FileText size={16} className="text-muted-foreground" />
                        <span className="truncate max-w-[200px] block" title={paper.title}>{paper.title}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-muted-foreground">{paper.className}</td>
                    <td className="px-6 py-4 text-muted-foreground">{paper.subject}</td>
                    <td className="px-6 py-4 text-muted-foreground">{paper.examType || 'N/A'}</td>
                    <td className="px-6 py-4">
                      <span className={`px-2.5 py-1 rounded text-[10px] font-black tracking-widest ${
                        paper.status === 'PUBLISHED' ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'
                      }`}>
                        {paper.status}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-muted-foreground">
                      {paper.examDate ? new Date(paper.examDate).toLocaleDateString() : new Date(paper.createdAt).toLocaleDateString()}
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex justify-end gap-1 opacity-100 transition-opacity">
                        <button 
                          onClick={() => router.push(`/question-papers/${paper.id}`)}
                          className="p-1.5 text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded transition-colors" 
                          title="View"
                        >
                          <Eye size={16} />
                        </button>
                        <button 
                          onClick={() => router.push(`/question-papers/${paper.id}/edit`)}
                          className="p-1.5 text-indigo-600 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 rounded transition-colors" 
                          title="Edit"
                        >
                          <Edit2 size={16} />
                        </button>
                        <button 
                          onClick={() => handleDuplicateClick(paper)}
                          className="p-1.5 text-teal-600 hover:bg-teal-50 dark:hover:bg-teal-900/20 rounded transition-colors" 
                          title="Duplicate"
                        >
                          <Copy size={16} />
                        </button>
                        {activeTab === 'PAPERS' ? (
                          <button 
                            onClick={() => handleSaveAsTemplate(paper)}
                            className="p-1.5 text-purple-600 hover:bg-purple-50 dark:hover:bg-purple-900/20 rounded transition-colors" 
                            title="Save as Template"
                          >
                            <FileText size={16} />
                          </button>
                        ) : (
                          <button 
                            onClick={() => handleCreateFromTemplate(paper)}
                            className="p-1.5 text-orange-600 hover:bg-orange-50 dark:hover:bg-orange-900/20 rounded transition-colors" 
                            title="Create Paper from Template"
                          >
                            <Plus size={16} />
                          </button>
                        )}
                        <button 
                          onClick={() => router.push(`/question-papers/${paper.id}`)}
                          className="p-1.5 text-slate-600 hover:bg-slate-100 dark:hover:bg-slate-800 rounded transition-colors" 
                          title="Print"
                        >
                          <Printer size={16} />
                        </button>
                        <button 
                          onClick={() => handleExportPdf(paper.id, paper.title)}
                          disabled={exportingId === paper.id}
                          className="p-1.5 text-amber-600 hover:bg-amber-50 dark:hover:bg-amber-900/20 rounded transition-colors disabled:opacity-50 flex items-center justify-center min-w-[28px]" 
                          title="Export PDF"
                        >
                          {exportingId === paper.id ? <div className="w-4 h-4 border-2 border-amber-600 border-t-transparent rounded-full animate-spin" /> : <FileDown size={16} />}
                        </button>
                        <button 
                          onClick={() => {
                            setPaperToDelete(paper.id);
                            setDeleteModalOpen(true);
                          }}
                          className="p-1.5 text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded transition-colors" 
                          title="Delete"
                        >
                          <Trash2 size={16} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={7} className="px-6 py-12 text-center">
                    <div className="flex flex-col items-center justify-center text-muted-foreground">
                      <FileText size={32} className="mb-2 opacity-50" />
                      <p>No question papers found matching your criteria.</p>
                      <Button variant="ghost" onClick={clearFilters} className="mt-4">
                        Clear all filters
                      </Button>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </Card>

      <ConfirmationModal
        isOpen={deleteModalOpen}
        onClose={() => {
          setDeleteModalOpen(false);
          setPaperToDelete(null);
        }}
        onConfirm={handleDeleteConfirm}
        title="Delete Question Paper"
        message="Are you sure you want to delete this question paper? This action cannot be undone."
        confirmText="Delete"
        cancelText="Cancel"
        destructive={true}
      />

      <ConfirmationModal
        isOpen={duplicateModalOpen}
        onClose={() => {
          setDuplicateModalOpen(false);
          setPaperToDuplicate(null);
        }}
        onConfirm={handleDuplicateConfirm}
        title="Duplicate Question Paper"
        message={`Are you sure you want to duplicate "${paperToDuplicate?.title}"? This will create a fresh draft copy.`}
        confirmText="Duplicate"
        cancelText="Cancel"
        destructive={false}
      />
    </div>
  );
}

'use client';

import React, { useState, useEffect, useMemo } from 'react';
import { 
  FileText, 
  BarChart3, 
  Calendar, 
  Download, 
  Filter, 
  Printer,
  TrendingUp,
} from 'lucide-react';
import { useAppDispatch, useAppSelector } from '@/lib/hooks';
import { 
  fetchStudentReport, 
  fetchClassPerformance, 
  fetchAttendanceSummary,
  selectStudentReport,
  selectClassPerformance,
  selectAttendanceSummary,
  selectReportsLoading,
  updateRemarks,
  clearAllReports
} from '@/lib/features/reportsSlice';
import { selectSchoolProfile, fetchSchoolProfile, selectSystemSettings, fetchSystemSettings } from '@/lib/features/settingsSlice';
import { selectClasses, selectExamTypes, fetchConfig } from '@/lib/features/configSlice';
import { selectAllStudents, fetchStudents } from '@/lib/features/studentsSlice';
import { Card, CardHeader, CardTitle } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import toast from 'react-hot-toast';
import api from '@/lib/api';

export default function ReportsPage() {
  const dispatch = useAppDispatch();
  const CLASSES = useAppSelector(selectClasses);
  const EXAM_TYPES = useAppSelector(selectExamTypes);
  const systemSettings = useAppSelector(selectSystemSettings);
  const students = useAppSelector(selectAllStudents);
  const schoolProfile = useAppSelector(selectSchoolProfile);
  const studentReport = useAppSelector(selectStudentReport);
  const classPerformance = useAppSelector(selectClassPerformance);
  const attendanceSummary = useAppSelector(selectAttendanceSummary);
  const loading = useAppSelector(selectReportsLoading);

  const [activeTab, setActiveTab] = useState<'report-card' | 'attendance' | 'performance'>('report-card');
  const [isLoadingReport, setIsLoadingReport] = useState(false);
  
  // Filters
  const [selectedClass, setSelectedClass] = useState('');
  const [selectedExamType, setSelectedExamType] = useState('');
  const [selectedStudentId, setSelectedStudentId] = useState<number | ''>('');

  useEffect(() => {
    dispatch(clearAllReports()); // Clear on mount
    dispatch(fetchConfig());
    dispatch(fetchStudents());
    dispatch(fetchSchoolProfile());
    dispatch(fetchSystemSettings());

    return () => {
      dispatch(clearAllReports()); // Clear on unmount
    };
  }, [dispatch]);

  // Clear reports when filters change to avoid showing old data
  useEffect(() => {
    dispatch(clearAllReports());
  }, [selectedClass, selectedExamType, selectedStudentId, activeTab, dispatch]);

  const filteredStudents = useMemo(() => {
    if (!selectedClass) return students;
    return students.filter(s => s.className === selectedClass);
  }, [students, selectedClass]);

  const reportOptions = useMemo(() => {
    const baseOptions = EXAM_TYPES.map(e => ({ value: e.value, label: e.label }));
    
    const specials = [
      { value: 'Annual Result', label: 'Annual Master Report' }
    ];

    const termsPerYear = parseInt(systemSettings.academicStructure?.split('_')[0] || '2');
    for (let i = 1; i <= termsPerYear; i++) {
      specials.push({ value: `TERM_${i}`, label: `Term ${i} Report (BD Standard)` });
    }

    return [...baseOptions, ...specials];
  }, [EXAM_TYPES, systemSettings.academicStructure]);

  const handleFetchReport = () => {
    if (!selectedStudentId || !selectedExamType) {
      toast.error('Please select both a student and an assessment type');
      return;
    }
    dispatch(fetchStudentReport({ studentId: Number(selectedStudentId), examType: selectedExamType }));
  };

  const handleFetchPerformance = () => {
    if (!selectedClass || !selectedExamType) {
      toast.error('Please select both a class and an exam type');
      return;
    }
    dispatch(fetchClassPerformance({ className: selectedClass, examType: selectedExamType }));
  };

  const handleFetchAttendance = () => {
    dispatch(fetchAttendanceSummary({ className: selectedClass || undefined }));
  };

  const handleUpdateRemarks = (remarks: string) => {
    if (!selectedStudentId || !selectedExamType) return;
    dispatch(updateRemarks({ 
      studentId: Number(selectedStudentId), 
      examType: selectedExamType, 
      remarks 
    })).unwrap().then(() => toast.success('Remarks updated'));
  };

  const auth = useAppSelector((state: any) => state.auth);
  const token = auth.token;

  const handleDownloadPDF = () => {
    if (!selectedStudentId || !selectedExamType) return;
    const baseUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:5000/api';
    const url = `${baseUrl}/reports/export/${selectedStudentId}/${selectedExamType}?token=${token}`;
    window.open(url, '_blank');
  };

  const handleBulkExport = () => {
    if (!selectedClass || !selectedExamType) {
      toast.error('Please select both a class and an exam type');
      return;
    }
    const baseUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:5000/api';
    const url = `${baseUrl}/reports/export-bulk/${selectedClass}/${selectedExamType}?token=${token}`;
    window.open(url, '_blank');
  };

  const exportToCSV = (data: any[], filename: string) => {
    if (data.length === 0) return;
    const headers = Object.keys(data[0]).join(',');
    const rows = data.map(row => Object.values(row).join(','));
    const csvContent = "data:text/csv;charset=utf-8," + headers + "\n" + rows.join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `${filename}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* Hide controls when printing */}
      <div className="print:hidden space-y-6">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
          <div>
            <h1 className="text-3xl font-bold text-slate-900 tracking-tight">Reporting Center</h1>
            <p className="text-slate-500 font-medium mt-1">Generate and export comprehensive academic insights.</p>
          </div>
          <div className="flex flex-wrap items-center gap-2">
            {activeTab === 'report-card' && (
              <>
                <Button 
                  onClick={async () => {
                    if (!selectedStudentId) {
                      toast.error('Please select a student first');
                      return;
                    }
                    try {
                      setIsLoadingReport(true);
                      await api.post(`/reports/annual-result/${selectedStudentId}`);
                      toast.success('Annual Result calculated successfully');
                      setSelectedExamType('Annual Result');
                      // Use the Redux thunk instead of a non-existent local setter
                      await dispatch(fetchStudentReport({ 
                        studentId: Number(selectedStudentId), 
                        examType: 'Annual Result' 
                      })).unwrap();
                    } catch (err: any) {
                      toast.error(err.response?.data?.message || 'Failed to calculate Annual Result');
                    } finally {
                      setIsLoadingReport(false);
                    }
                  }} 
                  variant="soft" 
                  className="flex gap-2"
                  disabled={!selectedStudentId || isLoadingReport}
                >
                  <TrendingUp size={16} />
                  <span className="hidden sm:inline">Compile Annual Result</span>
                </Button>
                {studentReport && (
                  <Button onClick={handleDownloadPDF} variant="outline" className="flex gap-2 border-blue-200 hover:bg-blue-50 text-blue-700 shadow-sm">
                    <Download size={16} />
                    <span className="hidden sm:inline">Download</span> PDF
                  </Button>
                )}
                <Button onClick={handleBulkExport} variant="outline" className="flex gap-2 border-slate-200 hover:bg-slate-50 shadow-sm">
                  <Download size={16} />
                  Bulk Export
                </Button>
              </>
            )}
            <Button onClick={() => window.print()} className="flex items-center gap-2 shadow-lg shadow-blue-200">
              <Printer size={18} />
              <span className="hidden sm:inline">Print View</span>
            </Button>
          </div>
        </div>

        {/* Tabs */}
        <div className="flex bg-white p-1 rounded-xl border border-slate-200 w-full md:w-max">
          {[
            { id: 'report-card', label: 'Report Cards', icon: FileText },
            { id: 'attendance', label: 'Attendance', icon: Calendar },
            { id: 'performance', label: 'Performance', icon: BarChart3 }
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`flex items-center gap-2 px-6 py-2.5 rounded-lg text-sm font-bold transition-all ${
                activeTab === tab.id 
                  ? 'bg-primary text-white shadow-md' 
                  : 'text-slate-500 hover:bg-slate-50'
              }`}
            >
              <tab.icon size={18} />
              {tab.label}
            </button>
          ))}
        </div>

        {/* Filters Card */}
        <Card className="border-slate-200/60 shadow-sm">
          <div className="p-6 grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1">Grade / Class</label>
              <select
                value={selectedClass}
                onChange={(e) => setSelectedClass(e.target.value)}
                className="w-full h-10 px-3 rounded-lg border border-slate-200 bg-slate-50/50 text-sm font-semibold focus:ring-4 focus:ring-primary/5 outline-none transition-standard"
              >
                <option value="">All Classes</option>
                {CLASSES.map(c => <option key={c.value} value={c.value}>{c.label}</option>)}
              </select>
            </div>

            {activeTab === 'report-card' && (
              <div className="space-y-1.5">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1">Select Student</label>
                <select
                  value={selectedStudentId}
                  onChange={(e) => setSelectedStudentId(Number(e.target.value))}
                  className="w-full h-10 px-3 rounded-lg border border-slate-200 bg-slate-50/50 text-sm font-semibold focus:ring-4 focus:ring-primary/5 outline-none transition-standard"
                >
                  <option value="">Choose Student</option>
                  {filteredStudents.map(s => <option key={s.id} value={s.id}>{s.fullName} ({s.rollNumber})</option>)}
                </select>
              </div>
            )}

            {(activeTab === 'report-card' || activeTab === 'performance') && (
              <div className="space-y-1.5">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1">Exam Type</label>
                <select
                  value={selectedExamType}
                  onChange={(e) => setSelectedExamType(e.target.value)}
                  className="w-full h-10 px-3 rounded-lg border border-slate-200 bg-slate-50/50 text-sm font-semibold focus:ring-4 focus:ring-primary/5 outline-none transition-standard"
                >
                  <option value="">Select Assessment</option>
                  {EXAM_TYPES.map(t => <option key={t.value} value={t.value}>{t.label}</option>)}
                </select>
              </div>
            )}

            <Button 
              onClick={
                activeTab === 'report-card' ? handleFetchReport : 
                activeTab === 'performance' ? handleFetchPerformance : 
                handleFetchAttendance
              }
              className="h-10 w-full md:w-auto"
            >
              <Filter size={16} className="mr-2" />
              Generate Report
            </Button>
          </div>
        </Card>
      </div>

      {/* Main Content Area */}
      <div className="min-h-[400px]">
        {loading ? (
          <div className="flex flex-col items-center justify-center py-24 gap-4 print:hidden">
            <div className="h-12 w-12 border-4 border-primary/20 border-t-primary rounded-full animate-spin"></div>
            <p className="text-slate-400 font-bold text-sm uppercase tracking-widest">Compiling Data...</p>
          </div>
        ) : activeTab === 'report-card' && studentReport ? (
          // --- FORMAL REPORT CARD LAYOUT ---
          <div className="flex justify-center bg-slate-100 print:bg-white p-8 print:p-0 rounded-2xl">
            <div className="bg-white w-full max-w-[210mm] min-h-[297mm] shadow-2xl print:shadow-none p-[15mm] border border-slate-200 print:border-none relative flex flex-col">
              
              {/* Document Header with Professional Branding */}
              <div className="flex items-center justify-between border-b-2 border-slate-900 pb-6 mb-8">
                {schoolProfile?.logo ? (
                  <img src={schoolProfile.logo} alt="School Logo" className="h-20 w-auto object-contain" />
                ) : (
                  <div className="h-20 w-20 bg-slate-50 rounded-full flex items-center justify-center border border-slate-200 print:hidden">
                    <span className="text-[10px] text-slate-300 font-black uppercase">Logo</span>
                  </div>
                )}
                
                <div className="flex-1 text-center px-4">
                  <h1 className="text-3xl font-black text-slate-900 uppercase tracking-tight leading-none mb-2">
                    {schoolProfile?.name || 'EduTrack Academy'}
                  </h1>
                  <div className="text-[10px] text-slate-500 font-bold uppercase tracking-widest flex flex-wrap justify-center gap-x-3 gap-y-1">
                    {schoolProfile?.address && <span>{schoolProfile.address}</span>}
                    {schoolProfile?.phone && <span>Tel: {schoolProfile.phone}</span>}
                    {schoolProfile?.email && <span>Email: {schoolProfile.email}</span>}
                    {schoolProfile?.website && <span>Web: {schoolProfile.website}</span>}
                  </div>
                </div>

                <div className="w-20 h-20 opacity-0 hidden sm:block" aria-hidden="true" />
              </div>

              <div className="text-center mb-8">
                <h2 className="text-xl font-bold text-primary uppercase tracking-[0.2em] underline underline-offset-8">Official Academic Report</h2>
                <p className="text-xs font-black text-slate-400 mt-3 uppercase">Assessment: {selectedExamType.replace('_', ' ')} • Session {schoolProfile?.academicYear || '2026'}</p>
              </div>

              {/* Student Information Grid */}
              <div className="grid grid-cols-2 gap-x-12 gap-y-4 mb-8">
                <div className="flex justify-between border-b border-slate-200 pb-1">
                  <span className="font-bold text-slate-500 text-sm">Student Name</span>
                  <span className="font-black text-slate-900 text-sm">{studentReport.student.fullName}</span>
                </div>
                <div className="flex justify-between border-b border-slate-200 pb-1">
                  <span className="font-bold text-slate-500 text-sm">Student ID</span>
                  <span className="font-bold text-slate-900 text-sm">{studentReport.student.studentId}</span>
                </div>
                <div className="flex justify-between border-b border-slate-200 pb-1">
                  <span className="font-bold text-slate-500 text-sm">Class & Section</span>
                  <span className="font-bold text-slate-900 text-sm">{studentReport.student.className} - {studentReport.student.section}</span>
                </div>
                <div className="flex justify-between border-b border-slate-200 pb-1">
                  <span className="font-bold text-slate-500 text-sm">Roll Number</span>
                  <span className="font-bold text-slate-900 text-sm">{studentReport.student.rollNumber}</span>
                </div>
                <div className="flex justify-between border-b border-slate-200 pb-1">
                  <span className="font-bold text-slate-500 text-sm">Date of Issue</span>
                  <span className="font-bold text-slate-900 text-sm">{new Date().toLocaleDateString()}</span>
                </div>
                <div className="flex justify-between border-b border-slate-200 pb-1">
                  <span className="font-bold text-slate-500 text-sm">Attendance</span>
                  <span className="font-bold text-slate-900 text-sm">{studentReport.attendanceRate}%</span>
                </div>
              </div>

              {/* Academic Performance Table */}
              <div className="mb-8 overflow-hidden">
                <h3 className="font-black text-slate-900 uppercase tracking-widest text-sm mb-3">Academic Performance</h3>
                <table className="w-full text-[12px] border-collapse border border-slate-800">
                  <thead>
                    <tr className="bg-slate-100">
                      <th className="border border-slate-800 p-2 text-left font-bold text-slate-900">Subject</th>
                      
                      {/* Dynamic Term Columns for Annual Report */}
                      {selectedExamType === 'Annual Result' && (studentReport as any).contributingTerms?.map((term: any) => (
                        <th key={term.value} className="border border-slate-800 p-1 text-center font-bold text-slate-900 w-16">
                          {term.label}
                        </th>
                      ))}

                      {/* Dynamic Columns for BD Standard Term Report */}
                      {(studentReport as any).isBDStandard && (
                        <>
                          <th className="border border-slate-800 p-2 text-center font-bold text-slate-900 w-20">Tutorial</th>
                          <th className="border border-slate-800 p-2 text-center font-bold text-slate-900 w-20">Final Exam</th>
                        </>
                      )}

                      {selectedExamType !== 'Annual Result' && !(studentReport as any).isBDStandard && <th className="border border-slate-800 p-2 text-center font-bold text-slate-900 w-20">Full Marks</th>}
                      <th className="border border-slate-800 p-2 text-center font-bold text-slate-900 w-20">
                        {selectedExamType === 'Annual Result' ? 'Annual Avg' : 'Total Marks'}
                      </th>
                      <th className="border border-slate-800 p-2 text-center font-bold text-slate-900 w-12">GP</th>
                      <th className="border border-slate-800 p-2 text-center font-bold text-slate-900 w-12">Grade</th>
                    </tr>
                  </thead>
                  <tbody>
                    {studentReport.marks.map((mark) => (
                      <tr key={mark.id}>
                        <td className="border border-slate-800 p-2 font-semibold text-slate-800 truncate max-w-[120px]">{mark.subject}</td>
                        
                        {/* Dynamic Score Cells for Annual Report */}
                        {selectedExamType === 'Annual Result' && (mark as any).termScores && (studentReport as any).contributingTerms?.map((term: any) => (
                          <td key={term.value} className="border border-slate-800 p-1 text-center text-slate-600 font-medium">
                            {(mark as any).termScores[term.value] ?? '-'}
                          </td>
                        ))}

                        {/* Dynamic Cells for BD Standard Term Report */}
                        {(studentReport as any).isBDStandard && (
                          <>
                            <td className="border border-slate-800 p-2 text-center text-slate-600">{(mark as any).tutorial ?? '-'}</td>
                            <td className="border border-slate-800 p-2 text-center text-slate-600">{(mark as any).final ?? '-'}</td>
                          </>
                        )}

                        {selectedExamType !== 'Annual Result' && !(studentReport as any).isBDStandard && <td className="border border-slate-800 p-2 text-center text-slate-600">{mark.maxScore}</td>}
                        <td className="border border-slate-800 p-2 text-center font-bold text-slate-900">{mark.score}</td>
                        <td className="border border-slate-800 p-2 text-center font-bold text-slate-900">
                          {(mark as any).gpa?.toFixed(2) || '0.00'}
                        </td>
                        <td className="border border-slate-800 p-2 text-center font-bold text-slate-900">
                          {(mark as any).grade}
                        </td>
                      </tr>
                    ))}
                    {studentReport.marks.length === 0 && (
                      <tr>
                        <td colSpan={
                          selectedExamType === 'Annual Result' 
                            ? 4 + ((studentReport as any).contributingTerms?.length || 0) 
                            : (studentReport as any).isBDStandard ? 6 : 5
                        } className="border border-slate-800 p-4 text-center text-slate-500 italic text-sm">
                          No marks recorded for this exam type.
                        </td>
                      </tr>
                    )}
                  </tbody>
                  {(selectedExamType === 'Annual Result' || (studentReport as any).isBDStandard) && (
                    <tfoot>
                      <tr className="bg-slate-50">
                        <th colSpan={
                          selectedExamType === 'Annual Result' 
                            ? 1 + ((studentReport as any).contributingTerms?.length || 0) 
                            : (studentReport as any).isBDStandard ? 3 : 2
                        } className="border border-slate-800 p-2 text-right font-black text-slate-900 uppercase text-[10px]">Grade Point Average (GPA)</th>
                        <th colSpan={3} className="border border-slate-800 p-2 text-center font-black text-slate-900 text-base">
                          {studentReport.gpa.toFixed(2)}
                        </th>
                      </tr>
                    </tfoot>
                  )}
                </table>
              </div>

              {/* Teacher Remarks - Editable on screen, static on print */}
              <div className="mb-16">
                 <h3 className="font-black text-slate-900 uppercase tracking-widest text-sm mb-2">Class Teacher's Remarks</h3>
                 <textarea 
                    defaultValue={studentReport.teacherRemarks}
                    onBlur={(e) => handleUpdateRemarks(e.target.value)}
                    placeholder="Click to enter official remarks before printing..."
                    className="w-full min-h-[80px] p-0 text-sm text-slate-800 bg-transparent border-b border-dashed border-slate-400 focus:border-primary focus:ring-0 resize-none outline-none print:border-none print:resize-none"
                 />
              </div>

              {/* Signatures */}
              <div className="flex justify-between items-end mt-auto pt-12 pb-12">
                <div className="text-center w-48">
                  <div className="border-t border-slate-800 pt-2 font-bold text-slate-800 text-sm">Class Teacher</div>
                </div>
                <div className="text-center w-48">
                  <div className="border-t border-slate-800 pt-2 font-bold text-slate-800 text-sm">Principal</div>
                </div>
                <div className="text-center w-48">
                  <div className="border-t border-slate-800 pt-2 font-bold text-slate-800 text-sm">Guardian</div>
                </div>
              </div>

              {/* Footer */}
              <div className="text-center text-xs text-slate-400 font-medium border-t border-slate-100 pt-4 pb-2 print:pb-0">
                This is a computer-generated document by EduTrack AI.
              </div>

            </div>
          </div>
        ) : activeTab === 'attendance' && attendanceSummary.length > 0 ? (
          // ... (Rest of the file remains unchanged for Attendance and Performance tabs)
          <div className="print:hidden">
            <Card className="border-slate-200/60 shadow-sm overflow-hidden p-0">
               <CardHeader className="flex flex-row items-center justify-between p-6 border-b border-slate-100 bg-slate-50/50">
                  <CardTitle className="text-slate-900">Attendance Summary Matrix</CardTitle>
                  <Button variant="outline" size="sm" onClick={() => exportToCSV(attendanceSummary, 'attendance_report')}>
                    <Download size={14} className="mr-2" /> Export CSV
                  </Button>
               </CardHeader>
               <div className="overflow-x-auto">
                  <table className="w-full text-left text-sm">
                    <thead className="bg-white border-b border-slate-100">
                      <tr>
                        <th className="px-6 py-4 font-bold text-slate-600 uppercase tracking-wider text-[10px]">Student Name</th>
                        <th className="px-6 py-4 font-bold text-slate-600 uppercase tracking-wider text-[10px]">Roll No</th>
                        <th className="px-6 py-4 font-bold text-slate-600 uppercase tracking-wider text-[10px]">Class</th>
                        <th className="px-6 py-4 font-bold text-slate-600 uppercase tracking-wider text-[10px] text-right">Attendance Rate</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {attendanceSummary.map((s) => (
                        <tr key={s.id} className="hover:bg-slate-50/50 transition-colors">
                          <td className="px-6 py-4 font-bold text-slate-900">{s.fullName}</td>
                          <td className="px-6 py-4 font-mono font-bold text-slate-500">{s.rollNumber}</td>
                          <td className="px-6 py-4 font-bold text-slate-400">{s.className}-{s.section}</td>
                          <td className="px-6 py-4 text-right">
                             <div className="flex items-center justify-end gap-3">
                                <div className="w-24 h-1.5 bg-slate-100 rounded-full overflow-hidden">
                                  <div 
                                    className={`h-full rounded-full ${s.attendanceRate >= 80 ? 'bg-emerald-500' : 'bg-red-500'}`}
                                    style={{ width: `${s.attendanceRate}%` }}
                                  />
                                </div>
                                <span className="font-black text-slate-900">{s.attendanceRate}%</span>
                             </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
               </div>
            </Card>
          </div>
        ) : activeTab === 'performance' && classPerformance ? (
          <div className="space-y-6 print:hidden">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
               <Card className="border-slate-200/60 shadow-sm overflow-hidden p-0">
                  <CardHeader className="bg-emerald-50 border-b border-emerald-100 p-6">
                    <CardTitle className="text-emerald-900 flex items-center gap-2">
                      <TrendingUp size={20} />
                      Top Performing Students
                    </CardTitle>
                  </CardHeader>
                  <div className="divide-y divide-slate-50">
                    {classPerformance.topStudents.map((s, idx) => (
                      <div key={s.id} className="p-4 flex items-center justify-between hover:bg-slate-50 transition-colors">
                        <div className="flex items-center gap-4">
                          <span className="h-6 w-6 rounded-full bg-emerald-100 text-emerald-700 flex items-center justify-center font-black text-xs">{idx + 1}</span>
                          <div>
                            <p className="font-bold text-slate-900 text-sm">{s.fullName}</p>
                            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Roll: {s.rollNumber}</p>
                          </div>
                        </div>
                        <div className="text-right">
                          <p className="font-black text-emerald-600">GPA {s.gpa.toFixed(2)}</p>
                          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{s.totalScore} Points</p>
                        </div>
                      </div>
                    ))}
                  </div>
               </Card>

               <Card className="border-slate-200/60 shadow-sm overflow-hidden p-0">
                  <CardHeader className="bg-red-50 border-b border-red-100 p-6">
                    <CardTitle className="text-red-900 flex items-center gap-2">
                      <TrendingUp size={20} className="rotate-180" />
                      Critical Performance (Weak)
                    </CardTitle>
                  </CardHeader>
                  <div className="divide-y divide-slate-50">
                    {classPerformance.weakStudents.map((s, idx) => (
                      <div key={s.id} className="p-4 flex items-center justify-between hover:bg-slate-50 transition-colors">
                        <div className="flex items-center gap-4">
                          <span className="h-6 w-6 rounded-full bg-red-100 text-red-700 flex items-center justify-center font-black text-xs">{idx + 1}</span>
                          <div>
                            <p className="font-bold text-slate-900 text-sm">{s.fullName}</p>
                            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Roll: {s.rollNumber}</p>
                          </div>
                        </div>
                        <div className="text-right">
                          <p className="font-black text-red-600">GPA {s.gpa.toFixed(2)}</p>
                          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{s.totalScore} Points</p>
                        </div>
                      </div>
                    ))}
                  </div>
               </Card>
            </div>

            <Card className="bg-primary p-8 text-white">
               <div className="flex flex-col md:flex-row justify-between items-center gap-8">
                  <div>
                    <p className="text-primary-foreground/60 text-[10px] font-bold uppercase tracking-[0.2em] mb-2">Class Overview Stats</p>
                    <h3 className="text-2xl font-black uppercase tracking-tight">Analytical Summary</h3>
                  </div>
                  <div className="flex flex-wrap items-center gap-12">
                    <div className="text-center">
                      <p className="text-5xl font-black tracking-tighter">{classPerformance.classAverageGPA.toFixed(2)}</p>
                      <p className="text-primary-foreground/40 text-[10px] font-bold uppercase tracking-widest mt-2">Class Avg GPA</p>
                    </div>
                    <div className="text-center">
                      <p className="text-5xl font-black tracking-tighter">{classPerformance.totalStudents}</p>
                      <p className="text-primary-foreground/40 text-[10px] font-bold uppercase tracking-widest mt-2">Evaluated Students</p>
                    </div>
                  </div>
               </div>
            </Card>
          </div>
        ) : (
          <div className="flex flex-col items-center justify-center py-32 text-center print:hidden">
            <div className="p-8 bg-slate-50 rounded-full border border-slate-100 mb-6 text-slate-200">
               <BarChart3 size={64} />
            </div>
            <h3 className="text-xl font-black text-slate-900 tracking-tight">Ready to Analyze</h3>
            <p className="text-slate-500 text-sm mt-2 max-w-[320px]">Select your parameters in the filter above to generate high-fidelity reports.</p>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { 
  Building2, 
  GraduationCap, 
  Users, 
  Palette, 
  Bell, 
  ShieldCheck, 
  Save,
  Plus,
  Edit2,
  Trash2,
  Upload,
  Loader2,
  Image as ImageIcon,
  Database,
  Download as DownloadIcon,
  Cloud as CloudIcon,
  Zap,
  FileUp,
  Info
} from 'lucide-react';
import api from '@/lib/api';
import { useAppDispatch, useAppSelector } from '@/lib/hooks';
import { 
  fetchSchoolProfile, 
  updateSchoolProfileThunk, 
  uploadSchoolLogoThunk,
  fetchSystemSettings, 
  updateSystemSettingsThunk,
  fetchUsers,
  updateUserThunk,
  deleteUserThunk,
  triggerEndOfDayThunk,
  triggerBackupThunk,
  fetchGradeScales,
  createGradeScaleThunk,
  updateGradeScaleThunk,
  deleteGradeScaleThunk,
  selectSchoolProfile,
  selectSystemSettings,
  selectUsers,
  selectGradeScales
} from '@/lib/features/settingsSlice';
import { 
  selectClasses, 
  selectSubjects, 
  selectExamTypes, 
  fetchConfig,
  addClassThunk,
  addSubjectThunk,
  addExamTypeThunk,
  updateExamTypeThunk,
  deleteClassThunk,
  deleteSubjectThunk,
  deleteExamTypeThunk
} from '@/lib/features/configSlice';
import { Card, CardHeader, CardTitle, CardContent, CardDescription } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Modal } from '@/components/ui/Modal';
import { ConfirmationModal } from '@/components/ui/ConfirmationModal';
import { User } from '@/types/models';
import toast from 'react-hot-toast';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { schoolProfileSchema, SchoolProfileFormData } from '@/lib/validations';
import BackupManager from '@/components/settings/BackupManager';
import { CSVImporter } from '@/components/ui/CSVImporter';

type TabId = 'profile' | 'academic' | 'grading' | 'users' | 'theme' | 'notifications' | 'security' | 'database';

export default function SettingsPage() {
  const dispatch = useAppDispatch();
  const [activeTab, setActiveTab] = useState<TabId>('profile');
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const [testWhatsAppPhone, setTestWhatsAppPhone] = useState('');

  // Selectors
  const schoolProfile = useAppSelector(selectSchoolProfile);
  const systemSettings = useAppSelector(selectSystemSettings);
  const users = useAppSelector(selectUsers);
  const gradeScales = useAppSelector(selectGradeScales);
  const classes = useAppSelector(selectClasses);
  const subjects = useAppSelector(selectSubjects);
  const examTypes = useAppSelector(selectExamTypes);

  // Grade Scale State
  const [isGradeScaleModalOpen, setIsGradeScaleModalOpen] = useState(false);
  const [isEditingScale, setIsEditingScale] = useState(false);
  const [selectedScale, setSelectedScale] = useState<any>(null);
  const [scaleFormData, setScaleFormData] = useState({
    grade: '',
    minScore: '',
    maxScore: '',
    points: ''
  });

  // Forms
// ... existing code ...
  const {
    register: registerProfile,
    handleSubmit: handleSubmitProfile,
    reset: resetProfile,
    watch,
    formState: { errors: profileErrors },
  } = useForm<SchoolProfileFormData>({
    resolver: zodResolver(schoolProfileSchema),
  });

  const [settingsData, setSettingsData] = useState<Record<string, string>>({});
  const [isTriggering, setIsTriggering] = useState(false);
  const [isUploadingLogo, setIsUploadingLogo] = useState(false);

  const handleLogoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Validate file size (2MB)
    if (file.size > 2 * 1024 * 1024) {
      toast.error('File size must be less than 2MB');
      return;
    }

    setIsUploadingLogo(true);
    try {
      const resultAction = await dispatch(uploadSchoolLogoThunk(file));
      if (uploadSchoolLogoThunk.fulfilled.match(resultAction)) {
        const logoUrl = resultAction.payload as string;
        // Update the form field
        resetProfile({ ...schoolProfile as any, logo: logoUrl });
        toast.success('Logo uploaded successfully. Save the profile to apply changes.');
      } else {
        toast.error('Failed to upload logo');
      }
    } catch (err) {
      toast.error('Error uploading logo');
    } finally {
      setIsUploadingLogo(false);
    }
  };

  // Modal States
  const [confirmModal, setConfirmModal] = useState({
    isOpen: false,
    title: '',
    message: '',
    confirmText: 'Confirm',
    destructive: false,
    onConfirm: () => {}
  });
  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<Partial<User> | null>(null);
  const [academicModal, setAcademicModal] = useState<{ 
    isOpen: boolean; 
    type: 'class' | 'subject' | 'examType'; 
    value: string;
    baseMark?: number;
    weightage?: number;
    isFinal?: boolean;
    category?: 'TUTORIAL' | 'FINAL';
    termNumber?: number;
    isEditing?: boolean;
  }>({
    isOpen: false,
    type: 'class',
    value: '',
    baseMark: 100,
    weightage: 100,
    isFinal: false,
    category: 'FINAL',
    termNumber: 1
  });

  useEffect(() => {
    dispatch(fetchSchoolProfile());
    dispatch(fetchSystemSettings());
    dispatch(fetchUsers());
    dispatch(fetchConfig());
  }, [dispatch]);

  // Sync profile data
  useEffect(() => {
    if (schoolProfile) {
      resetProfile({
        name: schoolProfile.name || '',
        address: schoolProfile.address || '',
        phone: schoolProfile.phone || '',
        email: schoolProfile.email || '',
        academicYear: schoolProfile.academicYear || '',
        website: schoolProfile.website || '',
        logo: schoolProfile.logo || ''
      });
    }
  }, [schoolProfile, resetProfile]);

  // Sync settings data
  useEffect(() => {
    if (systemSettings) {
      setSettingsData(systemSettings);
    }
  }, [systemSettings]);

  const onProfileSave = (data: SchoolProfileFormData) => {
    dispatch(updateSchoolProfileThunk(data))
      .unwrap()
      .then(() => toast.success('School profile updated successfully'))
      .catch((err) => toast.error(err || 'Failed to update profile'));
  };

  const handleSettingsSave = (e: React.FormEvent) => {
    e.preventDefault();
    dispatch(updateSystemSettingsThunk(settingsData))
      .unwrap()
      .then(() => toast.success('Settings updated successfully'))
      .catch((err) => toast.error(err || 'Failed to update settings'));
  };

  const handleSettingChange = (key: string, value: string) => {
    setSettingsData(prev => ({ ...prev, [key]: value }));
  };

  const handleResetTheme = () => {
    setSettingsData(prev => ({
      ...prev,
      theme: 'light',
      compactMode: 'false',
      accentColor: '#2563eb'
    }));
    toast.success('Theme preferences reset to defaults. Click Save to apply.');
  };

  const handleTriggerEndOfDay = () => {
    setIsTriggering(true);
    dispatch(triggerEndOfDayThunk())
      .unwrap()
      .then((msg) => toast.success(msg || 'End of day tasks completed'))
      .catch((err) => toast.error(err || 'Failed to run tasks'))
      .finally(() => setIsTriggering(false));
  };

  const handleTriggerBackup = () => {
    setIsTriggering(true);
    dispatch(triggerBackupThunk())
      .unwrap()
      .then((data: any) => {
        toast.success(`Backup successful: ${data.filename}`);
      })
      .catch((err) => toast.error(err || 'Backup failed'))
      .finally(() => setIsTriggering(false));
  };

  const handleTestWhatsApp = async () => {
    if (!testWhatsAppPhone) {
      toast.error('Enter a phone number to test');
      return;
    }
    setIsTriggering(true);
    try {
      await api.post('/settings/whatsapp-test', { phone: testWhatsAppPhone });
      toast.success('Test WhatsApp message sent!');
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'Failed to send test message');
    } finally {
      setIsTriggering(false);
    }
  };

  // User Handlers
  const handleEditUser = (user: User) => {
    setEditingUser(user);
    setIsUserModalOpen(true);
  };

  const handleDeleteUser = (userId: number) => {
    setConfirmModal({
      isOpen: true,
      title: 'Delete User',
      message: 'Are you sure you want to delete this user? This action cannot be undone.',
      confirmText: 'Delete',
      destructive: true,
      onConfirm: () => {
        dispatch(deleteUserThunk(userId))
          .unwrap()
          .then(() => {
            toast.success('User deleted successfully');
            dispatch(fetchUsers());
          })
          .catch((err) => toast.error(err || 'Failed to delete user'));
      }
    });
  };

  const handleUpdateUser = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingUser) return;
    dispatch(updateUserThunk(editingUser))
      .unwrap()
      .then(() => {
        toast.success('User updated successfully');
        setIsUserModalOpen(false);
        dispatch(fetchUsers());
      })
      .catch((err) => toast.error(err || 'Failed to update user'));
  };

  // Grade Scale Handlers
  useEffect(() => {
    if (activeTab === 'grading') {
      dispatch(fetchGradeScales());
    }
  }, [activeTab, dispatch]);

  const handleAddGradeScale = () => {
    setIsEditingScale(false);
    setScaleFormData({ grade: '', minScore: '', maxScore: '', points: '' });
    setIsGradeScaleModalOpen(true);
  };

  const handleEditGradeScale = (scale: any) => {
    setIsEditingScale(true);
    setSelectedScale(scale);
    setScaleFormData({
      grade: scale.grade,
      minScore: scale.minScore.toString(),
      maxScore: scale.maxScore.toString(),
      points: scale.points.toString()
    });
    setIsGradeScaleModalOpen(true);
  };

  const handleDeleteGradeScale = (id: number) => {
    setConfirmModal({
      isOpen: true,
      title: 'Delete Grade Scale',
      message: 'Are you sure you want to delete this grade scale entry?',
      confirmText: 'Delete',
      destructive: true,
      onConfirm: () => {
        dispatch(deleteGradeScaleThunk(id))
          .unwrap()
          .then(() => {
             toast.success('Grade scale deleted');
             dispatch(fetchGradeScales());
             setConfirmModal(prev => ({ ...prev, isOpen: false }));
          })
          .catch(err => toast.error(err));
      }
    });
  };

  const handleGradeScaleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const data = {
      grade: scaleFormData.grade,
      minScore: parseFloat(scaleFormData.minScore),
      maxScore: parseFloat(scaleFormData.maxScore),
      points: parseFloat(scaleFormData.points)
    };

    if (isEditingScale && selectedScale) {
      dispatch(updateGradeScaleThunk({ id: selectedScale.id, ...data }))
        .unwrap()
        .then(() => {
          toast.success('Grade scale updated');
          setIsGradeScaleModalOpen(false);
        })
        .catch(err => toast.error(err));
    } else {
      dispatch(createGradeScaleThunk(data))
        .unwrap()
        .then(() => {
          toast.success('Grade scale created');
          setIsGradeScaleModalOpen(false);
        })
        .catch(err => toast.error(err));
    }
  };

  const handleDeleteAcademic = (type: 'class' | 'subject' | 'examType', name: string) => {
    setConfirmModal({
      isOpen: true,
      title: `Delete ${type}`,
      message: `Are you sure you want to delete this ${type}? This will remove all associated data.`,
      confirmText: 'Delete',
      destructive: true,
      onConfirm: () => {
        let thunk: any;
        if (type === 'class') thunk = deleteClassThunk;
        else if (type === 'subject') thunk = deleteSubjectThunk;
        else thunk = deleteExamTypeThunk;

        dispatch(thunk(name))
          .unwrap()
          .then(() => {
            toast.success(`${type} deleted successfully`);
            dispatch(fetchConfig());
            setConfirmModal(prev => ({ ...prev, isOpen: false }));
          })
          .catch((err: any) => toast.error(err || `Failed to delete ${type}`));
      }
    });
  };

  // Academic Handlers
  const handleAddAcademic = (type: 'class' | 'subject' | 'examType') => {
    setAcademicModal({ 
      isOpen: true, 
      type, 
      value: '', 
      baseMark: 100, 
      weightage: 100, 
      isFinal: false, 
      category: 'FINAL', 
      termNumber: 1, 
      isEditing: false 
    });
  };

  const handleEditExamType = (exam: any) => {
    setAcademicModal({ 
      isOpen: true, 
      type: 'examType', 
      value: exam.value, 
      baseMark: exam.baseMark,
      weightage: exam.weightage || 100,
      isFinal: exam.isFinal || false,
      category: exam.category || 'FINAL',
      termNumber: exam.termNumber || 1,
      isEditing: true 
    });
  };

  const submitAcademic = (e: React.FormEvent) => {
    e.preventDefault();
    const { type, value, baseMark, weightage, isFinal, category, termNumber, isEditing } = academicModal;
    if (!value.trim()) return;

    let thunk: any;
    let payload: any = value;

    if (type === 'class') thunk = addClassThunk;
    else if (type === 'subject') thunk = addSubjectThunk;
    else {
      if (isEditing) {
        thunk = updateExamTypeThunk;
        payload = { 
          name: value, 
          baseMark: baseMark || 100,
          weightage: weightage || 100,
          isFinal: isFinal || false,
          category: category || 'FINAL',
          termNumber: termNumber || 1
        };
      } else {
        thunk = addExamTypeThunk;
        payload = { 
          name: value, 
          baseMark: baseMark || 100,
          weightage: weightage || 100,
          isFinal: isFinal || false,
          category: category || 'FINAL',
          termNumber: termNumber || 1
        };
      }
    }

    dispatch(thunk(payload))
      .unwrap()
      .then(() => {
        toast.success(`${type.charAt(0).toUpperCase() + type.slice(1)} ${isEditing ? 'updated' : 'added'} successfully`);
        setAcademicModal({ ...academicModal, isOpen: false, value: '' });
        dispatch(fetchConfig());
      })
      .catch((err: any) => toast.error(err || `Failed to ${isEditing ? 'update' : 'add'} ${type}`));
  };

  const TABS: { id: TabId; label: string; icon: any }[] = [
    { id: 'profile', label: 'School Profile', icon: Building2 },
    { id: 'academic', label: 'Academic Settings', icon: GraduationCap },
    { id: 'grading', label: 'Grade Scale', icon: ShieldCheck },
    { id: 'users', label: 'User Management', icon: Users },
    { id: 'theme', label: 'Theme & UI', icon: Palette },
    { id: 'notifications', label: 'Notifications', icon: Bell },
    { id: 'security', label: 'Security', icon: ShieldCheck },
    { id: 'database', label: 'Database & Backup', icon: Database },
  ];

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-12">
      <div>
        <h1 className="text-3xl font-bold text-foreground tracking-tight">System Settings</h1>
        <p className="text-muted-foreground font-medium mt-1">Configure global platform preferences and organization profiles.</p>
      </div>

      <div className="flex flex-col lg:flex-row gap-8">
        {/* Sidebar Tabs */}
        <div className="w-full lg:w-64 shrink-0 space-y-1">
          {TABS.map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-semibold transition-all ${
                activeTab === tab.id 
                  ? 'bg-primary text-white shadow-md shadow-primary/20' 
                  : 'text-muted-foreground hover:bg-muted hover:text-foreground'
              }`}
            >
              <tab.icon size={18} className={activeTab === tab.id ? 'opacity-100' : 'opacity-70'} />
              {tab.label}
            </button>
          ))}
        </div>

        {/* Content Area */}
        <div className="flex-1">
          
          {/* PROFILE TAB */}
          {activeTab === 'profile' && (
            <Card className="border-border shadow-sm">
              <CardHeader className="border-b border-border bg-muted/50 pb-6">
                <CardTitle className="text-xl">School Profile</CardTitle>
                <CardDescription>Manage the primary identity and contact details of your institution.</CardDescription>
              </CardHeader>
              <CardContent className="p-6">
                <form onSubmit={handleSubmitProfile(onProfileSave)} className="space-y-6">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <Input 
                      label="Institution Name"
                      placeholder="e.g. EduTrack Academy"
                      {...registerProfile('name')}
                      error={profileErrors.name?.message}
                    />
                    <Input 
                      label="Academic Year"
                      placeholder="e.g. 2026-2027"
                      {...registerProfile('academicYear')}
                      error={profileErrors.academicYear?.message}
                    />
                    <Input 
                      label="Contact Email"
                      type="email"
                      placeholder="admin@school.com"
                      {...registerProfile('email')}
                      error={profileErrors.email?.message}
                    />
                    <Input 
                      label="Contact Phone"
                      placeholder="+1 (555) 000-0000"
                      {...registerProfile('phone')}
                      error={profileErrors.phone?.message}
                    />
                    <Input 
                      label="Website URL"
                      placeholder="https://www.school.com"
                      {...registerProfile('website')}
                      error={profileErrors.website?.message}
                    />
                    
                    <div className="space-y-2">
                      <label className="text-sm font-bold text-slate-700 ml-0.5">School Logo</label>
                      <div className="flex items-center gap-4">
                        <div className="h-16 w-16 rounded-xl border-2 border-dashed border-slate-200 bg-slate-50 flex items-center justify-center overflow-hidden">
                          {watch('logo') ? (
                            <img src={watch('logo')} alt="School Logo" className="h-full w-full object-contain" />
                          ) : (
                            <ImageIcon size={24} className="text-slate-300" />
                          )}
                        </div>
                        <div className="flex-1">
                          <label className={`
                            flex items-center justify-center gap-2 px-4 py-2 rounded-lg border border-slate-200 bg-white 
                            text-sm font-bold text-slate-700 cursor-pointer hover:bg-slate-50 transition-colors
                            ${isUploadingLogo ? 'opacity-50 cursor-not-allowed' : ''}
                          `}>
                            {isUploadingLogo ? (
                              <Loader2 size={16} className="animate-spin" />
                            ) : (
                              <Upload size={16} />
                            )}
                            {isUploadingLogo ? 'Uploading...' : 'Upload New Logo'}
                            <input 
                              type="file" 
                              className="hidden" 
                              accept="image/*" 
                              onChange={handleLogoUpload}
                              disabled={isUploadingLogo}
                            />
                          </label>
                          <p className="text-[10px] text-slate-500 mt-1 font-medium">PNG, JPG or SVG (Max 2MB)</p>
                        </div>
                      </div>
                      <input type="hidden" {...registerProfile('logo')} />
                    </div>

                    <div className="md:col-span-2">
                      <Input 
                        label="Physical Address"
                        placeholder="123 Education Blvd, Knowledge City"
                        {...registerProfile('address')}
                        error={profileErrors.address?.message}
                      />
                    </div>
                  </div>
                  <div className="flex justify-end pt-4 border-t border-border">
                    <Button type="submit" className="px-8 shadow-lg shadow-blue-200">
                      <Save size={18} className="mr-2" /> Save Profile
                    </Button>
                  </div>
                </form>
              </CardContent>
            </Card>
          )}

          {/* ACADEMIC TAB */}
          {activeTab === 'academic' && (
            <div className="space-y-6">
              <Card className="border-border shadow-sm">
                <CardHeader className="border-b border-border bg-muted/50 pb-6">
                  <CardTitle className="text-xl font-black">Academic Structure</CardTitle>
                  <CardDescription>Define how the academic year is divided.</CardDescription>
                </CardHeader>
                <CardContent className="p-6">
                  <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4 max-w-xl">
                    <div>
                      <h4 className="font-bold text-foreground text-sm">Terms per Year</h4>
                      <p className="text-muted-foreground text-xs mt-1">Select 2 (Bi-annual) or 3 (Trimester) terms.</p>
                    </div>
                    <div className="flex bg-slate-100 p-1 rounded-lg">
                      <button 
                        onClick={() => handleSettingChange('academicStructure', '2_TERMS')}
                        className={`px-6 py-2 rounded-md text-xs font-black transition-all ${settingsData.academicStructure === '2_TERMS' ? 'bg-white shadow-sm text-primary' : 'text-slate-500'}`}
                      >
                        2 TERMS
                      </button>
                      <button 
                        onClick={() => handleSettingChange('academicStructure', '3_TERMS')}
                        className={`px-6 py-2 rounded-md text-xs font-black transition-all ${settingsData.academicStructure === '3_TERMS' ? 'bg-white shadow-sm text-primary' : 'text-slate-500'}`}
                      >
                        3 TERMS
                      </button>
                    </div>
                  </div>
                  <div className="mt-6 flex justify-start">
                    <Button onClick={handleSettingsSave} size="sm" className="gap-2">
                       <Save size={14} /> Save Structure
                    </Button>
                  </div>
                </CardContent>
              </Card>

              <Card className="border-border shadow-sm">
                <CardHeader className="border-b border-border bg-muted/50 pb-4">
                  <div className="flex justify-between items-center">
                    <div>
                      <CardTitle className="text-lg">Configured Classes</CardTitle>
                      <CardDescription>Active grades and class levels</CardDescription>
                    </div>
                    <Button variant="outline" size="sm" className="min-h-[44px]" onClick={() => handleAddAcademic('class')}><Plus size={16} className="mr-1"/> Add Class</Button>
                  </div>
                </CardHeader>
                <CardContent className="p-6">
                  <div className="flex flex-wrap gap-3">
                    {classes.map(c => (
                      <div key={c.value} className="group relative flex items-center">
                        <span className="px-4 py-2 rounded-lg bg-blue-50 dark:bg-blue-900/30 text-blue-800 font-bold border border-blue-100 dark:border-blue-800 pr-10">
                          {c.label}
                        </span>
                        <button 
                          onClick={() => handleDeleteAcademic('class', c.value)}
                          className="absolute right-2 p-1 text-red-400 hover:text-red-600 hover:bg-red-50 rounded opacity-0 group-hover:opacity-100 transition-opacity"
                        >
                          <Trash2 size={14} />
                        </button>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>

              <Card className="border-border shadow-sm">
                <CardHeader className="border-b border-border bg-muted/50 pb-4">
                  <div className="flex justify-between items-center">
                    <div>
                      <CardTitle className="text-lg">Academic Subjects</CardTitle>
                      <CardDescription>Curriculum subjects taught across classes</CardDescription>
                    </div>
                    <Button variant="outline" size="sm" className="min-h-[44px]" onClick={() => handleAddAcademic('subject')}><Plus size={16} className="mr-1"/> Add Subject</Button>
                  </div>
                </CardHeader>
                <CardContent className="p-6">
                  <div className="flex flex-wrap gap-3">
                    {subjects.map(s => (
                      <div key={s.value} className="group relative flex items-center">
                        <span className="px-4 py-2 rounded-lg bg-emerald-50 dark:bg-emerald-900/30 text-emerald-700 font-bold border border-emerald-100 dark:border-emerald-800 pr-10">
                          {s.label}
                        </span>
                        <button 
                          onClick={() => handleDeleteAcademic('subject', s.value)}
                          className="absolute right-2 p-1 text-red-400 hover:text-red-600 hover:bg-red-50 rounded opacity-0 group-hover:opacity-100 transition-opacity"
                        >
                          <Trash2 size={14} />
                        </button>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>

              <Card className="border-border shadow-sm">
                <CardHeader className="border-b border-border bg-muted/50 pb-4">
                  <div className="flex justify-between items-center">
                    <div>
                      <CardTitle className="text-lg">Assessment Types</CardTitle>
                      <CardDescription>Standardized exam definitions</CardDescription>
                    </div>
                    <Button variant="outline" size="sm" className="min-h-[44px]" onClick={() => handleAddAcademic('examType')}><Plus size={16} className="mr-1"/> Add Exam Type</Button>
                  </div>
                </CardHeader>
                <CardContent className="p-6">
                  <div className="flex flex-wrap gap-4">
                    {examTypes.map(e => (
                      <div key={e.value} className="flex items-center gap-2 group">
                        <div className="flex flex-col px-4 py-2 rounded-lg bg-purple-50 dark:bg-purple-900/30 text-purple-700 font-bold border border-purple-100 dark:border-purple-800">
                          <span className="text-sm">{e.label}</span>
                          <span className="text-[10px] opacity-60 uppercase tracking-tighter font-black">Weight: {e.weightage}%</span>
                        </div>
                        <div className="flex flex-col gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button 
                            onClick={() => handleEditExamType(e)}
                            className="p-1 text-purple-600 dark:text-purple-400 hover:bg-purple-100 dark:hover:bg-purple-900/50 rounded"
                          >
                            <Edit2 size={14} />
                          </button>
                          <button 
                            onClick={() => handleDeleteAcademic('examType', e.value)}
                            className="p-1 text-red-500 hover:bg-red-50 rounded"
                          >
                            <Trash2 size={14} />
                          </button>
                        </div>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>
            </div>
          )}

          {/* USERS TAB */}
          {activeTab === 'users' && (
            <Card className="border-border shadow-sm overflow-hidden p-0">
              <CardHeader className="border-b border-border bg-muted/50 p-6 flex flex-row justify-between items-center mb-0">
                <div>
                  <CardTitle className="text-xl">Platform Users</CardTitle>
                  <CardDescription>Manage administrators and teachers.</CardDescription>
                </div>
                <div className="flex gap-2">
                  <Button variant="outline" onClick={() => setIsImportModalOpen(true)}>
                    <FileUp size={16} className="mr-2" /> Import Staff
                  </Button>
                  <Button><Plus size={16} className="mr-2" /> Invite User</Button>
                </div>
              </CardHeader>
              <div className="overflow-x-auto">
                <table className="w-full text-left text-sm">
                  <thead className="bg-muted/50 border-b border-border">
                    <tr>
                      <th className="px-6 py-4 font-bold text-muted-foreground uppercase tracking-wider text-xs">Name</th>
                      <th className="px-6 py-4 font-bold text-muted-foreground uppercase tracking-wider text-xs">Email</th>
                      <th className="px-6 py-4 font-bold text-muted-foreground uppercase tracking-wider text-xs">Role</th>
                      <th className="px-6 py-4 font-bold text-muted-foreground uppercase tracking-wider text-xs">Joined</th>
                      <th className="px-6 py-4 font-bold text-muted-foreground uppercase tracking-wider text-xs text-right">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-border bg-card">
                    {users.map(u => (
                      <tr key={u.id} className="hover:bg-muted/30 transition-colors group">
                        <td className="px-6 py-4 font-bold text-foreground">{u.name || 'Unknown'}</td>
                        <td className="px-6 py-4 text-muted-foreground font-medium">{u.email}</td>
                        <td className="px-6 py-4">
                          <span className={`px-2.5 py-1 rounded text-[10px] font-black tracking-widest ${
                            u.role === 'ADMIN' ? 'bg-amber-100 dark:bg-amber-900/30 text-amber-700' : 'bg-blue-100 dark:bg-blue-900/30 text-blue-700'
                          }`}>
                            {u.role}
                          </span>
                        </td>
                        <td className="px-6 py-4 text-muted-foreground">{new Date(u.createdAt || '').toLocaleDateString()}</td>
                        <td className="px-6 py-4 text-right">
                          <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button 
                              onClick={() => handleEditUser(u)}
                              className="p-1.5 text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded"
                            >
                              <Edit2 size={16} />
                            </button>
                            <button 
                              onClick={() => handleDeleteUser(u.id)}
                              className="p-1.5 text-red-600 hover:bg-red-50 dark:hover:bg-red-900/30 rounded"
                            >
                              <Trash2 size={16} />
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                    {users.length === 0 && (
                      <tr>
                        <td colSpan={5} className="px-6 py-8 text-center text-muted-foreground italic">No users found.</td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </Card>
          )}

          {/* THEME & UI TAB */}
          {activeTab === 'theme' && (
            <Card className="border-slate-200/60 shadow-sm">
              <CardHeader className="border-b border-slate-100 bg-slate-50/50 pb-6">
                <CardTitle className="text-xl">Theme & UI Preferences</CardTitle>
                <CardDescription>Customize the look and feel of the platform.</CardDescription>
              </CardHeader>
              <CardContent className="p-6">
                <form onSubmit={handleSettingsSave} className="space-y-6">
                  <div className="space-y-6 max-w-xl">
                    <div className="flex items-center justify-between">
                      <div>
                        <h4 className="font-bold text-foreground text-sm">Theme Mode</h4>
                        <p className="text-muted-foreground text-xs mt-1">Select the primary color scheme.</p>
                      </div>
                      <select 
                        value={settingsData.theme || 'light'} 
                        onChange={(e) => handleSettingChange('theme', e.target.value)}
                        className="h-10 px-4 rounded-lg border border-border bg-card text-foreground font-semibold text-sm outline-none transition-standard focus:ring-4 focus:ring-primary/10"
                      >
                        <option value="light" className="bg-card text-foreground">Light</option>
                        <option value="dark" className="bg-card text-foreground">Dark</option>
                        <option value="system" className="bg-card text-foreground">System Default</option>
                      </select>
                    </div>

                    <div className="flex items-center justify-between border-t border-border pt-6">
                      <div>
                        <h4 className="font-bold text-foreground text-sm">Compact Mode</h4>
                        <p className="text-muted-foreground text-xs mt-1">Reduce spacing in tables and lists for denser data viewing.</p>
                      </div>
                      <label className="relative inline-flex items-center cursor-pointer">
                        <input 
                          type="checkbox" 
                          checked={settingsData.compactMode === 'true'} 
                          onChange={(e) => handleSettingChange('compactMode', e.target.checked ? 'true' : 'false')}
                          className="sr-only peer" 
                        />
                        <div className="w-11 h-6 bg-slate-200 dark:bg-slate-700 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-primary/20 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-slate-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-primary"></div>
                      </label>
                    </div>

                    <div className="flex items-center justify-between border-t border-border pt-6">
                      <div>
                        <h4 className="font-bold text-foreground text-sm">Brand Accent Color</h4>
                        <p className="text-muted-foreground text-xs mt-1">Used for primary buttons and highlights.</p>
                      </div>
                      <input 
                        type="color" 
                        value={settingsData.accentColor || '#2563eb'}
                        onChange={(e) => handleSettingChange('accentColor', e.target.value)}
                        className="h-10 w-14 rounded cursor-pointer border border-border bg-card" 
                      />
                    </div>
                  </div>
                  <div className="flex justify-start gap-4 pt-6 border-t border-slate-100">
                    <Button type="submit" className="px-8 shadow-lg shadow-blue-200">
                      <Save size={18} className="mr-2" /> Save Preferences
                    </Button>
                    <Button type="button" variant="outline" onClick={handleResetTheme}>
                      Reset to Defaults
                    </Button>
                  </div>
                </form>
              </CardContent>
            </Card>
          )}

          {/* NOTIFICATIONS TAB */}
          {activeTab === 'notifications' && (
            <Card className="border-border shadow-sm">
              <CardHeader className="border-b border-border bg-muted/50 pb-6">
                <CardTitle className="text-xl">Notification Rules</CardTitle>
                <CardDescription>Manage automated alerts and system emails.</CardDescription>
              </CardHeader>
              <CardContent className="p-6">
                <form onSubmit={handleSettingsSave} className="space-y-6">
                  <div className="space-y-6 max-w-xl">
                    
                    <div className="flex items-center justify-between">
                      <div>
                        <h4 className="font-bold text-foreground text-sm">Daily Attendance Alerts</h4>
                        <p className="text-muted-foreground text-xs mt-1">Send summary emails to class teachers daily.</p>
                      </div>
                      <label className="relative inline-flex items-center cursor-pointer">
                        <input 
                          type="checkbox" 
                          checked={settingsData.attendanceAlerts === 'true'} 
                          onChange={(e) => handleSettingChange('attendanceAlerts', e.target.checked ? 'true' : 'false')}
                          className="sr-only peer" 
                        />
                        <div className="w-11 h-6 bg-slate-200 dark:bg-slate-700 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-primary/20 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-slate-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-primary"></div>
                      </label>
                    </div>

                    <div className="flex items-center justify-between border-t border-border pt-6">
                      <div>
                        <h4 className="font-bold text-foreground text-sm">Exam Mark Finalization</h4>
                        <p className="text-muted-foreground text-xs mt-1">Alert admins when subject marks are locked.</p>
                      </div>
                      <label className="relative inline-flex items-center cursor-pointer">
                        <input 
                          type="checkbox" 
                          checked={settingsData.marksAlerts === 'true'} 
                          onChange={(e) => handleSettingChange('marksAlerts', e.target.checked ? 'true' : 'false')}
                          className="sr-only peer" 
                        />
                        <div className="w-11 h-6 bg-slate-200 dark:bg-slate-700 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-primary/20 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-slate-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-primary"></div>
                      </label>
                    </div>

                    <div className="flex items-center justify-between border-t border-border pt-6">
                      <div>
                        <h4 className="font-bold text-foreground text-sm">Fee Billing Notifications</h4>
                        <p className="text-muted-foreground text-xs mt-1">Notify parents when vouchers are issued or payments confirmed.</p>
                      </div>
                      <label className="relative inline-flex items-center cursor-pointer">
                        <input 
                          type="checkbox" 
                          checked={settingsData.feeNotifications === 'true'} 
                          onChange={(e) => handleSettingChange('feeNotifications', e.target.checked ? 'true' : 'false')}
                          className="sr-only peer" 
                        />
                        <div className="w-11 h-6 bg-slate-200 dark:bg-slate-700 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-primary/20 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-slate-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-primary"></div>
                      </label>
                    </div>

                    <div className="flex items-center justify-between border-t border-border pt-6">
                      <div>
                        <h4 className="font-bold text-foreground text-sm">Parent Notifications</h4>
                        <p className="text-muted-foreground text-xs mt-1">Enable automated SMS/Email for parents (Requires API Gateway).</p>
                      </div>
                      <label className="relative inline-flex items-center cursor-pointer">
                        <input 
                          type="checkbox" 
                          checked={settingsData.parentNotifications === 'true'} 
                          onChange={(e) => handleSettingChange('parentNotifications', e.target.checked ? 'true' : 'false')}
                          className="sr-only peer" 
                        />
                        <div className="w-11 h-6 bg-slate-200 dark:bg-slate-700 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-primary/20 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-slate-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-primary"></div>
                      </label>
                    </div>

                    {/* WhatsApp Configuration */}
                    <div className="pt-8 border-t border-border space-y-6">
                       <div className="flex items-center gap-2">
                          <div className="p-2 rounded-lg bg-green-500/10 text-green-600">
                             <Zap size={18} />
                          </div>
                          <div>
                             <h4 className="font-bold text-foreground text-sm">WhatsApp Integration (Twilio)</h4>
                             <p className="text-muted-foreground text-xs mt-1">Configure your Twilio WhatsApp API for automated parent alerts.</p>
                          </div>
                       </div>

                       <div className="space-y-4 bg-slate-50 dark:bg-slate-900/50 p-6 rounded-2xl border border-border">
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                             <div className="space-y-2">
                                <label className="text-xs font-black uppercase tracking-widest text-slate-500">Twilio Account SID</label>
                                <Input 
                                   value={settingsData.twilioSid || ''} 
                                   onChange={(e) => handleSettingChange('twilioSid', e.target.value)} 
                                   placeholder="ACxxxxxxxxxxxxxxxx" 
                                />
                             </div>
                             <div className="space-y-2">
                                <label className="text-xs font-black uppercase tracking-widest text-slate-500">Twilio Auth Token</label>
                                <Input 
                                   type="password"
                                   value={settingsData.twilioToken || ''} 
                                   onChange={(e) => handleSettingChange('twilioToken', e.target.value)} 
                                   placeholder="••••••••••••••••" 
                                />
                             </div>
                             <div className="space-y-2">
                                <label className="text-xs font-black uppercase tracking-widest text-slate-500">Twilio WhatsApp Number</label>
                                <Input 
                                   value={settingsData.twilioNumber || ''} 
                                   onChange={(e) => handleSettingChange('twilioNumber', e.target.value)} 
                                   placeholder="whatsapp:+14155238886" 
                                />
                             </div>
                             <div className="flex flex-col justify-end">
                                <div className="flex items-center justify-between h-10 px-2">
                                   <span className="text-xs font-bold text-slate-700">Attendance via WhatsApp</span>
                                   <label className="relative inline-flex items-center cursor-pointer">
                                      <input 
                                         type="checkbox" 
                                         checked={settingsData.parentNotificationsWhatsApp === 'true'} 
                                         onChange={(e) => handleSettingChange('parentNotificationsWhatsApp', e.target.checked ? 'true' : 'false')}
                                         className="sr-only peer" 
                                      />
                                      <div className="w-9 h-5 bg-slate-200 dark:bg-slate-700 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-slate-300 after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-primary"></div>
                                   </label>
                                </div>
                                <div className="flex items-center justify-between h-10 px-2 border-t border-slate-200/50 mt-1">
                                   <span className="text-xs font-bold text-slate-700">Fee Alerts via WhatsApp</span>
                                   <label className="relative inline-flex items-center cursor-pointer">
                                      <input 
                                         type="checkbox" 
                                         checked={settingsData.feeNotificationsWhatsApp === 'true'} 
                                         onChange={(e) => handleSettingChange('feeNotificationsWhatsApp', e.target.checked ? 'true' : 'false')}
                                         className="sr-only peer" 
                                      />
                                      <div className="w-9 h-5 bg-slate-200 dark:bg-slate-700 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-slate-300 after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-primary"></div>
                                   </label>
                                </div>
                             </div>
                          </div>

                          <div className="pt-4 border-t border-border flex flex-col sm:flex-row gap-3 items-end">
                             <div className="flex-1 w-full">
                                <label className="text-xs font-black uppercase tracking-widest text-slate-500 mb-2 block">Test WhatsApp Message</label>
                                <Input 
                                   value={testWhatsAppPhone} 
                                   onChange={(e) => setTestWhatsAppPhone(e.target.value)} 
                                   placeholder="Enter phone with country code (e.g. +88017...)" 
                                />
                             </div>
                             <Button 
                                type="button" 
                                variant="soft" 
                                onClick={handleTestWhatsApp}
                                disabled={isTriggering}
                                className="min-w-[140px]"
                             >
                                {isTriggering ? <Loader2 size={16} className="animate-spin mr-2" /> : <Zap size={16} className="mr-2" />}
                                Send Test
                             </Button>
                          </div>
                       </div>
                    </div>

                  </div>
                  <div className="flex justify-start gap-4 pt-6 border-t border-border">
                    <Button type="submit" className="px-8 shadow-lg shadow-blue-200">
                      <Save size={18} className="mr-2" /> Save Notification Rules
                    </Button>
                    <Button type="button" variant="outline" onClick={handleTriggerEndOfDay} disabled={isTriggering}>
                      {isTriggering ? 'Running...' : 'Run End-of-Day Tasks Now'}
                    </Button>
                  </div>
                </form>
              </CardContent>
            </Card>
          )}

          {/* SECURITY TAB */}
          {activeTab === 'security' && (
            <Card className="border-border shadow-sm border-t-red-500 border-t-4">
              <CardHeader className="border-b border-border bg-muted/50 pb-6">
                <CardTitle className="text-xl">Security & Authentication</CardTitle>
                <CardDescription>Manage sessions and account security protocols.</CardDescription>
              </CardHeader>
              <CardContent className="p-6">
                <form onSubmit={handleSettingsSave} className="space-y-8">
                  <div className="max-w-xl space-y-6">
                    <div className="space-y-2">
                      <label className="text-sm font-bold text-foreground/80">JWT Session Timeout (Minutes)</label>
                      <Input 
                        type="number"
                        value={settingsData.sessionTimeout || '60'} 
                        onChange={(e) => handleSettingChange('sessionTimeout', e.target.value)} 
                        placeholder="e.g. 60" 
                      />
                      <p className="text-xs text-muted-foreground font-medium">Users will be forcibly logged out after this period of inactivity.</p>
                    </div>
                  </div>
                  
                  <div className="pt-6 border-t border-border max-w-xl">
                    <h3 className="text-sm font-bold text-foreground mb-4">Account Security</h3>
                    <Button type="button" variant="outline" className="text-foreground font-bold w-full md:w-auto">
                      Initiate Password Reset
                    </Button>
                    <p className="text-xs text-muted-foreground font-medium mt-3">A secure link will be emailed to your registered admin address.</p>
                  </div>

                  <div className="flex justify-start pt-6 border-t border-border">
                    <Button type="submit" className="px-8 shadow-lg shadow-blue-200">
                      <Save size={18} className="mr-2" /> Update Security Policies
                    </Button>
                  </div>
                </form>
              </CardContent>
            </Card>
          )}

          {/* GRADING TAB */}
          {activeTab === 'grading' && (
            <Card className="border-border shadow-sm overflow-hidden p-0">
              <CardHeader className="border-b border-border bg-muted/50 p-6 flex flex-row justify-between items-center mb-0">
                <div>
                  <CardTitle className="text-xl">Grade Scale Definitions</CardTitle>
                  <CardDescription>Map percentage ranges to letter grades and GPAs.</CardDescription>
                </div>
                <Button onClick={handleAddGradeScale}><Plus size={16} className="mr-2" /> Add Rule</Button>
              </CardHeader>
              <div className="overflow-x-auto">
                <table className="w-full text-left text-sm">
                  <thead className="bg-muted/50 border-b border-border">
                    <tr>
                      <th className="px-6 py-4 font-bold text-muted-foreground uppercase tracking-wider text-xs">Letter Grade</th>
                      <th className="px-6 py-4 font-bold text-muted-foreground uppercase tracking-wider text-xs">Min Score (%)</th>
                      <th className="px-6 py-4 font-bold text-muted-foreground uppercase tracking-wider text-xs">Max Score (%)</th>
                      <th className="px-6 py-4 font-bold text-muted-foreground uppercase tracking-wider text-xs">GP Points</th>
                      <th className="px-6 py-4 font-bold text-muted-foreground uppercase tracking-wider text-xs text-right">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-border bg-card">
                    {gradeScales?.map(scale => (
                      <tr key={scale.id} className="hover:bg-muted/30 transition-colors group">
                        <td className="px-6 py-4">
                          <span className="px-3 py-1 rounded-md bg-primary/10 text-primary font-black text-sm">
                            {scale.grade}
                          </span>
                        </td>
                        <td className="px-6 py-4 font-bold text-slate-700">{scale.minScore}%</td>
                        <td className="px-6 py-4 font-bold text-slate-700">{scale.maxScore}%</td>
                        <td className="px-6 py-4">
                          <span className="font-black text-emerald-600">{scale.points.toFixed(2)}</span>
                        </td>
                        <td className="px-6 py-4 text-right">
                          <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button 
                              onClick={() => handleEditGradeScale(scale)}
                              className="p-1.5 text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded"
                            >
                              <Edit2 size={16} />
                            </button>
                            <button 
                              onClick={() => handleDeleteGradeScale(scale.id)}
                              className="p-1.5 text-red-600 hover:bg-red-50 dark:hover:bg-red-900/30 rounded"
                            >
                              <Trash2 size={16} />
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                    {(gradeScales || []).length === 0 && (
                      <tr>
                        <td colSpan={5} className="px-6 py-8 text-center text-muted-foreground italic">
                          No custom grade scales defined. Using system defaults (80%=A, 70%=B, etc.)
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </Card>
          )}

          {/* DATABASE TAB */}
          {activeTab === 'database' && (
            <Card className="border-border shadow-sm">
              <CardHeader className="border-b border-border pb-6">
                <CardTitle className="text-xl">Database & Data Safeguard</CardTitle>
                <CardDescription>Configure automated backups and manage institutional data integrity.</CardDescription>
              </CardHeader>
              <CardContent className="p-6">
                <div className="space-y-8">
                  <div className="max-w-xl space-y-4">
                    <div className="p-4 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded-xl flex gap-4">
                       <ShieldCheck className="text-amber-600 shrink-0" size={24} />
                       <div>
                          <p className="text-sm font-bold text-amber-900">Data Protection</p>
                          <p className="text-xs text-amber-800 mt-0.5">Automated backups are scheduled to run daily at 2:00 AM. Ensure your backup path is accessible.</p>
                       </div>
                    </div>

                    <div className="space-y-2 pt-4">
                      <label className="text-sm font-bold text-foreground/80">Local Backup Path</label>
                      <div className="flex gap-2">
                        <Input 
                          value={settingsData.backupPath || ''} 
                          onChange={(e) => handleSettingChange('backupPath', e.target.value)} 
                          placeholder="e.g. C:\EduTracker\Backups or E:\" 
                        />
                        <Button onClick={handleSettingsSave} variant="outline" className="shrink-0">
                           <Save size={16} />
                        </Button>
                      </div>
                      <p className="text-[10px] text-muted-foreground font-medium italic">If left empty, backups will be stored in the application's root 'backups' folder.</p>
                    </div>

                    <div className="pt-6 border-t border-border">
                      <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
                         <div>
                            <h4 className="font-bold text-foreground text-sm">Manual Database Dump</h4>
                            <p className="text-muted-foreground text-xs mt-1">Trigger an immediate full SQL backup of the system.</p>
                         </div>
                         <Button onClick={handleTriggerBackup} disabled={isTriggering} className="gap-2 shadow-lg shadow-blue-200 min-w-[160px]">
                            {isTriggering ? <Loader2 size={16} className="animate-spin" /> : <DownloadIcon size={16} />}
                            {isTriggering ? 'Backing up...' : 'Backup Now'}
                         </Button>
                      </div>
                    </div>

                    <div className="pt-6 border-t border-border">
                       <BackupManager />
                    </div>

                    <div className="pt-8 border-t border-border space-y-6">
                       <div>
                          <h4 className="font-bold text-foreground text-sm flex items-center gap-2">
                             <CloudIcon size={18} className="text-blue-500" />
                             Cloud Backup (Google Drive)
                          </h4>
                          <p className="text-muted-foreground text-xs mt-1">Automatically sync your daily backups to Google Drive for off-site protection.</p>
                       </div>

                       <div className="space-y-4 max-w-xl">
                          <div className="flex items-center justify-between">
                            <label className="text-sm font-bold text-foreground/80">Enable Cloud Sync</label>
                            <label className="relative inline-flex items-center cursor-pointer">
                              <input 
                                type="checkbox" 
                                checked={settingsData.googleDriveEnabled === 'true'} 
                                onChange={(e) => handleSettingChange('googleDriveEnabled', e.target.checked ? 'true' : 'false')}
                                className="sr-only peer" 
                              />
                              <div className="w-11 h-6 bg-slate-200 dark:bg-slate-700 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-primary/20 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-slate-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-primary"></div>
                            </label>
                          </div>

                          <div className="space-y-2">
                            <label className="text-sm font-bold text-foreground/80">Google Drive Folder ID</label>
                            <Input 
                              value={settingsData.googleDriveFolderId || ''} 
                              onChange={(e) => handleSettingChange('googleDriveFolderId', e.target.value)} 
                              placeholder="Paste the Folder ID from the Drive URL" 
                            />
                            <p className="text-[10px] text-muted-foreground italic">Share the folder with your service account email as an Editor.</p>
                          </div>

                          <div className="space-y-2">
                            <label className="text-sm font-bold text-foreground/80">Service Account Credentials (JSON)</label>
                            <textarea
                              value={settingsData.googleDriveCredentials || ''}
                              onChange={(e) => handleSettingChange('googleDriveCredentials', e.target.value)}
                              placeholder="Paste the contents of your credentials.json file here"
                              className="w-full h-32 p-3 text-xs font-mono rounded-lg border border-border bg-muted/30 focus:ring-2 focus:ring-primary/20 outline-none"
                            />
                          </div>

                          <div className="flex justify-start">
                             <Button onClick={handleSettingsSave} className="shadow-lg shadow-blue-200">
                                <Save size={16} className="mr-2" /> Save Cloud Configuration
                             </Button>
                          </div>
                          
                          {settingsData.lastCloudBackupRun && (
                            <p className="text-[10px] text-muted-foreground font-medium italic">
                               Last successful cloud sync: <span className="font-bold text-foreground">{new Date(settingsData.lastCloudBackupRun).toLocaleString()}</span>
                            </p>
                          )}
                       </div>
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>
          )}

        </div>
      </div>

      {/* Grade Scale Modal */}
      <Modal
        isOpen={isGradeScaleModalOpen}
        onClose={() => setIsGradeScaleModalOpen(false)}
        title={isEditingScale ? 'Edit Grading Rule' : 'New Grading Rule'}
      >
        <form onSubmit={handleGradeScaleSubmit} className="space-y-4">
          <Input 
            label="Letter Grade (e.g. A+)"
            value={scaleFormData.grade}
            onChange={(e) => setScaleFormData(prev => ({ ...prev, grade: e.target.value }))}
            required
            autoFocus
          />
          <div className="grid grid-cols-2 gap-4">
            <Input 
              label="Min Score %"
              type="number"
              step="0.01"
              value={scaleFormData.minScore}
              onChange={(e) => setScaleFormData(prev => ({ ...prev, minScore: e.target.value }))}
              required
            />
            <Input 
              label="Max Score %"
              type="number"
              step="0.01"
              value={scaleFormData.maxScore}
              onChange={(e) => setScaleFormData(prev => ({ ...prev, maxScore: e.target.value }))}
              required
            />
          </div>
          <Input 
            label="Grade Points (e.g. 4.00)"
            type="number"
            step="0.01"
            value={scaleFormData.points}
            onChange={(e) => setScaleFormData(prev => ({ ...prev, points: e.target.value }))}
            required
          />
          <div className="flex justify-end gap-3 pt-4">
            <Button type="button" variant="outline" onClick={() => setIsGradeScaleModalOpen(false)}>Cancel</Button>
            <Button type="submit">{isEditingScale ? 'Update Rule' : 'Create Rule'}</Button>
          </div>
        </form>
      </Modal>

      {/* Edit User Modal */}
      <Modal
        isOpen={isUserModalOpen}
        onClose={() => setIsUserModalOpen(false)}
        title="Edit User Profile"
      >
        <form onSubmit={handleUpdateUser} className="space-y-4">
          <Input 
            label="Full Name"
            value={editingUser?.name || ''}
            onChange={(e) => setEditingUser(prev => ({ ...prev, name: e.target.value }))}
          />
          <Input 
            label="Email Address"
            type="email"
            value={editingUser?.email || ''}
            onChange={(e) => setEditingUser(prev => ({ ...prev, email: e.target.value }))}
          />
          <div className="space-y-1">
            <label className="text-sm font-bold text-slate-700">Role</label>
            <select
              value={editingUser?.role || 'TEACHER'}
              onChange={(e) => setEditingUser(prev => ({ ...prev, role: e.target.value as any }))}
              className="w-full h-10 px-4 rounded-lg border border-slate-200 bg-white text-sm outline-none focus:ring-2 focus:ring-primary/20"
            >
              <option value="ADMIN">Admin</option>
              <option value="PRINCIPAL">Principal</option>
              <option value="TEACHER">Teacher</option>
              <option value="ACCOUNTANT">Accountant</option>
              <option value="LIBRARIAN">Librarian</option>
              <option value="STAFF">General Staff</option>
              <option value="CLERK">Clerk</option>
              <option value="SECURITY">Security</option>
              <option value="CLEANER">Cleaner</option>
            </select>
          </div>
          <div className="flex justify-end gap-3 pt-4">
            <Button type="button" variant="outline" onClick={() => setIsUserModalOpen(false)}>Cancel</Button>
            <Button type="submit">Update User</Button>
          </div>
        </form>
      </Modal>

      {/* Academic Add Modal */}
      <Modal
        isOpen={academicModal.isOpen}
        onClose={() => setAcademicModal({ ...academicModal, isOpen: false })}
        title={academicModal.isEditing ? `Edit ${academicModal.type.charAt(0).toUpperCase() + academicModal.type.slice(1)}` : `Add New ${academicModal.type.charAt(0).toUpperCase() + academicModal.type.slice(1)}`}
      >
        <form onSubmit={submitAcademic} className="space-y-4">
          <Input 
            label="Name"
            placeholder={`e.g. ${academicModal.type === 'class' ? 'Class 11' : academicModal.type === 'subject' ? 'Physics' : 'Mid Term'}`}
            value={academicModal.value}
            onChange={(e) => setAcademicModal({ ...academicModal, value: e.target.value })}
            disabled={academicModal.isEditing}
            autoFocus
          />
          {academicModal.type === 'examType' && (
            <div className="space-y-4">
              <Input 
                label="Base Mark (Maximum Score)"
                type="number"
                placeholder="e.g. 100"
                value={academicModal.baseMark ?? ''}
                onChange={(e) => setAcademicModal({ ...academicModal, baseMark: Number(e.target.value) })}
              />
              <Input 
                label="Weightage (%)"
                type="number"
                placeholder="e.g. 30"
                value={academicModal.weightage ?? ''}
                onChange={(e) => setAcademicModal({ ...academicModal, weightage: Number(e.target.value) })}
              />
              
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-sm font-bold text-slate-700">Exam Category</label>
                  <select
                    value={academicModal.category}
                    onChange={(e) => setAcademicModal({ ...academicModal, category: e.target.value as any })}
                    className="w-full h-10 px-4 rounded-lg border border-slate-200 bg-white text-sm outline-none focus:ring-2 focus:ring-primary/20"
                  >
                    <option value="FINAL">Final/Term Exam</option>
                    <option value="TUTORIAL">Class Test / Tutorial</option>
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-sm font-bold text-slate-700">Term Number</label>
                  <select
                    value={academicModal.termNumber}
                    onChange={(e) => setAcademicModal({ ...academicModal, termNumber: Number(e.target.value) })}
                    className="w-full h-10 px-4 rounded-lg border border-slate-200 bg-white text-sm outline-none focus:ring-2 focus:ring-primary/20"
                  >
                    <option value={1}>Term 1</option>
                    <option value={2}>Term 2</option>
                    <option value={3}>Term 3</option>
                  </select>
                </div>
              </div>

              <div className="flex items-center justify-between border-t border-border pt-4">
                <div>
                  <h4 className="font-bold text-foreground text-sm">Is Final Exam?</h4>
                  <p className="text-muted-foreground text-[10px] mt-1">If true, this exam type will not be included in combined annual calculations.</p>
                </div>
                <label className="relative inline-flex items-center cursor-pointer">
                  <input 
                    type="checkbox" 
                    checked={academicModal.isFinal === true} 
                    onChange={(e) => setAcademicModal({ ...academicModal, isFinal: e.target.checked })}
                    className="sr-only peer" 
                  />
                  <div className="w-9 h-5 bg-slate-200 dark:bg-slate-700 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-slate-300 after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-primary"></div>
                </label>
              </div>
            </div>
          )}
          <div className="flex justify-end gap-3 pt-4">
            <Button type="button" variant="outline" onClick={() => setAcademicModal({ ...academicModal, isOpen: false })}>Cancel</Button>
            <Button type="submit">{academicModal.isEditing ? 'Update' : 'Add'} {academicModal.type.charAt(0).toUpperCase() + academicModal.type.slice(1)}</Button>
          </div>
        </form>
      </Modal>

      <ConfirmationModal 
        {...confirmModal} 
        onClose={() => setConfirmModal({ ...confirmModal, isOpen: false })} 
      />

      {/* Import CSV Modal */}
      <Modal
        isOpen={isImportModalOpen}
        onClose={() => setIsImportModalOpen(false)}
        title="Bulk Import Staff Members"
        className="max-w-xl"
      >
        <CSVImporter 
          type="staff" 
          onSuccess={() => {
            dispatch(fetchUsers());
          }}
          onClose={() => setIsImportModalOpen(false)}
        />
      </Modal>
    </div>
  );
}

"use client";

import React, { useEffect, useState, useRef } from 'react';
import { 
  Users, 
  UserPlus, 
  Search, 
  Shield, 
  Trash2, 
  Edit,
  AlertCircle,
  Camera,
  CheckCircle2,
  X,
  CreditCard,
  Phone,
  MapPin,
  Lock,
  Unlock
} from 'lucide-react';
import { useAppSelector, useAppDispatch } from '@/lib/hooks';
import { 
  fetchUsers, 
  createUserThunk, 
  updateUserThunk, 
  deleteUserThunk,
  selectAllUsers,
  selectUsersLoading,
  selectUsersError
} from '@/lib/features/usersSlice';
import { selectRole, selectUser, updateCurrentUser } from '@/lib/features/authSlice';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Select } from '@/components/ui/Select';
import { Modal } from '@/components/ui/Modal';
import { Skeleton } from '@/components/ui/Skeleton';
import { User, Role } from '@/types/models';
import { toast } from 'react-hot-toast';
import Image from 'next/image';

export default function StaffManagementPage() {
  const dispatch = useAppDispatch();
  const users = useAppSelector(selectAllUsers);
  const loading = useAppSelector(selectUsersLoading);
  const error = useAppSelector(selectUsersError);
  const currentUserRole = useAppSelector(selectRole);
  const currentUser = useAppSelector(selectUser);

  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [userToDelete, setUserToDelete] = useState<User | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    role: 'TEACHER' as Role,
    nid: '',
    phone: '',
    address: '',
    canLogin: true,
    profileImage: ''
  });

  useEffect(() => {
    dispatch(fetchUsers());
  }, [dispatch]);

  const filteredUsers = users.filter(user => 
    user.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    user.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
    user.nid?.includes(searchTerm)
  );

  const handleOpenModal = (user: User | null = null) => {
    if (user) {
      setEditingUser(user);
      setFormData({
        name: user.name || '',
        email: user.email,
        password: '',
        role: user.role,
        nid: user.nid || '',
        phone: user.phone || '',
        address: user.address || '',
        canLogin: user.canLogin,
        profileImage: user.profileImage || ''
      });
    } else {
      setEditingUser(null);
      setFormData({
        name: '',
        email: '',
        password: '',
        role: 'TEACHER',
        nid: '',
        phone: '',
        address: '',
        canLogin: true,
        profileImage: ''
      });
    }
    setIsModalOpen(true);
  };

  const handleSaveUser = async (e: React.FormEvent) => {
    e.preventDefault();
    
    // Logic: Teachers and Admins MUST have canLogin = true in this UI for consistency,
    // though the DB allows it. If it's a cleaner/security etc, we might default to false.
    const submissionData = { ...formData };
    if (!['ADMIN', 'TEACHER'].includes(formData.role)) {
       // Optional: you can force canLogin to false here if you want, 
       // but let's leave it to the user's choice in the checkbox.
    }

    try {
      if (editingUser) {
        const updatedUser = await dispatch(updateUserThunk({ ...editingUser, ...submissionData })).unwrap();
        
        // If the logged-in user is editing their own profile, update the auth state
        if (currentUser && currentUser.id === updatedUser.id) {
          dispatch(updateCurrentUser(updatedUser));
        }
        
        toast.success('Staff profile updated');
      } else {
        await dispatch(createUserThunk(submissionData)).unwrap();
        toast.success('Staff member added successfully');
      }
      setIsModalOpen(false);
    } catch (err: any) {
      toast.error(err || 'Failed to save staff member');
    }
  };

  const handleDeleteUser = async () => {
    if (!userToDelete) return;
    try {
      await dispatch(deleteUserThunk(userToDelete.id)).unwrap();
      toast.success('Staff member removed');
      setIsDeleteModalOpen(false);
      setUserToDelete(null);
    } catch (err: any) {
      toast.error(err || 'Failed to remove staff member');
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData({ ...formData, profileImage: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  if (currentUserRole !== 'ADMIN') {
    return (
      <div className="h-[60vh] flex flex-col items-center justify-center text-center space-y-4">
        <div className="h-16 w-16 bg-red-50 rounded-full flex items-center justify-center text-red-500">
          <Shield size={32} />
        </div>
        <h2 className="text-2xl font-black text-slate-900 tracking-tight">Access Restricted</h2>
        <p className="text-slate-500 max-w-md">Only administrators can access the staff management console.</p>
        <Button onClick={() => window.history.back()} className="min-h-[44px] w-full sm:w-auto">Go Back</Button>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
        <div className="space-y-1">
          <div className="flex items-center gap-2 text-primary font-black uppercase tracking-[0.2em] text-[10px]">
            <Shield size={12} />
            HR & Personnel Management
          </div>
          <h1 className="text-4xl font-black text-slate-900 tracking-tight">Institutional Staff</h1>
          <p className="text-slate-500 font-medium">Comprehensive database of all academic and support personnel.</p>
        </div>
        
        <Button onClick={() => handleOpenModal()} size="lg" className="min-h-[44px] rounded-2xl shadow-xl shadow-primary/20 font-black text-xs uppercase tracking-widest px-8 w-full sm:w-auto">
          <UserPlus size={18} className="mr-2" />
          Onboard New Staff
        </Button>
      </div>

      <Card className="border-none shadow-xl shadow-slate-200/40 bg-white overflow-hidden">
        <CardHeader className="border-b border-slate-50 px-6 py-4 flex flex-col md:flex-row items-center justify-between gap-4">
          <div className="relative w-full max-w-md">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <Input 
              placeholder="Search by name, email, or NID..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-10 h-11 bg-slate-50 border-none rounded-xl font-medium text-sm"
            />
          </div>
          <div className="flex items-center gap-2">
            <span className="text-xs font-black text-slate-400 uppercase tracking-widest">{filteredUsers.length} Staff Members</span>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-slate-50/50 border-b border-slate-100">
                  <th className="px-6 py-4 text-[10px] font-black uppercase tracking-widest text-slate-400">Personnel</th>
                  <th className="px-6 py-4 text-[10px] font-black uppercase tracking-widest text-slate-400">Role & Access</th>
                  <th className="px-6 py-4 text-[10px] font-black uppercase tracking-widest text-slate-400">Contact & NID</th>
                  <th className="px-6 py-4 text-[10px] font-black uppercase tracking-widest text-slate-400 text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {loading ? (
                  Array.from({ length: 5 }).map((_, i) => (
                    <tr key={i}>
                      <td className="px-6 py-4"><Skeleton className="h-10 w-48 rounded-xl" /></td>
                      <td className="px-6 py-4"><Skeleton className="h-6 w-24 rounded-full" /></td>
                      <td className="px-6 py-4"><Skeleton className="h-4 w-40" /></td>
                      <td className="px-6 py-4"><Skeleton className="h-8 w-8 ml-auto rounded-lg" /></td>
                    </tr>
                  ))
                ) : filteredUsers.length > 0 ? (
                  filteredUsers.map((user) => (
                    <tr key={user.id} className="hover:bg-slate-50/50 transition-colors group">
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-3">
                          <div className="h-12 w-12 rounded-xl bg-slate-100 flex items-center justify-center text-slate-500 font-bold group-hover:bg-primary/10 group-hover:text-primary transition-colors overflow-hidden relative">
                            {user.profileImage ? (
                              <Image src={user.profileImage} alt={user.name || ''} fill sizes="48px" className="object-cover" />
                            ) : (
                              user.name?.charAt(0) || 'U'
                            )}
                          </div>
                          <div>
                            <div className="font-bold text-slate-900">{user.name || 'Unnamed User'}</div>
                            <div className="text-[10px] text-slate-400 font-bold uppercase tracking-tighter">{user.email}</div>
                          </div>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <div className="space-y-1.5">
                          <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest ${
                            ['ADMIN', 'TEACHER'].includes(user.role) ? 'bg-indigo-50 text-indigo-600' : 'bg-slate-100 text-slate-600'
                          }`}>
                            {user.role}
                          </span>
                          <div className="flex items-center gap-1.5 text-[10px] font-black uppercase tracking-tight">
                            {user.canLogin ? (
                              <><Unlock size={10} className="text-emerald-500" /> <span className="text-emerald-600">Login Enabled</span></>
                            ) : (
                              <><Lock size={10} className="text-slate-400" /> <span className="text-slate-400">No Login Access</span></>
                            )}
                          </div>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <div className="space-y-1">
                          <div className="flex items-center gap-2 text-xs font-bold text-slate-600">
                            <CreditCard size={12} className="text-slate-400" />
                            {user.nid || 'NID Not Set'}
                          </div>
                          <div className="flex items-center gap-2 text-xs font-bold text-slate-600">
                            <Phone size={12} className="text-slate-400" />
                            {user.phone || 'No Phone'}
                          </div>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex items-center justify-end gap-2">
                          <Button 
                            variant="ghost" 
                            size="sm" 
                            onClick={() => handleOpenModal(user)}
                            className="h-9 w-9 p-0 rounded-xl hover:bg-white hover:shadow-md text-slate-400 hover:text-primary transition-all"
                          >
                            <Edit size={16} />
                          </Button>
                          <Button 
                            variant="ghost" 
                            size="sm" 
                            onClick={() => {
                              setUserToDelete(user);
                              setIsDeleteModalOpen(true);
                            }}
                            className="h-9 w-9 p-0 rounded-xl hover:bg-white hover:shadow-md text-slate-400 hover:text-red-500 transition-all"
                          >
                            <Trash2 size={16} />
                          </Button>
                        </div>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan={4} className="px-6 py-12 text-center">
                      <div className="h-16 w-16 bg-slate-50 rounded-full flex items-center justify-center text-slate-300 mx-auto mb-4 border border-dashed border-slate-200">
                        <Users size={24} />
                      </div>
                      <p className="text-slate-400 font-bold text-sm uppercase tracking-widest">No matching records found</p>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>

      {/* Onboard/Edit Modal */}
      <Modal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        title={editingUser ? 'Update Personnel File' : 'Onboard New Staff'}
        className="max-w-2xl"
      >
        <form onSubmit={handleSaveUser} className="space-y-6 pt-4">
          
          <div className="flex flex-col md:flex-row gap-8">
            {/* Left: Image Upload */}
            <div className="flex flex-col items-center gap-4">
               <div 
                onClick={() => fileInputRef.current?.click()}
                className="h-32 w-32 rounded-3xl bg-slate-50 border-2 border-dashed border-slate-200 flex flex-col items-center justify-center text-slate-400 hover:border-primary hover:text-primary cursor-pointer transition-all overflow-hidden relative group"
               >
                 {formData.profileImage ? (
                   <>
                    <Image src={formData.profileImage} alt="Preview" fill sizes="128px" className="object-cover" />
                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center text-white transition-opacity">
                      <Camera size={24} />
                    </div>
                   </>
                 ) : (
                   <>
                    <Camera size={24} className="mb-2" />
                    <span className="text-[10px] font-black uppercase tracking-widest">Photo</span>
                   </>
                 )}
               </div>
               <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleImageUpload} 
                className="hidden" 
                accept="image/*"
               />
               <div className="text-center">
                 <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Profile Picture</p>
                 <button 
                  type="button"
                  onClick={() => setFormData({...formData, profileImage: ''})}
                  className="text-[9px] font-bold text-red-400 uppercase tracking-tighter hover:text-red-600 mt-1"
                 >
                   Remove
                 </button>
               </div>
            </div>

            {/* Right: Primary Info */}
            <div className="flex-1 grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2 md:col-span-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Full Name</label>
                <Input 
                  required
                  value={formData.name}
                  onChange={(e) => setFormData({...formData, name: e.target.value})}
                  placeholder="e.g. Michael Chen"
                  className="h-11 min-h-[44px] rounded-xl border-slate-100 bg-slate-50/50 font-bold"
                />
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">System Role</label>
                <Select 
                  value={formData.role}
                  onChange={(e) => setFormData({...formData, role: e.target.value as Role})}
                  options={[
                    { value: 'TEACHER', label: 'Teacher' },
                    { value: 'ADMIN', label: 'Administrator' },
                    { value: 'LIBRARIAN', label: 'Librarian' },
                    { value: 'ACCOUNTANT', label: 'Accountant' },
                    { value: 'CLERK', label: 'Office Clerk' },
                    { value: 'SECURITY', label: 'Security Personnel' },
                    { value: 'CLEANER', label: 'Cleaning Staff' },
                    { value: 'STAFF', label: 'General Staff' }
                  ]}
                  className="h-11 min-h-[44px] rounded-xl border-slate-100 bg-slate-50/50 font-black text-[10px] uppercase tracking-widest"
                />
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">NID Number</label>
                <Input 
                  value={formData.nid}
                  onChange={(e) => setFormData({...formData, nid: e.target.value})}
                  placeholder="13-digit NID"
                  className="h-11 min-h-[44px] rounded-xl border-slate-100 bg-slate-50/50 font-bold"
                />
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-2">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 text-primary flex items-center gap-2">
                <Lock size={12} />
                Access Credentials
              </label>
              <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 space-y-4">
                <div className="flex items-center justify-between">
                  <span className="text-xs font-bold text-slate-600">Grant Login Access</span>
                  <input 
                    type="checkbox" 
                    checked={formData.canLogin}
                    onChange={(e) => setFormData({...formData, canLogin: e.target.checked})}
                    className="h-4 w-4 rounded border-slate-300 text-primary focus:ring-primary"
                  />
                </div>
                
                <div className={`space-y-3 transition-all ${formData.canLogin ? 'opacity-100' : 'opacity-40 pointer-events-none'}`}>
                  <Input 
                    required={formData.canLogin}
                    type="email"
                    value={formData.email}
                    onChange={(e) => setFormData({...formData, email: e.target.value})}
                    placeholder="Institutional Email"
                    className="h-10 min-h-[44px] rounded-xl border-slate-200 bg-white font-bold text-sm"
                  />
                  <Input 
                    required={formData.canLogin && !editingUser}
                    type="password"
                    value={formData.password}
                    onChange={(e) => setFormData({...formData, password: e.target.value})}
                    placeholder={editingUser ? "New Password (optional)" : "Secure Password"}
                    className="h-10 min-h-[44px] rounded-xl border-slate-200 bg-white font-bold text-sm"
                  />
                </div>
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 flex items-center gap-2">
                <Phone size={12} />
                Contact Particulars
              </label>
              <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 space-y-3">
                <Input 
                  value={formData.phone}
                  onChange={(e) => setFormData({...formData, phone: e.target.value})}
                  placeholder="Primary Phone Number"
                  className="h-10 min-h-[44px] rounded-xl border-slate-200 bg-white font-bold text-sm"
                />
                <textarea 
                  value={formData.address}
                  onChange={(e) => setFormData({...formData, address: e.target.value})}
                  placeholder="Residential Address"
                  className="w-full h-20 p-3 rounded-xl border border-slate-200 bg-white font-bold text-sm focus:ring-1 focus:ring-primary focus:outline-none custom-scrollbar"
                />
              </div>
            </div>
          </div>

          <div className="flex gap-4 pt-4 border-t border-slate-50">
            <Button type="button" variant="outline" onClick={() => setIsModalOpen(false)} className="flex-1 rounded-xl h-12 font-bold uppercase tracking-widest text-xs">
              Discard Changes
            </Button>
            <Button type="submit" className="flex-1 rounded-xl h-12 font-black uppercase tracking-widest text-xs shadow-lg shadow-primary/20 bg-primary hover:bg-primary/90">
              {editingUser ? 'Sync File Changes' : 'Complete Onboarding'}
            </Button>
          </div>
        </form>
      </Modal>

      {/* Delete Confirmation Modal */}
      <Modal
        isOpen={isDeleteModalOpen}
        onClose={() => setIsDeleteModalOpen(false)}
        title="Revoke All Privileges?"
      >
        <div className="pt-4 space-y-6">
          <div className="flex items-center gap-4 p-4 bg-red-50 rounded-2xl border border-red-100">
            <AlertCircle size={32} className="text-red-500 shrink-0" />
            <p className="text-sm font-medium text-red-800 leading-relaxed">
              This will permanently delete <span className="font-bold underline">{userToDelete?.name}</span> from the institutional database. This action is irreversible.
            </p>
          </div>
          <div className="flex gap-4">
            <Button variant="outline" onClick={() => setIsDeleteModalOpen(false)} className="flex-1 h-12 rounded-xl font-bold uppercase tracking-widest text-xs text-slate-500">
              Retain Record
            </Button>
            <Button onClick={handleDeleteUser} className="flex-1 h-12 bg-red-600 hover:bg-red-700 text-white rounded-xl font-black uppercase tracking-widest text-xs shadow-lg shadow-red-200">
              Confirm Deletion
            </Button>
          </div>
        </div>
      </Modal>
    </div>
  );
}

