"use client";

import React, { useState, useEffect } from 'react';
import { Card, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Select } from '@/components/ui/Select';
import { hrService } from '@/services/hr.service';
import { StaffMember, StaffAttendance } from '@/types/hr';
import toast from 'react-hot-toast';

export function AttendanceTab() {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [staff, setStaff] = useState<StaffMember[]>([]);
  const [attendance, setAttendance] = useState<Record<number, { status: string; remarks: string }>>({});
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  async function fetchData() {
    try {
      setLoading(true);
      const [staffData, attendanceData] = await Promise.all([
        hrService.getStaff(),
        hrService.getAttendance(date)
      ]);

      setStaff(staffData);

      // Map existing attendance records
      const attMap: Record<number, { status: string; remarks: string }> = {};
      
      // Default everyone to PRESENT if no records exist
      staffData.forEach(s => {
        attMap[s.id] = { status: 'PRESENT', remarks: '' };
      });

      attendanceData.forEach(record => {
        attMap[record.userId] = { 
          status: record.status, 
          remarks: record.remarks || '' 
        };
      });

      setAttendance(attMap);
    } catch (error) {
      toast.error('Failed to load attendance data');
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    fetchData();
  }, [date]);

  const handleStatusChange = (userId: number, status: string) => {
    setAttendance(prev => ({
      ...prev,
      [userId]: { ...prev[userId], status }
    }));
  };

  const handleRemarksChange = (userId: number, remarks: string) => {
    setAttendance(prev => ({
      ...prev,
      [userId]: { ...prev[userId], remarks }
    }));
  };

  const saveAttendance = async () => {
    try {
      setSaving(true);
      const records = Object.entries(attendance).map(([userId, data]) => ({
        userId: parseInt(userId, 10),
        status: data.status,
        remarks: data.remarks
      }));

      await hrService.markAttendance(date, records);
      toast.success('Attendance saved successfully');
    } catch (error) {
      toast.error('Failed to save attendance');
    } finally {
      setSaving(false);
    }
  };

  return (
    <Card>
      <CardContent className="p-6">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-6">
          <div className="flex items-center gap-4">
            <h2 className="text-lg font-bold">Daily Attendance</h2>
            <Input 
              type="date" 
              value={date} 
              onChange={(e) => setDate(e.target.value)} 
              className="w-48"
            />
          </div>
          <Button onClick={saveAttendance} disabled={loading || saving} className="bg-emerald-600 hover:bg-emerald-700">
            {saving ? 'Saving...' : 'Save Attendance'}
          </Button>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left">
            <thead className="text-xs text-muted-foreground uppercase bg-muted/50">
              <tr>
                <th className="px-4 py-3">Staff Member</th>
                <th className="px-4 py-3">Role</th>
                <th className="px-4 py-3 w-48">Status</th>
                <th className="px-4 py-3">Remarks</th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                <tr><td colSpan={4} className="text-center py-8">Loading...</td></tr>
              ) : staff.map((member) => (
                <tr key={member.id} className="border-b border-border hover:bg-muted/30">
                  <td className="px-4 py-3 font-medium">{member.name}</td>
                  <td className="px-4 py-3 text-xs text-muted-foreground">{member.role}</td>
                  <td className="px-4 py-3">
                    <Select
                      value={attendance[member.id]?.status || 'PRESENT'}
                      onChange={(e) => handleStatusChange(member.id, e.target.value)}
                      options={[
                        { value: 'PRESENT', label: 'Present' },
                        { value: 'ABSENT', label: 'Absent' },
                        { value: 'LATE', label: 'Late' },
                        { value: 'HALF_DAY', label: 'Half Day' }
                      ]}
                      className={`h-9 ${
                        attendance[member.id]?.status === 'ABSENT' ? 'bg-red-50 text-red-700 border-red-200' : ''
                      }`}
                    />
                  </td>
                  <td className="px-4 py-3">
                    <Input
                      placeholder="Add remarks..."
                      value={attendance[member.id]?.remarks || ''}
                      onChange={(e) => handleRemarksChange(member.id, e.target.value)}
                      className="h-9"
                    />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import React, { useState, useEffect } from 'react';
import { Card, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { hrService } from '@/services/hr.service';
import { LeaveRequest } from '@/types/hr';
import toast from 'react-hot-toast';
import { Check, X } from 'lucide-react';
import { useAppSelector } from '@/lib/hooks';
import { selectRole } from '@/lib/features/authSlice';
import { Modal } from '@/components/ui/Modal';
import { Input } from '@/components/ui/Input';
import { useForm, Controller } from 'react-hook-form';

export function LeaveRequestsTab() {
  const [leaves, setLeaves] = useState<LeaveRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const role = useAppSelector(selectRole);
  const [isApplyModalOpen, setIsApplyModalOpen] = useState(false);
  
  const canManage = role === 'ADMIN' || (role as string) === 'PRINCIPAL';

  const { control, handleSubmit, reset } = useForm({
    defaultValues: { startDate: '', endDate: '', reason: '' }
  });

  useEffect(() => {
    fetchLeaves();
  }, []);

  async function fetchLeaves() {
    try {
      setLoading(true);
      const data = await hrService.getLeaves();
      setLeaves(data);
    } catch (error) {
      toast.error('Failed to load leave requests');
    } finally {
      setLoading(false);
    }
  };

  const updateStatus = async (id: number, status: 'APPROVED' | 'REJECTED') => {
    try {
      await hrService.updateLeaveStatus(id, status);
      toast.success(`Leave request ${status.toLowerCase()}`);
      fetchLeaves();
    } catch (error) {
      toast.error('Failed to update status');
    }
  };

  const onApply = async (data: any) => {
    try {
      await hrService.applyLeave(data);
      toast.success('Leave request submitted successfully');
      setIsApplyModalOpen(false);
      reset();
      fetchLeaves();
    } catch (error) {
      toast.error('Failed to submit request');
    }
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'APPROVED': return <span className="bg-emerald-100 text-emerald-800 px-2 py-1 rounded-full text-xs font-medium">Approved</span>;
      case 'REJECTED': return <span className="bg-red-100 text-red-800 px-2 py-1 rounded-full text-xs font-medium">Rejected</span>;
      default: return <span className="bg-amber-100 text-amber-800 px-2 py-1 rounded-full text-xs font-medium">Pending</span>;
    }
  };

  return (
    <Card>
      <CardContent className="p-6">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-lg font-bold">Leave Requests</h2>
          <Button onClick={() => setIsApplyModalOpen(true)}>Apply for Leave</Button>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left">
            <thead className="text-xs text-muted-foreground uppercase bg-muted/50">
              <tr>
                <th className="px-4 py-3">Applicant</th>
                <th className="px-4 py-3">Dates</th>
                <th className="px-4 py-3">Reason</th>
                <th className="px-4 py-3">Status</th>
                {canManage && <th className="px-4 py-3 text-right">Actions</th>}
              </tr>
            </thead>
            <tbody>
              {loading ? (
                <tr><td colSpan={canManage ? 5 : 4} className="text-center py-8">Loading...</td></tr>
              ) : leaves.length === 0 ? (
                <tr><td colSpan={canManage ? 5 : 4} className="text-center py-8">No leave requests found</td></tr>
              ) : (
                leaves.map((leave) => (
                  <tr key={leave.id} className="border-b border-border hover:bg-muted/30">
                    <td className="px-4 py-3">
                      <div className="font-medium">{leave.user?.name}</div>
                      <div className="text-xs text-muted-foreground">{leave.user?.role}</div>
                    </td>
                    <td className="px-4 py-3 whitespace-nowrap">
                      {new Date(leave.startDate).toLocaleDateString()} <br/>
                      to {new Date(leave.endDate).toLocaleDateString()}
                    </td>
                    <td className="px-4 py-3 max-w-xs truncate" title={leave.reason}>{leave.reason}</td>
                    <td className="px-4 py-3">{getStatusBadge(leave.status)}</td>
                    {canManage && (
                      <td className="px-4 py-3 text-right">
                        {leave.status === 'PENDING' && (
                          <div className="flex justify-end gap-2">
                            <Button size="icon" variant="outline" className="h-8 w-8 text-emerald-600 border-emerald-200 hover:bg-emerald-50" onClick={() => updateStatus(leave.id, 'APPROVED')}>
                              <Check size={16} />
                            </Button>
                            <Button size="icon" variant="outline" className="h-8 w-8 text-red-600 border-red-200 hover:bg-red-50" onClick={() => updateStatus(leave.id, 'REJECTED')}>
                              <X size={16} />
                            </Button>
                          </div>
                        )}
                      </td>
                    )}
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        <Modal isOpen={isApplyModalOpen} onClose={() => setIsApplyModalOpen(false)} title="Apply for Leave">
          <form onSubmit={handleSubmit(onApply)} className="space-y-4">
            <div>
              <label className="text-sm font-medium mb-1 block">Start Date *</label>
              <Controller name="startDate" control={control} rules={{required:true}} render={({field}) => <Input type="date" {...field} />} />
            </div>
            <div>
              <label className="text-sm font-medium mb-1 block">End Date *</label>
              <Controller name="endDate" control={control} rules={{required:true}} render={({field}) => <Input type="date" {...field} />} />
            </div>
            <div>
              <label className="text-sm font-medium mb-1 block">Reason *</label>
              <Controller name="reason" control={control} rules={{required:true}} render={({field}) => <Input {...field} placeholder="Brief explanation..." />} />
            </div>
            <div className="flex justify-end gap-2 pt-4">
              <Button type="button" variant="outline" onClick={() => setIsApplyModalOpen(false)}>Cancel</Button>
              <Button type="submit">Submit Request</Button>
            </div>
          </form>
        </Modal>
      </CardContent>
    </Card>
  );
}

"use client";

import React, { useState, useEffect } from 'react';
import { Card, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Select } from '@/components/ui/Select';
import { hrService } from '@/services/hr.service';
import { PayrollRecord } from '@/types/hr';
import toast from 'react-hot-toast';
import { Printer, Play } from 'lucide-react';

export function PayrollTab() {
  const currentMonth = new Date().getMonth() + 1;
  const currentYear = new Date().getFullYear();
  
  const [month, setMonth] = useState(currentMonth.toString());
  const [year, setYear] = useState(currentYear.toString());
  const [records, setRecords] = useState<PayrollRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [generating, setGenerating] = useState(false);

  useEffect(() => {
    fetchRecords();
  }, [month, year]);

  async function fetchRecords() {
    try {
      setLoading(true);
      const data = await hrService.getPayrollRecords(parseInt(month), parseInt(year));
      setRecords(data);
    } catch (error) {
      toast.error('Failed to load payroll records');
    } finally {
      setLoading(false);
    }
  };

  const handleGenerate = async () => {
    try {
      setGenerating(true);
      await hrService.generatePayroll(parseInt(month), parseInt(year));
      toast.success('Payroll generated successfully');
      fetchRecords();
    } catch (error) {
      toast.error('Failed to generate payroll');
    } finally {
      setGenerating(false);
    }
  };

  const handlePay = async (id: string) => {
    try {
      await hrService.paySalary(id, 'BANK_TRANSFER');
      toast.success('Salary marked as paid');
      fetchRecords();
    } catch (error) {
      toast.error('Failed to process payment');
    }
  };

  const handlePrintSlip = async (record: PayrollRecord) => {
    try {
      toast.loading(`Generating Salary Slip for ${record.user?.name}...`, { id: 'slip-gen' });
      await hrService.downloadSalarySlip(record.id);
      toast.success('Salary slip downloaded successfully', { id: 'slip-gen' });
    } catch (error) {
      toast.error('Failed to generate salary slip', { id: 'slip-gen' });
    }
  };

  return (
    <Card>
      <CardContent className="p-6">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-6">
          <div className="flex items-center gap-4">
            <Select 
              value={month} 
              onChange={(e) => setMonth(e.target.value)} 
              options={Array.from({length: 12}, (_, i) => ({ value: `${i+1}`, label: new Date(2000, i, 1).toLocaleString('default', { month: 'long' }) }))}
              className="w-32"
            />
            <Select 
              value={year} 
              onChange={(e) => setYear(e.target.value)} 
              options={[currentYear-1, currentYear, currentYear+1].map(y => ({ value: `${y}`, label: `${y}` }))}
              className="w-24"
            />
          </div>
          <Button onClick={handleGenerate} disabled={generating || loading} className="gap-2 bg-blue-600 hover:bg-blue-700">
            <Play size={16} /> {generating ? 'Generating...' : 'Run Payroll Engine'}
          </Button>
        </div>

        <div className="bg-blue-50 border border-blue-100 p-4 rounded-lg mb-6 text-sm text-blue-800">
          <strong>Note:</strong> Running the Payroll Engine will automatically calculate deductions for any unpaid absent days during the selected month.
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left">
            <thead className="text-xs text-muted-foreground uppercase bg-muted/50">
              <tr>
                <th className="px-4 py-3">Staff Member</th>
                <th className="px-4 py-3 text-right">Base Salary</th>
                <th className="px-4 py-3 text-right text-green-600">Allowances</th>
                <th className="px-4 py-3 text-right text-red-600">Deductions</th>
                <th className="px-4 py-3 text-right font-bold">Net Pay</th>
                <th className="px-4 py-3 text-center">Status</th>
                <th className="px-4 py-3 text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                <tr><td colSpan={7} className="text-center py-8">Loading...</td></tr>
              ) : records.length === 0 ? (
                <tr><td colSpan={7} className="text-center py-8">No records found. Run the engine to generate payroll.</td></tr>
              ) : (
                records.map((record) => (
                  <tr key={record.id} className="border-b border-border hover:bg-muted/30">
                    <td className="px-4 py-3">
                      <div className="font-medium">{record.user?.name}</div>
                      <div className="text-xs text-muted-foreground">{record.user?.role}</div>
                    </td>
                    <td className="px-4 py-3 text-right font-mono">${record.baseSalary.toFixed(2)}</td>
                    <td className="px-4 py-3 text-right font-mono text-green-600">+${record.allowances.toFixed(2)}</td>
                    <td className="px-4 py-3 text-right font-mono text-red-600">-${record.deductions.toFixed(2)}</td>
                    <td className="px-4 py-3 text-right font-mono font-bold text-lg">${record.netPay.toFixed(2)}</td>
                    <td className="px-4 py-3 text-center">
                      <span className={`px-2 py-1 rounded-full text-xs font-medium ${record.status === 'PAID' ? 'bg-emerald-100 text-emerald-800' : 'bg-amber-100 text-amber-800'}`}>
                        {record.status}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-right">
                      <div className="flex justify-end gap-2">
                        {record.status === 'PENDING' && (
                          <Button size="sm" onClick={() => handlePay(record.id)} className="bg-emerald-600 hover:bg-emerald-700 h-8">
                            Mark Paid
                          </Button>
                        )}
                        <Button size="sm" variant="outline" onClick={() => handlePrintSlip(record)} className="h-8 gap-1">
                          <Printer size={14} /> Slip
                        </Button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import React, { useState, useEffect } from 'react';
import { Card, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Modal } from '@/components/ui/Modal';
import { hrService } from '@/services/hr.service';
import { StaffMember } from '@/types/hr';
import toast from 'react-hot-toast';
import { Edit2 } from 'lucide-react';
import { useForm, Controller } from 'react-hook-form';

export function StaffSalaryTab() {
  const [staff, setStaff] = useState<StaffMember[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedStaff, setSelectedStaff] = useState<StaffMember | null>(null);

  const { control, handleSubmit, reset } = useForm({
    defaultValues: {
      baseSalary: 0,
      allowances: 0,
      deductions: 0
    }
  });

  const fetchStaff = async () => {
    try {
      setLoading(true);
      const data = await hrService.getStaff();
      setStaff(data);
    } catch (error) {
      toast.error('Failed to load staff records');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    setTimeout(() => fetchStaff(), 0);
  }, []);

  const openEditModal = (member: StaffMember) => {
    setSelectedStaff(member);
    reset({
      baseSalary: member.salary?.baseSalary || 0,
      allowances: member.salary?.allowances || 0,
      deductions: member.salary?.deductions || 0
    });
    setIsModalOpen(true);
  };

  const onSubmit = async (data: any) => {
    if (!selectedStaff) return;
    try {
      await hrService.updateSalary(selectedStaff.id, data);
      toast.success('Salary updated successfully');
      setIsModalOpen(false);
      fetchStaff();
    } catch (error) {
      toast.error('Failed to update salary');
    }
  };

  return (
    <Card>
      <CardContent className="p-6">
        <h2 className="text-lg font-bold mb-4">Staff & Salary Configuration</h2>
        
        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left">
            <thead className="text-xs text-muted-foreground uppercase bg-muted/50">
              <tr>
                <th className="px-4 py-3">Staff Name</th>
                <th className="px-4 py-3">Role</th>
                <th className="px-4 py-3">Base Salary</th>
                <th className="px-4 py-3">Allowances</th>
                <th className="px-4 py-3">Deductions</th>
                <th className="px-4 py-3 text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                <tr><td colSpan={6} className="text-center py-8">Loading...</td></tr>
              ) : staff.length === 0 ? (
                <tr><td colSpan={6} className="text-center py-8">No staff found</td></tr>
              ) : (
                staff.map((member) => (
                  <tr key={member.id} className="border-b border-border hover:bg-muted/30">
                    <td className="px-4 py-3">
                      <div className="font-medium text-foreground">{member.name}</div>
                      <div className="text-xs text-muted-foreground">{member.email}</div>
                    </td>
                    <td className="px-4 py-3">{member.role}</td>
                    <td className="px-4 py-3 font-mono">${member.salary?.baseSalary.toFixed(2) || '0.00'}</td>
                    <td className="px-4 py-3 font-mono text-green-600">${member.salary?.allowances.toFixed(2) || '0.00'}</td>
                    <td className="px-4 py-3 font-mono text-red-600">${member.salary?.deductions.toFixed(2) || '0.00'}</td>
                    <td className="px-4 py-3 text-right">
                      <Button variant="ghost" size="sm" onClick={() => openEditModal(member)}>
                        <Edit2 size={16} />
                      </Button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={`Configure Salary: ${selectedStaff?.name}`}>
          <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
            <div>
              <label className="text-sm font-medium mb-1 block">Base Salary ($)</label>
              <Controller name="baseSalary" control={control} render={({field}) => <Input type="number" {...field} />} />
            </div>
            <div>
              <label className="text-sm font-medium mb-1 block">Monthly Allowances ($)</label>
              <Controller name="allowances" control={control} render={({field}) => <Input type="number" {...field} />} />
            </div>
            <div>
              <label className="text-sm font-medium mb-1 block">Standard Deductions ($)</label>
              <Controller name="deductions" control={control} render={({field}) => <Input type="number" {...field} />} />
            </div>
            <div className="flex justify-end gap-2 pt-4">
              <Button type="button" variant="outline" onClick={() => setIsModalOpen(false)}>Cancel</Button>
              <Button type="submit">Save Settings</Button>
            </div>
          </form>
        </Modal>
      </CardContent>
    </Card>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { Sidebar } from './Sidebar';
import { TopNavbar } from './TopNavbar';
import { useAppDispatch, useAppSelector } from '@/lib/hooks';
import { fetchConfig, selectConfigInitialized } from '@/lib/features/configSlice';
import { fetchLicenseStatus } from '@/lib/features/licenseSlice';
import { fetchSchoolProfile, selectSchoolProfile, fetchSystemSettings, selectSystemSettings } from '@/lib/features/settingsSlice';
import { usePathname } from 'next/navigation';
import { selectRole } from '@/lib/features/authSlice';
import { navItems } from '@/lib/navigation';
import { AccessDeniedModal } from '../ui/AccessDeniedModal';
import { LicenseLockout } from './LicenseLockout';
import Image from 'next/image';

export function DashboardLayout({ children }: { children: React.ReactNode }) {
  const [collapsed, setCollapsed] = useState(false);
  const [isMobileOpen, setIsMobileOpen] = useState(false);
  const dispatch = useAppDispatch();
  const configInitialized = useAppSelector(selectConfigInitialized);
  const schoolProfile = useAppSelector(selectSchoolProfile);
  const systemSettings = useAppSelector(selectSystemSettings);
  const pathname = usePathname();
  const role = useAppSelector(selectRole);
  
  const licenseStatus = useAppSelector((state) => state.license.status);

  useEffect(() => {
    if (!configInitialized) {
      dispatch(fetchConfig());
    }
  }, [dispatch, configInitialized]);

  // Fetch license, school profile, and system settings on mount
  useEffect(() => {
    dispatch(fetchLicenseStatus());
    dispatch(fetchSchoolProfile());
    dispatch(fetchSystemSettings());
  }, [dispatch]);

  // RBAC check (derived from state/props)
  const currentNavItem = navItems.find(item => 
    pathname === item.href || pathname.startsWith(item.href + '/')
  );

  const isAccessDenied = !!(
    currentNavItem && 
    currentNavItem.roles && 
    role && 
    !currentNavItem.roles.includes(role.toUpperCase())
  );

  // Apply accent color to document root
  useEffect(() => {
    const accentColor = systemSettings?.accentColor || '#2563eb';
    document.documentElement.style.setProperty('--primary', accentColor);
    
    // Also update primary-foreground for buttons
    document.documentElement.style.setProperty('--primary-foreground', '#ffffff');
  }, [systemSettings?.accentColor]);

  // Close mobile sidebar on navigation
  useEffect(() => {
    setTimeout(() => setIsMobileOpen(false), 0);
  }, [pathname]);

  if (licenseStatus === 'EXPIRED' || licenseStatus === 'MISSING') {
    return <LicenseLockout status={licenseStatus} />;
  }

  return (
    <div className="flex h-screen overflow-hidden bg-background text-foreground font-sans print:h-auto print:overflow-visible">
      {/* Sidebar Component */}
      <div className="print:hidden h-full">
        <Sidebar 
          collapsed={collapsed} 
          setCollapsed={setCollapsed} 
          isMobileOpen={isMobileOpen}
          setIsMobileOpen={setIsMobileOpen}
        />
      </div>

      <div className="flex flex-1 flex-col overflow-hidden relative print:overflow-visible print:block">
        <div className="print:hidden">
          <TopNavbar onMenuClick={() => setIsMobileOpen(true)} />
        </div>
        
        <main className="flex-1 overflow-y-auto p-4 lg:p-8 custom-scrollbar print:p-0 print:overflow-visible print:block">
          <div className="mx-auto max-w-7xl print:max-w-none">
            {children}
          </div>
        </main>

        {/* Global Branding Footer (Always Visible) */}
        <footer className="h-14 px-6 border-t border-border bg-card flex flex-row justify-between items-center text-muted-foreground print:hidden shrink-0 z-10">
          <div className="flex items-center gap-3 opacity-90 hover:opacity-100 transition-opacity">
             <span className="text-[10px] font-bold uppercase tracking-widest">Powered by</span>
             <div className="flex items-center gap-2 grayscale contrast-125">
               <Image src="/edutrackerLogo.png" alt="EduTracker AI" width={22} height={22} priority style={{ width: '22px', height: '22px' }} className="object-contain" />
               <span className="text-sm font-black tracking-tight text-foreground/80">EduTracker AI</span>
             </div>
          </div>
          <div className="flex items-center gap-5">
             <span className="hidden sm:inline text-[10px] font-medium tracking-wide uppercase opacity-60">© 2026 All Rights Reserved</span>
             <div className="px-3 py-1 rounded-full bg-primary/10 border border-primary/20 text-primary text-xs font-black tracking-tighter uppercase shadow-sm">
                v1.0.0
             </div>
          </div>
        </footer>

        <AccessDeniedModal 
          isOpen={isAccessDenied} 
          onClose={() => {}} 
        />
      </div>
    </div>
  );
}

'use client';

import React, { useEffect, useState, useRef } from 'react';
import { 
  Bell, 
  CheckCheck, 
  Trash2, 
  Info, 
  CheckCircle2, 
  AlertTriangle, 
  XCircle,
  ExternalLink,
  Clock,
  X
} from 'lucide-react';
import { useAppSelector, useAppDispatch } from '@/lib/hooks';
import { 
  fetchNotifications, 
  markAsReadThunk, 
  markAllAsReadThunk, 
  deleteNotificationThunk,
  selectAllNotifications,
  selectUnreadCount,
  selectNotificationsLoading
} from '@/lib/features/notificationsSlice';
import { Button } from '@/components/ui/Button';
import Link from 'next/link';
import { formatDistanceToNow } from 'date-fns';

export function NotificationCenter({ isOpen, onClose }: { isOpen: boolean, onClose: () => void }) {
  const dispatch = useAppDispatch();
  const notifications = useAppSelector(selectAllNotifications);
  const unreadCount = useAppSelector(selectUnreadCount);
  const loading = useAppSelector(selectNotificationsLoading);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (isOpen) {
      dispatch(fetchNotifications());
    }
  }, [isOpen, dispatch]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        onClose();
      }
    };

    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [isOpen, onClose]);

  const handleMarkAsRead = (id: number) => {
    dispatch(markAsReadThunk(id));
  };

  const handleMarkAllRead = () => {
    dispatch(markAllAsReadThunk());
  };

  const handleDelete = (id: number) => {
    dispatch(deleteNotificationThunk(id));
  };

  const getTypeIcon = (type: string) => {
    switch (type) {
      case 'SUCCESS': return <CheckCircle2 size={16} className="text-emerald-500" />;
      case 'WARNING': return <AlertTriangle size={16} className="text-amber-500" />;
      case 'ERROR': return <XCircle size={16} className="text-red-500" />;
      default: return <Info size={16} className="text-blue-500" />;
    }
  };

  if (!isOpen) return null;

  return (
    <div 
      ref={containerRef}
      className="absolute top-20 right-4 w-full max-w-[400px] bg-white rounded-3xl shadow-2xl shadow-slate-200 border border-slate-100 z-50 animate-in slide-in-from-top-2 duration-300 overflow-hidden flex flex-col max-h-[600px]"
    >
      <div className="p-6 border-b border-slate-50 flex items-center justify-between bg-white sticky top-0 z-10">
        <div className="flex items-center gap-3">
          <div className="h-10 w-10 bg-primary/10 rounded-xl flex items-center justify-center text-primary">
            <Bell size={20} />
          </div>
          <div>
            <h3 className="font-black text-slate-900 tracking-tight">Notifications</h3>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
              {unreadCount} Unread Alerts
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {unreadCount > 0 && (
            <Button 
              variant="ghost" 
              size="sm" 
              onClick={handleMarkAllRead}
              className="h-8 px-2 rounded-lg text-[10px] font-black uppercase tracking-widest text-primary hover:bg-primary/5"
            >
              <CheckCheck size={14} className="mr-1" />
              Mark all read
            </Button>
          )}
          <button 
            onClick={onClose}
            className="h-8 w-8 flex items-center justify-center rounded-lg hover:bg-slate-50 text-slate-400 transition-colors"
          >
            <X size={18} />
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
        {loading && notifications.length === 0 ? (
          <div className="p-8 text-center space-y-3">
            <div className="h-8 w-8 border-2 border-primary/30 border-t-primary rounded-full animate-spin mx-auto"></div>
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Syncing alerts...</p>
          </div>
        ) : notifications.length > 0 ? (
          <div className="space-y-1">
            {notifications.map((n) => (
              <div 
                key={n.id}
                className={`p-4 rounded-2xl transition-all group relative border ${
                  n.isRead ? 'bg-white border-transparent' : 'bg-slate-50 border-slate-100'
                }`}
              >
                <div className="flex gap-4">
                  <div className="mt-1 shrink-0">
                    {getTypeIcon(n.type)}
                  </div>
                  <div className="flex-1 space-y-1">
                    <div className="flex items-start justify-between gap-2">
                      <h4 className={`text-sm font-bold tracking-tight leading-snug ${n.isRead ? 'text-slate-600' : 'text-slate-900'}`}>
                        {n.title}
                      </h4>
                      <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        {!n.isRead && (
                          <button 
                            onClick={() => handleMarkAsRead(n.id)}
                            className="p-1.5 hover:bg-primary/10 text-primary rounded-lg transition-colors"
                            title="Mark as read"
                          >
                            <CheckCheck size={14} />
                          </button>
                        )}
                        <button 
                          onClick={() => handleDelete(n.id)}
                          className="p-1.5 hover:bg-red-50 text-red-500 rounded-lg transition-colors"
                          title="Delete"
                        >
                          <Trash2 size={14} />
                        </button>
                      </div>
                    </div>
                    <p className={`text-xs leading-relaxed ${n.isRead ? 'text-slate-400 font-medium' : 'text-slate-600 font-semibold'}`}>
                      {n.message}
                    </p>
                    <div className="flex items-center justify-between pt-2">
                      <div className="flex items-center gap-1.5 text-[10px] font-bold text-slate-400 uppercase tracking-tighter">
                        <Clock size={10} />
                        {formatDistanceToNow(new Date(n.createdAt), { addSuffix: true })}
                      </div>
                      {n.link && (
                        <Link 
                          href={n.link} 
                          onClick={onClose}
                          className="flex items-center gap-1 text-[10px] font-black text-primary uppercase tracking-widest hover:underline"
                        >
                          View Details
                          <ExternalLink size={10} />
                        </Link>
                      )}
                    </div>
                  </div>
                </div>
                {!n.isRead && (
                  <div className="absolute top-4 right-4 h-2 w-2 bg-primary rounded-full group-hover:hidden"></div>
                )}
              </div>
            ))}
          </div>
        ) : (
          <div className="p-12 text-center">
            <div className="h-16 w-16 bg-slate-50 rounded-full flex items-center justify-center text-slate-300 mx-auto mb-4 border border-dashed border-slate-200">
              <Bell size={24} />
            </div>
            <p className="text-slate-400 font-bold text-sm uppercase tracking-widest">No notifications yet</p>
          </div>
        )}
      </div>
      
      {notifications.length > 0 && (
        <div className="p-4 bg-slate-50/50 border-t border-slate-50 text-center">
          <p className="text-[9px] font-black text-slate-400 uppercase tracking-[0.2em]">Institutional Console Alert System</p>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { Modal } from '@/components/ui/Modal';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Select } from '@/components/ui/Select';
import { Sparkles, Loader2, Check } from 'lucide-react';
import api from '@/lib/api';
import toast from 'react-hot-toast';

interface AIQuestionGeneratorModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSelect: (questions: any[]) => void;
  defaultClass?: string;
  defaultSubject?: string;
}

const DIFFICULTY_LEVELS = [
  { value: 'Easy', label: 'Easy' },
  { value: 'Medium', label: 'Medium' },
  { value: 'Hard', label: 'Hard' },
];

export function AIQuestionGeneratorModal({ isOpen, onClose, onSelect, defaultClass, defaultSubject }: AIQuestionGeneratorModalProps) {
  const [topic, setTopic] = useState('');
  const [difficulty, setDifficulty] = useState('Medium');
  const [count, setCount] = useState(3);
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedQuestions, setGeneratedQuestions] = useState<any[]>([]);
  const [selectedIndices, setSelectedIndices] = useState<Set<number>>(new Set());

  const handleGenerate = async () => {
    if (!defaultClass || !defaultSubject || !topic) {
      toast.error('Please ensure Class, Subject, and Topic are provided.');
      return;
    }

    setIsGenerating(true);
    setGeneratedQuestions([]);
    setSelectedIndices(new Set());

    try {
      const response = await api.post('/ai-insights/generate-questions', {
        className: defaultClass,
        subject: defaultSubject,
        topic,
        difficulty,
        count
      });
      
      setGeneratedQuestions(response.data.data);
      toast.success('Questions generated successfully!');
    } catch (error) {
      console.error('Error generating questions:', error);
      toast.error('Failed to generate questions using AI.');
    } finally {
      setIsGenerating(false);
    }
  };

  const toggleSelect = (index: number) => {
    const newSet = new Set(selectedIndices);
    if (newSet.has(index)) {
      newSet.delete(index);
    } else {
      newSet.add(index);
    }
    setSelectedIndices(newSet);
  };

  const handleImport = () => {
    const selectedQuestions = generatedQuestions.filter((_, idx) => selectedIndices.has(idx));
    onSelect(selectedQuestions);
    setTopic('');
    setGeneratedQuestions([]);
    setSelectedIndices(new Set());
    onClose();
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="AI Question Generator" size="xl">
      <div className="space-y-6 pt-4">
        {/* Input Form */}
        <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 space-y-4">
          <div className="flex items-center gap-2 mb-2 text-indigo-600 font-medium">
            <Sparkles size={18} />
            <h3>Generate Questions with AI</h3>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="sm:col-span-2">
              <Input 
                label="Topic / Keyword" 
                placeholder="e.g. Photosynthesis, Newton's Laws, World War II" 
                value={topic}
                onChange={(e) => setTopic(e.target.value)}
              />
            </div>
            <Select 
              label="Difficulty Level" 
              options={DIFFICULTY_LEVELS}
              value={difficulty}
              onChange={(e) => setDifficulty(e.target.value)}
            />
            <Input 
              label="Number of Questions" 
              type="number"
              min={1}
              max={10}
              value={count}
              onChange={(e) => setCount(parseInt(e.target.value) || 3)}
            />
          </div>
          <div className="flex justify-end pt-2">
            <Button 
              onClick={handleGenerate} 
              disabled={isGenerating || !topic}
              className="bg-indigo-600 hover:bg-indigo-700 text-white shadow-md shadow-indigo-200 w-full sm:w-auto"
            >
              {isGenerating ? (
                <Loader2 size={16} className="mr-2 animate-spin" />
              ) : (
                <Sparkles size={16} className="mr-2" />
              )}
              {isGenerating ? 'Generating...' : 'Generate Questions'}
            </Button>
          </div>
        </div>

        {/* Results */}
        {generatedQuestions.length > 0 && (
          <div className="space-y-3">
            <div className="flex justify-between items-center">
              <h4 className="font-bold text-slate-800">Generated Suggestions</h4>
              <span className="text-xs font-semibold text-slate-500 bg-slate-100 px-2 py-1 rounded">
                Select questions to import
              </span>
            </div>
            <div className="max-h-[350px] overflow-y-auto space-y-3 pr-2 custom-scrollbar">
              {generatedQuestions.map((q, idx) => {
                const isSelected = selectedIndices.has(idx);
                return (
                  <div 
                    key={idx} 
                    className={`p-4 border rounded-xl cursor-pointer transition-all ${
                      isSelected 
                        ? 'border-indigo-500 bg-indigo-50/50 shadow-sm' 
                        : 'border-slate-200 hover:border-indigo-300 hover:bg-slate-50'
                    }`}
                    onClick={() => toggleSelect(idx)}
                  >
                    <div className="flex gap-4">
                      <div className={`mt-1 w-5 h-5 rounded border flex items-center justify-center shrink-0 transition-colors ${
                        isSelected ? 'bg-indigo-600 border-indigo-600 text-white' : 'border-slate-300 bg-white'
                      }`}>
                        {isSelected && <Check size={14} />}
                      </div>
                      <div className="flex-1 space-y-2">
                        <div className="flex justify-between items-start gap-4">
                          <p className="font-medium text-slate-900 leading-relaxed text-sm">
                            {q.questionText}
                          </p>
                          <span className="shrink-0 text-xs font-bold text-slate-500 whitespace-nowrap">
                            [{q.marks} Marks]
                          </span>
                        </div>
                        
                        {q.questionType === 'MULTIPLE_CHOICE' && q.options && (
                          <div className="grid grid-cols-2 gap-2 mt-2">
                            {q.options.map((opt: string, optIdx: number) => (
                              <div key={optIdx} className="text-xs flex gap-2 items-center bg-white border border-slate-100 p-2 rounded">
                                <span className="font-bold text-slate-400">{String.fromCharCode(97 + optIdx)})</span>
                                <span className={opt === q.correctAnswer ? 'text-emerald-600 font-medium' : 'text-slate-600'}>
                                  {opt}
                                </span>
                              </div>
                            ))}
                          </div>
                        )}
                        
                        <div className="flex gap-2">
                          <span className="text-[10px] font-bold tracking-wider uppercase bg-slate-200 text-slate-600 px-2 py-0.5 rounded">
                            {q.questionType.replace('_', ' ')}
                          </span>
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        <div className="flex justify-between items-center pt-4 border-t border-slate-100">
          <span className="text-sm text-slate-600 font-medium">
            {selectedIndices.size} selected
          </span>
          <div className="flex gap-3">
            <Button variant="outline" onClick={onClose}>Cancel</Button>
            <Button 
              onClick={handleImport} 
              disabled={selectedIndices.size === 0}
              className="bg-indigo-600 hover:bg-indigo-700 text-white"
            >
              <Check size={16} className="mr-2" />
              Add to Paper
            </Button>
          </div>
        </div>
      </div>
    </Modal>
  );
}

import React, { useState } from 'react';
import { useFieldArray, Control, UseFormRegister, FieldErrors, useWatch } from 'react-hook-form';
import { Button } from '@/components/ui/Button';
import { Plus, BookOpen, Sparkles } from 'lucide-react';
import { QuestionPaperForm } from '@/lib/validations';
import { QuestionItem } from './QuestionItem';
import { QuestionBankModal } from './QuestionBankModal';
import { AIQuestionGeneratorModal } from './AIQuestionGeneratorModal';
import { BankQuestion } from '@/types/question-bank';
import {
  DndContext,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragEndEvent
} from '@dnd-kit/core';
import {
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
} from '@dnd-kit/sortable';

interface QuestionBuilderProps {
  control: Control<QuestionPaperForm>;
  register: UseFormRegister<QuestionPaperForm>;
  errors: FieldErrors<QuestionPaperForm>;
}

export function QuestionBuilder({ control, register, errors }: QuestionBuilderProps) {
  const { fields, append, remove, move } = useFieldArray({
    control,
    name: 'questions',
  });

  const [isBankModalOpen, setIsBankModalOpen] = useState(false);
  const [isAIModalOpen, setIsAIModalOpen] = useState(false);
  const currentSubject = useWatch({ control, name: 'subject' });
  const currentClass = useWatch({ control, name: 'className' });

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 5,
      },
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  const handleAddQuestion = () => {
    append({
      questionText: '',
      questionType: 'SHORT_ANSWER',
      marks: 1,
      options: ['', '', '', ''],
      correctAnswer: '',
      instructions: '',
    });
  };

  const handleImportQuestions = (bankQuestions: any[]) => {
    const formattedQuestions = bankQuestions.map(bq => ({
      questionText: bq.questionText,
      questionType: bq.questionType as any,
      marks: bq.marks,
      options: bq.options && bq.options.length > 0 ? bq.options : ['', '', '', ''],
      correctAnswer: bq.correctAnswer || '',
      instructions: '',
    }));
    
    append(formattedQuestions);
  };

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;

    if (over && active.id !== over.id) {
      const oldIndex = fields.findIndex((item) => item.id === active.id);
      const newIndex = fields.findIndex((item) => item.id === over.id);
      move(oldIndex, newIndex);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between border-b border-slate-100 pb-4 gap-4">
        <h3 className="text-lg font-bold text-slate-900">Questions</h3>
        <div className="flex gap-2 flex-wrap">
          <Button 
            type="button" 
            onClick={() => setIsAIModalOpen(true)}
            variant="outline" 
            size="sm"
            className="border-purple-200 text-purple-600 hover:bg-purple-50"
          >
            <Sparkles size={16} className="mr-2" />
            AI Suggest
          </Button>
          <Button 
            type="button" 
            onClick={() => setIsBankModalOpen(true)}
            variant="outline" 
            size="sm"
            className="border-indigo-200 text-indigo-600 hover:bg-indigo-50"
          >
            <BookOpen size={16} className="mr-2" />
            Import from Bank
          </Button>
          <Button 
            type="button" 
            onClick={handleAddQuestion}
            variant="outline" 
            size="sm"
            className="border-primary/20 text-primary hover:bg-primary/5"
          >
            <Plus size={16} className="mr-2" />
            Add Blank
          </Button>
        </div>
      </div>

      <div className="space-y-6">
        <DndContext
          sensors={sensors}
          collisionDetection={closestCenter}
          onDragEnd={handleDragEnd}
        >
          <SortableContext
            items={fields.map((f) => f.id)}
            strategy={verticalListSortingStrategy}
          >
            {fields.map((field, index) => (
              <QuestionItem
                key={field.id}
                id={field.id}
                index={index}
                register={register}
                control={control}
                errors={errors}
                onRemove={() => remove(index)}
              />
            ))}
          </SortableContext>
        </DndContext>

        {fields.length === 0 && (
          <div className="text-center py-12 border-2 border-dashed border-slate-200 rounded-xl bg-slate-50/50">
            <div className="inline-flex items-center justify-center w-12 h-12 rounded-full bg-primary/10 text-primary mb-4">
              <Plus size={24} />
            </div>
            <h4 className="text-slate-900 font-bold mb-1">No Questions Added</h4>
            <p className="text-slate-500 text-sm mb-4">Start building your question paper by adding the first question.</p>
            <div className="flex justify-center gap-3 flex-wrap">
              <Button 
                type="button" 
                onClick={() => setIsAIModalOpen(true)}
                variant="outline"
                className="border-purple-200 text-purple-600 hover:bg-purple-50"
              >
                <Sparkles size={16} className="mr-2" />
                AI Suggest
              </Button>
              <Button 
                type="button" 
                onClick={() => setIsBankModalOpen(true)}
                variant="outline"
              >
                <BookOpen size={16} className="mr-2" />
                Import from Bank
              </Button>
              <Button 
                type="button" 
                onClick={handleAddQuestion}
                className="shadow-sm"
              >
                Add Blank Question
              </Button>
            </div>
          </div>
        )}
      </div>

      <QuestionBankModal 
        isOpen={isBankModalOpen} 
        onClose={() => setIsBankModalOpen(false)} 
        onSelect={handleImportQuestions}
        subject={currentSubject}
        className={currentClass}
      />
      <AIQuestionGeneratorModal
        isOpen={isAIModalOpen}
        onClose={() => setIsAIModalOpen(false)}
        onSelect={handleImportQuestions}
        defaultClass={currentClass}
        defaultSubject={currentSubject}
      />
    </div>
  );
}

'use client';

import React from 'react';
import { QuestionPaperForm } from '@/lib/validations';
import { SchoolProfile } from '@/types/models';
import { Card, CardContent } from '@/components/ui/Card';
import { Skeleton } from '@/components/ui/Skeleton';
import Image from 'next/image';

interface QuestionPaperPreviewProps {
  data: QuestionPaperForm;
  schoolProfile: SchoolProfile | null;
  loading?: boolean;
}

export function QuestionPaperPreview({ data, schoolProfile, loading = false }: QuestionPaperPreviewProps) {
  if (loading) {
    return (
      <div className="w-full h-full overflow-y-auto bg-slate-100 p-4 lg:p-8 flex justify-center animate-pulse">
        <Card className="w-full max-w-[210mm] min-h-[297mm] bg-white shadow-xl mx-auto p-12 space-y-12">
          <div className="flex flex-col items-center space-y-4">
            <Skeleton className="h-20 w-20 rounded-full" />
            <Skeleton className="h-8 w-3/4" />
            <Skeleton className="h-4 w-1/2" />
            <Skeleton className="h-6 w-1/3 pt-4" />
          </div>
          <div className="grid grid-cols-2 gap-4 border-y border-slate-200 py-6">
            <Skeleton className="h-6 w-full" />
            <Skeleton className="h-6 w-full" />
            <Skeleton className="h-6 w-full" />
            <Skeleton className="h-6 w-full" />
          </div>
          <div className="space-y-8 pt-6">
            {Array(4).fill(0).map((_, i) => (
