          </div>

          {/* Instructions */}
          {instructions && (
            <div className="space-y-2">
              <h3 className="text-sm font-bold uppercase underline">General Instructions:</h3>
              <div className="text-xs text-slate-700 leading-relaxed whitespace-pre-wrap pl-4">
                {instructions}
              </div>
            </div>
          )}

          {/* Questions */}
          <div className="space-y-6 pt-4 print:space-y-5">
            {questions && questions.length > 0 ? (
              questions.map((q, index) => (
                <div key={index} className="space-y-3 relative group break-inside-avoid">
                  <div className="flex justify-between items-start gap-4">
                    <div className="flex gap-3 flex-1">
                      <span className="font-bold text-slate-900 min-w-[24px]">Q{index + 1}.</span>
                      <div className="flex-1 space-y-3">
                        <p className="text-[15px] text-slate-900 font-medium leading-relaxed">
                          {q.questionText || 'Question text goes here...'}
                        </p>
                        
                        {/* Options for MCQs */}
                        {q.questionType === 'MULTIPLE_CHOICE' && q.options && (
                          <div className="grid grid-cols-2 gap-4 pl-2">
                            {q.options.map((opt, optIdx) => (
                              <div key={optIdx} className="flex gap-2 text-sm text-slate-700">
                                <span className="font-semibold">{String.fromCharCode(97 + optIdx)})</span>
                                <span>{opt || `Option ${optIdx + 1}`}</span>
                              </div>
                            ))}
                          </div>
                        )}

                        {/* Space for True/False */}
                        {q.questionType === 'TRUE_FALSE' && (
                          <div className="flex gap-8 pl-2">
                            <div className="flex gap-2 text-sm text-slate-700">
                              <span className="w-4 h-4 rounded-full border border-slate-400 mt-0.5" />
                              <span>True</span>
                            </div>
                            <div className="flex gap-2 text-sm text-slate-700">
                              <span className="w-4 h-4 rounded-full border border-slate-400 mt-0.5" />
                              <span>False</span>
                            </div>
                          </div>
                        )}
                      </div>
                    </div>
                    <div className="font-bold text-slate-900 shrink-0 border-b border-slate-400 pb-0.5 px-2">
                      [{q.marks || 0}]
                    </div>
                  </div>
                </div>
              ))
            ) : (
              <div className="text-center py-20 border-2 border-dashed border-slate-100 rounded-xl">
                <p className="text-slate-400 italic">No questions added yet. They will appear here in real-time.</p>
              </div>
            )}
          </div>

          {/* Footer for the paper */}
          <div className="pt-12 border-t border-slate-200 mt-auto">
            <div className="flex justify-between text-xs font-bold text-slate-400 uppercase tracking-widest">
              <span>*** END OF QUESTION PAPER ***</span>
              <span>Page 1 of 1</span>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { Button } from '@/components/ui/Button';
import { Loader2, DownloadIcon, Trash2, FileText, AlertCircle } from 'lucide-react';
import { toast } from 'react-hot-toast';
import api from '@/lib/api';

export default function BackupManager() {
  const [backups, setBackups] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isDeleting, setIsDeleting] = useState<string | null>(null);

  const fetchBackups = async () => {
    try {
      setIsLoading(true);
      const res = await api.get('/settings/backups');
      if (res.data.success) {
        setBackups(res.data.data || []);
      }
    } catch (error: any) {
      toast.error('Failed to load backups');
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    setTimeout(() => fetchBackups(), 0);
  }, []);

  const handleDownload = (filename: string) => {
    // The browser will handle the download natively
    window.location.assign(`http://localhost:3000/api/settings/backups/download/${filename}`); // Note: Ensure URL is dynamic if needed or use api.defaults.baseURL
  };

  const handleDelete = async (filename: string) => {
    if (!confirm('Are you sure you want to delete this backup?')) return;
    
    try {
      setIsDeleting(filename);
      await api.delete(`/settings/backups/${filename}`);
      toast.success('Backup deleted successfully');
      fetchBackups();
    } catch (error) {
      toast.error('Failed to delete backup');
    } finally {
      setIsDeleting(null);
    }
  };

  if (isLoading) {
    return <div className="flex justify-center p-8"><Loader2 className="animate-spin text-muted-foreground" /></div>;
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h4 className="font-bold text-foreground text-sm">Available Backups</h4>
        <Button variant="outline" size="sm" onClick={fetchBackups}>Refresh</Button>
      </div>
      
      {backups.length === 0 ? (
        <div className="text-center p-8 bg-muted/30 rounded-lg border border-border border-dashed">
          <AlertCircle className="mx-auto text-muted-foreground mb-2" size={24} />
          <p className="text-sm text-muted-foreground">No backups found in the specified directory.</p>
        </div>
      ) : (
        <div className="border border-border rounded-lg overflow-hidden">
          <table className="w-full text-left text-sm">
            <thead className="bg-muted/50 border-b border-border">
              <tr>
                <th className="px-4 py-3 font-medium">Filename</th>
                <th className="px-4 py-3 font-medium">Date Created</th>
                <th className="px-4 py-3 font-medium">Size</th>
                <th className="px-4 py-3 font-medium text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border bg-card">
              {backups.map((backup) => (
                <tr key={backup.filename} className="hover:bg-muted/20 transition-colors">
                  <td className="px-4 py-3 flex items-center gap-2">
                    <FileText size={16} className="text-blue-500" />
                    <span className="font-medium text-slate-700 dark:text-slate-300">{backup.filename}</span>
                  </td>
                  <td className="px-4 py-3 text-muted-foreground">
                    {new Date(backup.createdAt).toLocaleString()}
                  </td>
                  <td className="px-4 py-3 text-muted-foreground">
                    {(backup.size / 1024 / 1024).toFixed(2)} MB
                  </td>
                  <td className="px-4 py-3 text-right">
                    <div className="flex justify-end gap-2">
                      <Button 
                        variant="ghost" 
                        size="sm" 
                        onClick={() => handleDownload(backup.filename)}
                        className="h-8 px-2 text-blue-600 hover:text-blue-700 hover:bg-blue-50"
                      >
                        <DownloadIcon size={14} className="mr-1" /> Download
                      </Button>
                      <Button 
                        variant="ghost" 
                        size="sm" 
                        onClick={() => handleDelete(backup.filename)}
                        disabled={isDeleting === backup.filename}
                        className="h-8 px-2 text-red-600 hover:text-red-700 hover:bg-red-50"
                      >
                        {isDeleting === backup.filename ? <Loader2 size={14} className="animate-spin" /> : <Trash2 size={14} />}
                      </Button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useRef, useState, useEffect } from 'react';
import { Users, Plus, MoreVertical, Search, Camera, Upload, X, Loader2 } from 'lucide-react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { studentSchema, StudentFormData } from '@/lib/validations';
import { useAppSelector } from '@/lib/hooks';
import { selectClasses, selectGenders } from '@/lib/features/configSlice';
import { Input } from '@/components/ui/Input';
import { Select } from '@/components/ui/Select';
import { Button } from '@/components/ui/Button';
import api from '@/lib/api';
import { toast } from 'react-hot-toast';
import Image from 'next/image';

interface StudentFormProps {
  onSubmit: (data: StudentFormData) => void;
  onCancel: () => void;
  initialData?: Partial<StudentFormData>;
  isEditing?: boolean;
  hideClassAndSection?: boolean;
}

export function StudentForm({ 
  onSubmit, 
  onCancel, 
  initialData, 
  isEditing = false,
  hideClassAndSection = false
}: StudentFormProps) {
  const CLASSES = useAppSelector(selectClasses);
  const GENDERS = useAppSelector(selectGenders);
  const [isUploading, setIsUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const {
    register,
    handleSubmit,
    setValue,
    watch,
    formState: { errors },
  } = useForm<StudentFormData>({
    resolver: zodResolver(studentSchema),
    defaultValues: {
      fullName: initialData?.fullName || '',
      studentId: initialData?.studentId || '',
      rollNumber: initialData?.rollNumber || '',
      className: initialData?.className || '',
      section: initialData?.section || '',
      gender: initialData?.gender || 'MALE',
      email: initialData?.email || '',
      phone: initialData?.phone || '',
      parentName: initialData?.parentName || '',
      parentPhone: initialData?.parentPhone || '',
      address: initialData?.address || '',
      bloodGroup: initialData?.bloodGroup || '',
      dateOfBirth: initialData?.dateOfBirth || '',
      admissionDate: initialData?.admissionDate || '',
      profileImage: initialData?.profileImage || '',
    }
  });

  // eslint-disable-next-line react-hooks/incompatible-library
  const watchClass = watch('className');
  const watchSection = watch('section');

  // Reset section when class changes
  useEffect(() => {
    if (watchClass && watchSection) {
      const classObj = CLASSES.find(c => c.value === watchClass);
      const isValidSection = classObj?.sections?.some(s => s.value === watchSection);
      if (!isValidSection) {
        setValue('section', '', { shouldValidate: true });
      }
    }
  }, [watchClass, CLASSES, setValue, watchSection]);

  useEffect(() => {
    // Only auto-generate if we are not editing an existing student
    // and both class and section are selected.
    if (!isEditing && watchClass && watchSection) {
      const fetchCredentials = async () => {
        try {
          const response = await api.get('/students/generate-credentials', {
            params: { className: watchClass, section: watchSection }
          });
          const { studentId, rollNumber } = response.data.data;
          
          setValue('studentId', studentId, { shouldValidate: true });
          setValue('rollNumber', rollNumber, { shouldValidate: true });
        } catch (error) {
          console.error('Failed to generate credentials:', error);
          toast.error('Failed to auto-generate Student ID and Roll Number');
        }
      };

      fetchCredentials();
    }
  }, [watchClass, watchSection, isEditing, setValue]);

  const onSubmitLocal = (data: StudentFormData) => {
    onSubmit(data);
  };

  const profileImage = watch('profileImage' as any);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > 2 * 1024 * 1024) {
      toast.error('Image size must be less than 2MB');
      return;
    }

    const formData = new FormData();
    formData.append('student-photo', file);

    setIsUploading(true);
    try {
      const response = await api.post('students/upload-photo', formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      });
      const imageUrl = response.data.data.imageUrl;
      setValue('profileImage' as any, imageUrl);
      toast.success('Photo uploaded successfully');
    } catch (error: any) {
      console.error('Upload error:', error);
      toast.error(error.response?.data?.message || 'Failed to upload photo');
    } finally {
      setIsUploading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit(onSubmitLocal)} className="space-y-8 pb-4">
      {/* Section 1: Student Information */}
      <div className="space-y-5">
        <div className="flex items-center gap-2 border-b border-slate-100 pb-3">
          <div className="h-8 w-8 bg-blue-50 text-blue-600 rounded-lg flex items-center justify-center shrink-0">
            <Users size={18} />
          </div>
          <h3 className="text-base font-bold text-slate-900">Student Identity</h3>
        </div>

        <div className="flex flex-col sm:flex-row gap-6 items-start sm:items-center bg-slate-50/50 p-4 rounded-2xl border border-slate-100">
          <div className="relative group">
            <div className="h-24 w-24 rounded-2xl bg-white border-2 border-dashed border-slate-200 flex flex-col items-center justify-center text-slate-400 overflow-hidden relative shadow-sm">
              {profileImage ? (
                <Image 
                  src={profileImage} 
                  alt="Profile" 
                  fill 
                  className="object-cover"
                />
              ) : (
                <Camera size={28} />
              )}
              {isUploading && (
                <div className="absolute inset-0 bg-white/80 flex items-center justify-center">
                  <Loader2 size={24} className="animate-spin text-primary" />
                </div>
              )}
            </div>
            {profileImage && !isUploading && (
              <button
                type="button"
                onClick={() => setValue('profileImage' as any, '')}
                className="absolute -top-2 -right-2 h-6 w-6 bg-red-500 text-white rounded-full flex items-center justify-center shadow-lg hover:bg-red-600 transition-colors"
              >
                <X size={14} />
              </button>
            )}
          </div>
          
          <div className="space-y-2">
            <h4 className="text-sm font-bold text-slate-900">Student Profile Photo</h4>
            <p className="text-xs text-slate-500 max-w-[200px]">Upload a clear passport-sized photo. Max size 2MB (JPG, PNG).</p>
            <input 
              type="file"
              ref={fileInputRef}
              onChange={handleImageUpload}
              className="hidden"
              accept="image/*"
            />
            <Button 
              type="button" 
              variant="outline" 
              size="sm" 
              onClick={() => fileInputRef.current?.click()}
              disabled={isUploading}
              className="gap-2 h-9 text-xs font-bold"
            >
              <Upload size={14} />
              {profileImage ? 'Change Photo' : 'Upload Photo'}
            </Button>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-4">
          <div className="md:col-span-2">
            <Input 
              label="Full Name *"
              placeholder="e.g. Johnathan Doe"
              {...register('fullName')}
              error={errors.fullName?.message}
            />
          </div>
          <Select
            label="Gender *"
            placeholder="Select gender"
            {...register('gender')}
            error={errors.gender?.message}
            options={GENDERS}
          />
          <Input 
            label="Date of Birth"
            type="date"
            {...register('dateOfBirth')}
            error={errors.dateOfBirth?.message}
          />
          <Input 
            label="Blood Group"
            placeholder="e.g. O+"
            {...register('bloodGroup')}
            error={errors.bloodGroup?.message}
          />
        </div>
      </div>

      {/* Section 2: Academic Information */}
      <div className="space-y-5">
        <div className="flex items-center gap-2 border-b border-slate-100 pb-3">
          <div className="h-8 w-8 bg-emerald-50 text-emerald-600 rounded-lg flex items-center justify-center shrink-0">
            <Plus size={18} />
          </div>
          <h3 className="text-base font-bold text-slate-900">Academic Records</h3>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-4">
          <Input 
            label="Official Student ID *"
            placeholder="STU-00000"
            {...register('studentId')}
            error={errors.studentId?.message}
          />
          <Input 
            label="Class Roll Number *"
            placeholder="e.g. 10"
            {...register('rollNumber')}
            error={errors.rollNumber?.message}
          />
          
          {!hideClassAndSection && (
            <>
              <Select
                label="Assigned Class *"
                placeholder="Choose a class"
                {...register('className')}
                error={errors.className?.message}
                options={CLASSES}
              />
              <Select
                label="Section/Group *"
                placeholder="Choose a section"
                {...register('section')}
                error={errors.section?.message}
                options={CLASSES.find(c => c.value === watchClass)?.sections || []}
                disabled={!watchClass}
              />
            </>
          )}

          <div className="md:col-span-2">
            <Input 
              label="Admission Date"
              type="date"
              {...register('admissionDate')}
              error={errors.admissionDate?.message}
            />
          </div>
        </div>
      </div>

      {/* Section 3: Guardian Details */}
      <div className="space-y-5">
        <div className="flex items-center gap-2 border-b border-slate-100 pb-3">
          <div className="h-8 w-8 bg-amber-50 text-amber-600 rounded-lg flex items-center justify-center shrink-0">
            <MoreVertical size={18} />
          </div>
          <h3 className="text-base font-bold text-slate-900">Guardian Information</h3>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-4">
          <Input 
            label="Parent/Guardian Name"
            placeholder="Jane Doe"
            {...register('parentName')}
            error={errors.parentName?.message}
          />
          <Input 
            label="Guardian Contact Number"
            placeholder="+1 000-000-000"
            {...register('parentPhone')}
            error={errors.parentPhone?.message}
          />
        </div>
      </div>

      {/* Section 4: Contact Info */}
      <div className="space-y-5">
        <div className="flex items-center gap-2 border-b border-slate-100 pb-3">
          <div className="h-8 w-8 bg-slate-50 text-slate-600 rounded-lg flex items-center justify-center shrink-0">
            <Search size={18} />
          </div>
          <h3 className="text-base font-bold text-slate-900">Contact & Communication</h3>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-4">
          <Input 
            label="Personal Email Address"
            type="email"
            placeholder="john@example.com"
            {...register('email')}
            error={errors.email?.message}
          />
          <Input 
            label="Primary Phone Number"
            placeholder="+1 000-000-000"
            {...register('phone')}
            error={errors.phone?.message}
          />
          <div className="md:col-span-2">
            <Input 
              label="Residential Address"
              placeholder="Complete street address, city, and zip"
              {...register('address')}
              error={errors.address?.message}
            />
          </div>
        </div>
      </div>

      <div className="flex flex-col sm:flex-row justify-end gap-3 pt-6 border-t border-slate-100">
        <Button type="button" variant="outline" onClick={onCancel} className="w-full sm:w-auto min-h-[44px]">
          Cancel
        </Button>
        <Button type="submit" className="w-full sm:w-auto px-8 shadow-lg shadow-blue-100 min-h-[44px]">
          {isEditing ? 'Update Records' : 'Confirm Registration'}
        </Button>
      </div>
    </form>
  );
}

import React from 'react';
import { Loader2 } from 'lucide-react';
import { motion } from 'framer-motion';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'outline' | 'ghost' | 'soft';
  size?: 'sm' | 'md' | 'lg' | 'icon';
  loading?: boolean;
}

export function Button({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  className = '', 
  loading = false,
  disabled,
  ...props 
}: ButtonProps) {
  const baseStyles = 'inline-flex items-center justify-center rounded-xl font-bold transition-all duration-300 focus:outline-none focus:ring-4 focus:ring-primary/20 disabled:opacity-50 disabled:cursor-not-allowed';
  
  const variants = {
    primary: 'bg-primary text-white hover:opacity-90 shadow-md hover:shadow-lg shadow-primary/20 active:scale-[0.98]',
    secondary: 'bg-slate-800 text-white hover:bg-slate-900 shadow-md active:scale-[0.98]',
    outline: 'bg-transparent border-2 border-slate-200 text-slate-700 hover:border-slate-300 hover:bg-slate-50 active:scale-[0.98]',
    danger: 'bg-red-500 text-white hover:bg-red-600 shadow-md shadow-red-500/20 active:scale-[0.98]',
    ghost: 'bg-transparent text-slate-500 hover:text-slate-900 hover:bg-slate-100 active:scale-[0.98]',
    soft: 'bg-primary/10 text-primary hover:bg-primary/20 active:scale-[0.98]',
  };

  const sizes = {
    sm: 'px-4 py-2 text-xs gap-1.5',
    md: 'px-5 py-2.5 text-sm gap-2',
    lg: 'px-6 py-3 text-sm gap-2.5',
    icon: 'p-2.5',
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${className}`}
      disabled={disabled || loading}
      {...props}
    >
      {loading && <Loader2 className="w-4 h-4 animate-spin mr-2" />}
      {children}
    </button>
  );
}

'use client';

import React, { useState, useRef } from 'react';
import { Button } from './Button';
import { Upload, Download, FileText, CheckCircle2, AlertCircle, Loader2, X } from 'lucide-react';
import { toast } from 'react-hot-toast';
import api from '@/lib/api';

interface CSVImporterProps {
  type: 'students' | 'staff' | 'books';
  onSuccess?: () => void;
  onClose?: () => void;
}

export function CSVImporter({ type, onSuccess, onClose }: CSVImporterProps) {
  const [file, setFile] = useState<File | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [result, setResult] = useState<{
    total: number;
    success: number;
    failed: number;
    errors: { row: number; errors: string[] }[];
  } | null>(null);
  
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const selectedFile = e.target.files[0];
      if (selectedFile.name.endsWith('.csv')) {
        setFile(selectedFile);
        setResult(null);
      } else {
        toast.error('Please select a valid CSV file');
      }
    }
  };

  const handleUpload = async () => {
    if (!file) return;

    try {
      setIsUploading(true);
      const formData = new FormData();
      formData.append('file', file);

      const res = await api.post(`/import/${type}`, formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });

      if (res.data.success) {
        setResult(res.data.data);
        toast.success(`Import completed: ${res.data.data.success} successful`);
        if (onSuccess) onSuccess();
      }
    } catch (error: any) {
      toast.error(error.response?.data?.message || 'Import failed');
    } finally {
      setIsUploading(false);
    }
  };

  const downloadTemplate = () => {
    window.location.href = `${process.env.NEXT_PUBLIC_API_URL || 'http://localhost:5000/api'}/import/template/${type}`;
  };

  return (
    <div className="bg-card border border-border rounded-xl p-6 shadow-sm">
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <div className="p-2 rounded-lg bg-primary/10 text-primary">
            <Upload size={20} />
          </div>
          <div>
            <h3 className="text-lg font-bold text-foreground capitalize">Import {type}</h3>
            <p className="text-xs text-muted-foreground">Bulk upload data using a CSV file</p>
          </div>
        </div>
        {onClose && (
          <button onClick={onClose} className="p-2 hover:bg-muted rounded-full transition-colors">
            <X size={18} />
          </button>
        )}
      </div>

      {!result ? (
        <div className="space-y-6">
          <div 
            onClick={() => fileInputRef.current?.click()}
            className={`
              border-2 border-dashed rounded-xl p-10 flex flex-col items-center justify-center gap-3 cursor-pointer transition-all
              ${file ? 'border-primary bg-primary/5' : 'border-border hover:border-primary/50 hover:bg-muted/50'}
            `}
          >
            <input 
              type="file" 
              ref={fileInputRef} 
              onChange={handleFileChange} 
              className="hidden" 
              accept=".csv"
            />
            {file ? (
              <>
                <FileText size={40} className="text-primary" />
                <span className="text-sm font-bold text-foreground">{file.name}</span>
                <span className="text-xs text-muted-foreground">{(file.size / 1024).toFixed(2)} KB</span>
              </>
            ) : (
              <>
                <div className="p-3 rounded-full bg-muted">
                   <Upload size={24} className="text-muted-foreground" />
                </div>
                <span className="text-sm font-medium text-foreground">Click to browse or drag and drop</span>
                <span className="text-xs text-muted-foreground">Only .csv files are supported</span>
              </>
            )}
          </div>

          <div className="flex flex-col sm:flex-row gap-3">
            <Button 
              variant="outline" 
              onClick={downloadTemplate}
              className="flex-1"
            >
              <Download size={16} className="mr-2" /> Download Template
            </Button>
            <Button 
              onClick={handleUpload}
              disabled={!file || isUploading}
              className="flex-1"
            >
              {isUploading ? (
                <>
                  <Loader2 size={16} className="mr-2 animate-spin" /> Processing...
                </>
              ) : (
                <>
                  <CheckCircle2 size={16} className="mr-2" /> Start Import
                </>
              )}
            </Button>
          </div>
        </div>
      ) : (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-300">
          <div className="grid grid-cols-3 gap-4">
             <div className="p-4 rounded-xl bg-slate-50 dark:bg-slate-900 border border-border text-center">
                <span className="block text-[10px] uppercase font-bold text-muted-foreground mb-1">Total</span>
                <span className="text-2xl font-black text-foreground">{result.total}</span>
             </div>
             <div className="p-4 rounded-xl bg-green-50 dark:bg-green-900/20 border border-green-100 dark:border-green-900/30 text-center">
                <span className="block text-[10px] uppercase font-bold text-green-600 mb-1">Success</span>
                <span className="text-2xl font-black text-green-600">{result.success}</span>
             </div>
             <div className="p-4 rounded-xl bg-red-50 dark:bg-red-900/20 border border-red-100 dark:border-red-900/30 text-center">
                <span className="block text-[10px] uppercase font-bold text-red-600 mb-1">Failed</span>
                <span className="text-2xl font-black text-red-600">{result.failed}</span>
             </div>
          </div>

          {result.errors.length > 0 && (
            <div className="max-h-64 overflow-y-auto border border-border rounded-xl divide-y divide-border">
              {result.errors.map((err, i) => (
                <div key={i} className="p-3 flex items-start gap-3 bg-red-50/30 dark:bg-red-900/10">
                   <AlertCircle size={16} className="text-red-500 mt-0.5 shrink-0" />
                   <div>
                      <span className="text-xs font-bold text-red-700 dark:text-red-400">Row {err.row}</span>
                      <ul className="mt-1 list-disc list-inside space-y-0.5">
                        {err.errors.map((msg, j) => (
                          <li key={j} className="text-[11px] text-red-600 dark:text-red-300">{msg}</li>
                        ))}
                      </ul>
                   </div>
                </div>
              ))}
            </div>
          )}

          <Button 
            variant="ghost" 
            className="w-full"
            onClick={() => {
              setResult(null);
              setFile(null);
            }}
          >
            Import Another File
          </Button>
        </div>
      )}
    </div>
  );
}

import React from 'react';
import { motion, HTMLMotionProps } from 'framer-motion';

interface CardProps extends React.HTMLAttributes<HTMLDivElement> {
  variant?: 'default' | 'outline' | 'glass' | 'elevated';
  isHoverable?: boolean;
}

export function Card({ children, className = '', variant = 'default', isHoverable = false, ...props }: CardProps) {
  const variants = {
    default: 'bg-card text-card-foreground shadow-sm border border-border',
    outline: 'bg-transparent border border-border hover:bg-slate-50/50 transition-colors',
    glass: 'bg-white/70 dark:bg-slate-900/70 backdrop-blur-md border border-white/20 shadow-sm',
    elevated: 'bg-white shadow-lg shadow-slate-200/40 border-none',
  };

  const hoverClass = isHoverable ? 'hover:shadow-xl hover:-translate-y-1 transition-all duration-300' : '';

  return (
    <div 
      className={`
        rounded-2xl p-6
        ${variants[variant]}
        ${hoverClass}
        ${className}
      `}
      {...props}
    >
      {children}
    </div>
  );
}

export function CardHeader({ children, className = '' }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={`mb-6 flex flex-col gap-1.5 bg-inherit ${className}`}>{children}</div>;
}

export function CardTitle({ children, className = '' }: React.HTMLAttributes<HTMLHeadingElement>) {
